def _now_ms():
    return int(time.time() * 1000)


def _read_group_data():
    if not os.path.exists(GROUP_DATA_FILE):
        return {"groups": {}, "invite_index": {}}
    try:
        with open(GROUP_DATA_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError("invalid group data")
        data.setdefault("groups", {})
        data.setdefault("invite_index", {})
        return data
    except Exception as exc:
        print(f"[GroupChat] failed to read data: {exc}")
        return {"groups": {}, "invite_index": {}}


def _write_group_data(data):
    tmp_path = GROUP_DATA_FILE + ".tmp"
    os.makedirs(os.path.dirname(GROUP_DATA_FILE), exist_ok=True)
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
    os.replace(tmp_path, GROUP_DATA_FILE)


def _memory_now_ms():
    return _now_ms()


class _MemoryDbLockAttempt:
    def __init__(self, timeout_ms=None):
        self.timeout_ms = MEMORY_READ_LOCK_WAIT_MS if timeout_ms is None else int(timeout_ms)
        self.acquired = False

    def __enter__(self):
        timeout = max(0.0, float(self.timeout_ms or 0) / 1000.0)
        self.acquired = MEMORY_DB_LOCK.acquire(timeout=timeout)
        return self.acquired

    def __exit__(self, exc_type, exc, tb):
        if self.acquired:
            MEMORY_DB_LOCK.release()
        return False


def _memory_connect():
    os.makedirs(os.path.dirname(MEMORY_DB_FILE), exist_ok=True)
    conn = sqlite3.connect(MEMORY_DB_FILE, timeout=20)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    conn.execute("PRAGMA foreign_keys=ON")
    return conn


def _memory_ensure_column(conn, table, column, definition):
    existing = {row["name"] for row in conn.execute(f"PRAGMA table_info({table})").fetchall()}
    if column not in existing:
        conn.execute(f"ALTER TABLE {table} ADD COLUMN {column} {definition}")


