def _memory_normalize_user(payload):
    user = payload.get("user") if isinstance(payload.get("user"), dict) else payload
    user = user if isinstance(user, dict) else {}
    user_id = str(user.get("id") or user.get("user_id") or "").strip()
    email = str(user.get("email") or "").strip().lower()
    name = str(user.get("name") or user.get("display_name") or "").strip()
    logged_in = bool(payload.get("logged_in") or payload.get("loggedIn") or user.get("logged_in") or user.get("loggedIn"))
    if not logged_in and (email or (user_id and user_id != "local-user")):
        logged_in = True
    if not logged_in or (not user_id and not email):
        return {"user_key": "", "display_name": name or "local", "persist": False}
    identity = f"{user_id}|{email}".strip("|")
    user_key = hashlib.sha256(identity.encode("utf-8")).hexdigest()
    return {"user_key": user_key, "display_name": name or email.split("@")[0] if email else name, "persist": True}


