def _normalize_favicon_domain(value):
    raw = (value or "").strip()
    if not raw:
        return ""
    if raw.startswith(("http://", "https://")):
        try:
            raw = urlparse(raw).hostname or ""
        except Exception:
            raw = ""
    raw = raw.split("/")[0].split(":")[0].lower().strip(".")
    if raw.startswith("www."):
        raw = raw[4:]
    if not raw or len(raw) > 253:
        return ""
    if not re.fullmatch(r"[a-z0-9.-]+", raw):
        return ""
    try:
        ip = ipaddress.ip_address(raw)
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved:
            return ""
    except ValueError:
        pass
    return raw


def _favicon_domain_candidates(domain):
    normalized = _normalize_favicon_domain(domain)
    if not normalized:
        return []
    candidates = [normalized]
    parts = normalized.split(".")
    if len(parts) > 2:
        parent = ".".join(parts[-2:])
        if parent not in candidates:
            candidates.append(parent)
        if len(parts) > 3 and parts[-2] in {"com", "net", "org", "gov", "edu", "co"}:
            parent3 = ".".join(parts[-3:])
            if parent3 not in candidates:
                candidates.append(parent3)
    return candidates


def _favicon_cache_paths(domain, size):
    os.makedirs(FAVICON_CACHE_DIR, exist_ok=True)
    digest = hashlib.sha256(f"{domain}|{size}".encode("utf-8")).hexdigest()[:32]
    return (
        os.path.join(FAVICON_CACHE_DIR, digest + ".bin"),
        os.path.join(FAVICON_CACHE_DIR, digest + ".json"),
    )


def _favicon_content_path(content_hash):
    safe_hash = re.sub(r"[^a-f0-9]", "", str(content_hash or "").lower())[:64]
    if not safe_hash:
        return ""
    return os.path.join(FAVICON_CACHE_DIR, f"data_{safe_hash}.bin")


def _read_favicon_cache_exact(domain, size):
    data_path, meta_path = _favicon_cache_paths(domain, size)
    try:
        if not os.path.exists(meta_path):
            return None
        with open(meta_path, "r", encoding="utf-8") as f:
            meta = json.load(f)
        ref_path = ""
        if meta.get("content_hash"):
            ref_path = _favicon_content_path(meta.get("content_hash"))
        if ref_path and os.path.exists(ref_path):
            data_path = ref_path
        elif not os.path.exists(data_path):
            return None
        if time.time() - os.path.getmtime(meta_path) > FAVICON_CACHE_TTL_SECONDS:
            return None
        if time.time() - os.path.getmtime(data_path) > FAVICON_CACHE_TTL_SECONDS:
            return None
        with open(data_path, "rb") as f:
            data = f.read()
        if not data:
            return None
        now = time.time()
        try:
            os.utime(meta_path, (now, now))
            os.utime(data_path, (now, now))
        except Exception:
            pass
        return data, meta.get("content_type") or "image/x-icon"
    except Exception:
        return None


def _read_favicon_cache(domain, size):
    normalized = _normalize_favicon_domain(domain)
    for candidate in _favicon_domain_candidates(normalized):
        cached = _read_favicon_cache_exact(candidate, size)
        if cached:
            if candidate != normalized:
                try:
                    data, content_type = cached
                    _write_favicon_cache(normalized, size, data, content_type, alias_of=candidate)
                except Exception:
                    pass
            return cached
    return None


def _prune_favicon_cache():
    try:
        now = time.time()
        metas = []
        referenced = set()
        for name in os.listdir(FAVICON_CACHE_DIR):
            if not name.endswith(".json"):
                continue
            meta_path = os.path.join(FAVICON_CACHE_DIR, name)
            try:
                with open(meta_path, "r", encoding="utf-8") as f:
                    meta = json.load(f)
                mtime = os.path.getmtime(meta_path)
                content_hash = meta.get("content_hash") or ""
                data_path = _favicon_content_path(content_hash) if content_hash else meta_path[:-5] + ".bin"
                size = os.path.getsize(data_path) if os.path.exists(data_path) else 0
                expired = now - mtime > FAVICON_CACHE_TTL_SECONDS
                metas.append({"meta_path": meta_path, "data_path": data_path, "mtime": mtime, "size": size, "expired": expired})
                if content_hash and not expired:
                    referenced.add(os.path.abspath(data_path))
            except Exception:
                continue

        for item in metas:
            if item["expired"]:
                try:
                    os.remove(item["meta_path"])
                except Exception:
                    pass

        active = [item for item in metas if not item["expired"]]
        active.sort(key=lambda item: item["mtime"], reverse=True)
        for item in active[FAVICON_CACHE_MAX_ITEMS:]:
            try:
                os.remove(item["meta_path"])
            except Exception:
                pass

        referenced = set()
        active = active[:FAVICON_CACHE_MAX_ITEMS]
        for item in active:
            if os.path.basename(item["data_path"]).startswith("data_"):
                referenced.add(os.path.abspath(item["data_path"]))

        total = 0
        data_files = []
        for name in os.listdir(FAVICON_CACHE_DIR):
            if not (name.startswith("data_") and name.endswith(".bin")):
                continue
            path = os.path.join(FAVICON_CACHE_DIR, name)
            try:
                size = os.path.getsize(path)
                total += size
                data_files.append((os.path.getmtime(path), size, path))
            except Exception:
                continue

        for _mtime, size, path in sorted(data_files):
            if os.path.abspath(path) not in referenced:
                try:
                    os.remove(path)
                    total -= size
                except Exception:
                    pass

        if total > FAVICON_CACHE_MAX_BYTES:
            for _mtime, size, path in sorted(data_files):
                if total <= FAVICON_CACHE_MAX_BYTES:
                    break
                try:
                    os.remove(path)
                    total -= size
                except Exception:
                    pass
    except Exception:
        pass


def _write_favicon_cache(domain, size, data, content_type, alias_of=""):
    data_path, meta_path = _favicon_cache_paths(domain, size)
    content_hash = hashlib.sha256(data).hexdigest()
    shared_data_path = _favicon_content_path(content_hash)
    tmp_data = data_path + ".tmp"
    tmp_meta = meta_path + ".tmp"
    tmp_shared = shared_data_path + ".tmp"
    if not os.path.exists(shared_data_path):
        with open(tmp_shared, "wb") as f:
            f.write(data)
        os.replace(tmp_shared, shared_data_path)
    with open(tmp_meta, "w", encoding="utf-8") as f:
        json.dump({
            "content_type": content_type or "image/x-icon",
            "created_at": time.time(),
            "domain": domain,
            "size": size,
            "content_hash": content_hash,
            "bytes": len(data),
            "alias_of": alias_of or "",
        }, f, ensure_ascii=False, separators=(",", ":"))
    # Keep a tiny compatibility copy for caches created before content-hash dedupe.
    if not os.path.exists(data_path):
        with open(tmp_data, "wb") as f:
            f.write(data)
        os.replace(tmp_data, data_path)
    os.replace(tmp_meta, meta_path)
    _prune_favicon_cache()


def _fetch_favicon_candidate(url, timeout=2.2):
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 (compatible; BlanketFavicon/1.0)",
            "Accept": "image/avif,image/webp,image/png,image/svg+xml,image/*,*/*;q=0.8",
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        content_type = (resp.headers.get("Content-Type") or "image/x-icon").split(";")[0].strip()
        data = resp.read(70000)
    if not data or len(data) > 65000:
        return None
    if not (content_type.startswith("image/") or data[:5].lower() == b"<svg "):
        return None
    if data.lstrip().startswith(b"<svg"):
        content_type = "image/svg+xml"
    return data, content_type or "image/x-icon"


def _favicon_site_icon_urls(domain):
    urls = [
        f"https://{domain}/favicon.ico",
        f"https://{domain}/apple-touch-icon.png",
        f"https://{domain}/apple-touch-icon-precomposed.png",
    ]
    try:
        req = urllib.request.Request(
            f"https://{domain}/",
            headers={
                "User-Agent": "Mozilla/5.0 (compatible; BlanketFavicon/1.0)",
                "Accept": "text/html,application/xhtml+xml",
            },
        )
        with urllib.request.urlopen(req, timeout=2.2) as resp:
            html = resp.read(120000).decode("utf-8", errors="ignore")
        if BeautifulSoup is not None:
            soup = BeautifulSoup(html, "html.parser")
            for link in soup.find_all("link"):
                rel = " ".join(link.get("rel") or []).lower()
                href = (link.get("href") or "").strip()
                if href and any(word in rel for word in ("icon", "apple-touch-icon", "shortcut icon")):
                    urls.append(urljoin(f"https://{domain}/", href))
        else:
            for match in re.finditer(r'<link[^>]+(?:rel=["\'][^"\']*icon[^"\']*["\'][^>]+href=["\']([^"\']+)["\']|href=["\']([^"\']+)["\'][^>]+rel=["\'][^"\']*icon[^"\']*["\'])', html, re.I):
                href = (match.group(1) or match.group(2) or "").strip()
                if href:
                    urls.append(urljoin(f"https://{domain}/", href))
    except Exception:
        pass
    urls.extend([
        f"http://{domain}/favicon.ico",
        f"http://{domain}/apple-touch-icon.png",
    ])
    aggregators = [
        item.strip()
        for item in os.environ.get("LONGCAT_FAVICON_AGGREGATORS", "").split(",")
        if item.strip()
    ]
    for template in aggregators:
        try:
            urls.append(template.format(domain=quote(domain), size=32))
        except Exception:
            continue
    seen = set()
    result = []
    for url in urls:
        if url not in seen:
            seen.add(url)
            result.append(url)
    return result


def _normalize_group_user(payload):
    user = payload.get("user") if isinstance(payload.get("user"), dict) else payload
    user_id = str(user.get("id") or user.get("user_id") or user.get("email") or "").strip()
    email = str(user.get("email") or "").strip()
    name = str(user.get("name") or user.get("display_name") or "").strip()
    if not name:
        name = email.split("@", 1)[0] if email else "成员"
    if not user_id:
        user_id = email or f"anon-{hashlib.sha1(name.encode('utf-8')).hexdigest()[:12]}"
    return {
        "id": user_id[:160],
        "email": email[:240],
        "name": name[:80],
    }


def _is_authenticated_group_user(user):
    user_id = str((user or {}).get("id") or "").strip()
    email = str((user or {}).get("email") or "").strip()
    if not user_id:
        return False
    if user_id == "local-user" or user_id.startswith("anon-"):
        return False
    if not email and user_id in {"成员", "blkters", "blanket", "Akira"}:
        return False
    return True


def _reject_anonymous_group_user(user):
    if _is_authenticated_group_user(user):
        return None
    return jsonify({"success": False, "error": "请先登录后再使用群聊"}), 401


def _public_group(group):
    return {
        "id": group.get("id"),
        "title": group.get("title") or "未命名群聊",
        "desc": group.get("desc") or "",
        "inviteCode": group.get("invite_code") or "",
        "createdAt": group.get("created_at") or _now_ms(),
        "updatedAt": group.get("updated_at") or group.get("created_at") or _now_ms(),
        "memberCount": len(group.get("members") or {}),
    }


def _require_group_member(group, user):
    members = group.setdefault("members", {})
    return user.get("id") in members


def _add_group_member(group, user):
    members = group.setdefault("members", {})
    is_new_member = user["id"] not in members
    members[user["id"]] = {
        "id": user["id"],
        "email": user.get("email") or "",
        "name": user.get("name") or "成员",
        "joined_at": members.get(user["id"], {}).get("joined_at") or _now_ms(),
    }
    return is_new_member


def _append_group_system_message(group, content, now=None):
    now = now or _now_ms()
    message = {
        "id": f"msg_{uuid.uuid4().hex}",
        "groupId": group.get("id"),
        "role": "assistant",
        "content": content,
        "senderId": "longcat-ai",
        "senderName": "LongCat",
        "createdAt": now,
        "system": True,
    }
    group.setdefault("messages", []).append(message)
    group["messages"] = group["messages"][-1000:]
    group["updated_at"] = now
    return message


