def _load_secret(name):
    """Decrypt and return a named secret from .secrets (Fernet-encrypted)."""
    import json as _j
    kf = os.path.join(BASE_DIR, '.secret_key')
    sf = os.path.join(BASE_DIR, '.secrets')
    if _FERNET_OK and os.path.exists(kf) and os.path.exists(sf):
        try:
            with open(kf, 'rb') as f:
                fn = _Fernet(f.read().strip())
            with open(sf, 'r', encoding='utf-8') as f:
                store = _j.load(f)
            tok = store.get(name)
            if tok:
                return fn.decrypt(tok.encode()).decode()
        except Exception as e:
            print(f'[Secrets] Failed to load {name!r}: {e}')
    return os.environ.get(name, '')


def _load_plain_secret(filename):
    path = os.path.join(BASE_DIR, filename)
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return f.read().strip()
    except Exception as e:
        print(f"[Secrets] Failed to load {filename!r}: {e}")
    return ""


def _normalize_api_host(host, fallback):
    value = (host or fallback or "").strip()
    if not value:
        value = fallback
    if value and not value.startswith(("http://", "https://")):
        value = "https://" + value
    return value.rstrip("/")


