def _split_longcat_keys(raw):
    keys = []
    for item in re.split(r"[\s,;]+", raw or ""):
        key = item.strip()
        if key:
            keys.append(key)
    return keys


def _longcat_default_api_keys():
    keys = []
    if LONGCAT_PROXY_KEY_FILE and os.path.exists(LONGCAT_PROXY_KEY_FILE):
        try:
            with open(LONGCAT_PROXY_KEY_FILE, "r", encoding="utf-8") as handle:
                keys.extend(_split_longcat_keys(handle.read()))
        except OSError as exc:
            print(f"[LongCat Proxy] failed to read API key file: {exc}")
    if not keys:
        keys.extend(_split_longcat_keys(os.environ.get("LONGCAT_API_KEY") or ""))
    return keys[:1]


def _longcat_proxy_keys(custom_key=""):
    custom_key = (custom_key or "").strip()
    if custom_key:
        return [custom_key]
    return _longcat_default_api_keys()


def _get_system_proxy():
    if os.environ.get("HTTP_PROXY") or os.environ.get("HTTPS_PROXY") or os.environ.get("ALL_PROXY"):
        return None
    if sys.platform == "win32":
        try:
            import winreg
            reg = winreg.ConnectRegistry(None, winreg.HKEY_CURRENT_USER)
            key = winreg.OpenKey(reg, r"Software\Microsoft\Windows\CurrentVersion\Internet Settings")
            proxy_enable, _ = winreg.QueryValueEx(key, "ProxyEnable")
            proxy_server, _ = winreg.QueryValueEx(key, "ProxyServer")
            if proxy_enable and proxy_server:
                p_str = str(proxy_server).strip()
                if ";" in p_str:
                    parts = p_str.split(";")
                    for part in parts:
                        if part.startswith("https="):
                            return "http://" + part[6:]
                        if part.startswith("http="):
                            return "http://" + part[5:]
                if not p_str.startswith("http://") and not p_str.startswith("https://"):
                    return f"http://{p_str}"
                return p_str
        except Exception:
            pass
    return None

# Global HTTPX Client for Connection Pooling
_system_proxy = _get_system_proxy()
if _system_proxy:
    _httpx_client = httpx.Client(
        proxy=_system_proxy,
        limits=httpx.Limits(max_connections=100, max_keepalive_connections=20),
        timeout=httpx.Timeout(10.0, read=60.0, write=20.0, connect=10.0)
    )
else:
    _httpx_client = httpx.Client(
        limits=httpx.Limits(max_connections=100, max_keepalive_connections=20),
        timeout=httpx.Timeout(10.0, read=60.0, write=20.0, connect=10.0)
    )

if _system_proxy:
    _httpx_async_client = httpx.AsyncClient(
        proxy=_system_proxy,
        limits=httpx.Limits(max_connections=100, max_keepalive_connections=20),
        timeout=httpx.Timeout(10.0, read=60.0, write=20.0, connect=10.0)
    )
else:
    _httpx_async_client = httpx.AsyncClient(
        limits=httpx.Limits(max_connections=100, max_keepalive_connections=20),
        timeout=httpx.Timeout(10.0, read=60.0, write=20.0, connect=10.0)
    )


async def _close_longcat_async_client():
    await _httpx_async_client.aclose()

class HttpxStreamWrapper:
    def __init__(self, client, method, url, **kwargs):
        self.client = client
        self.method = method
        self.url = url
        self.kwargs = kwargs
        self.stream_ctx = None
        self.response = None
        self.iter_bytes = None
        self._buffer = b""

    def __enter__(self):
        if self.response is None:
            self.stream_ctx = self.client.stream(self.method, self.url, **self.kwargs)
            self.response = self.stream_ctx.__enter__()
            if self.response.status_code >= 400:
                error_body = self.response.read()
                fp = io.BytesIO(error_body)
                import urllib.error
                from urllib.message import Message
                headers = Message()
                for k, v in self.response.headers.items():
                    headers.add_header(k, v)
                raise urllib.error.HTTPError(
                    self.url,
                    self.response.status_code,
                    self.response.reason_phrase,
                    headers,
                    fp
                )
            self.iter_bytes = self.response.iter_bytes()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.stream_ctx:
            self.stream_ctx.__exit__(exc_type, exc_val, exc_tb)

    @property
    def status(self):
        return self.response.status_code

    @property
    def code(self):
        return self.response.status_code

    @property
    def headers(self):
        return self.response.headers

    def read(self, n=None):
        if n is None:
            chunks = [self._buffer]
            self._buffer = b""
            for chunk in self.iter_bytes:
                chunks.append(chunk)
            return b"".join(chunks)
        else:
            while len(self._buffer) < n:
                try:
                    chunk = next(self.iter_bytes)
                    if not chunk:
                        break
                    self._buffer += chunk
                except StopIteration:
                    break
            res = self._buffer[:n]
            self._buffer = self._buffer[n:]
            return res

    def read1(self, n=8192):
        if self._buffer:
            res = self._buffer[:n]
            self._buffer = self._buffer[n:]
            return res
        try:
            chunk = next(self.iter_bytes)
            if len(chunk) > n:
                self._buffer = chunk[n:]
                return chunk[:n]
            return chunk
        except StopIteration:
            return b""

    def readline(self):
        while b"\n" not in self._buffer:
            try:
                chunk = next(self.iter_bytes)
                if not chunk:
                    break
                self._buffer += chunk
            except StopIteration:
                break
        if b"\n" in self._buffer:
            idx = self._buffer.index(b"\n") + 1
            line = self._buffer[:idx]
            self._buffer = self._buffer[idx:]
            return line
        else:
            line = self._buffer
            self._buffer = b""
            return line

    def close(self):
        if self.stream_ctx:
            try:
                self.response.close()
            except Exception:
                pass

def _longcat_proxy_request(payload, key, timeout=None):
    payload = dict(payload or {})
    payload["model"] = LONGCAT_PROXY_MODEL
    wants_stream = bool((payload or {}).get("stream"))
    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream" if wants_stream else "application/json",
        "Accept-Encoding": "identity",
        "Cache-Control": "no-cache",
        "Authorization": f"Bearer {key}",
    }
    
    max_retries = 3
    retry_delay = 1.0
    
    for attempt in range(max_retries):
        try:
            wrapper = HttpxStreamWrapper(
                _httpx_client,
                "POST",
                LONGCAT_PROXY_API_URL,
                json=payload,
                headers=headers,
                timeout=timeout or LONGCAT_PROXY_TIMEOUT_SECONDS
            )
            return wrapper.__enter__()
        except Exception as e:
            import urllib.error
            if isinstance(e, urllib.error.HTTPError):
                if not _longcat_proxy_should_retry(e.code):
                    raise e
            elif hasattr(e, "response") and e.response is not None:
                status_code = getattr(e.response, "status_code", 0)
                if status_code and not _longcat_proxy_should_retry(status_code):
                    raise e
            
            if attempt == max_retries - 1:
                logging.error(f"[LongCat Proxy] Request failed after {max_retries} attempts: {e}")
                raise e
            
            logging.warning(f"[LongCat Proxy] Request failed with {e}. Retrying in {retry_delay}s (attempt {attempt + 1}/{max_retries})...")
            time.sleep(retry_delay)
            retry_delay *= 2


async def _longcat_proxy_stream_payloads_async(payload, key, timeout=None, should_stop=None):
    payload = dict(payload or {})
    payload["model"] = LONGCAT_PROXY_MODEL
    payload["stream"] = True
    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "Accept-Encoding": "identity",
        "Cache-Control": "no-cache",
        "Authorization": f"Bearer {key}",
    }
    max_retries = 3
    retry_delay = 1.0
    last_error = ""
    for attempt in range(max_retries):
        if callable(should_stop) and should_stop():
            return
        try:
            async with _httpx_async_client.stream(
                "POST",
                LONGCAT_PROXY_API_URL,
                json=payload,
                headers=headers,
                timeout=timeout or LONGCAT_PROXY_TIMEOUT_SECONDS,
            ) as response:
                if response.status_code >= 400:
                    body = await response.aread()
                    last_error = body.decode("utf-8", errors="replace") or response.reason_phrase
                    if attempt < max_retries - 1 and _longcat_proxy_should_retry(response.status_code):
                        logging.warning(
                            "[LongCat Proxy] Async stream failed with status %s. Retrying in %.1fs (attempt %s/%s)...",
                            response.status_code,
                            retry_delay,
                            attempt + 1,
                            max_retries,
                        )
                        await asyncio.sleep(retry_delay)
                        retry_delay *= 2
                        continue
                    raise httpx.HTTPStatusError(
                        f"LongCat stream failed with status {response.status_code}: {last_error}",
                        request=response.request,
                        response=response,
                    )

                async for line in response.aiter_lines():
                    if callable(should_stop) and should_stop():
                        return
                    text = str(line or "").strip()
                    if not text or text.startswith(":"):
                        continue
                    if text.startswith("data:"):
                        text = text[5:].strip()
                    if not text:
                        continue
                    if text == "[DONE]":
                        yield {"__done__": True}
                        return
                    try:
                        yield json.loads(text)
                    except Exception:
                        continue
                return
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            last_error = str(exc)
            response = getattr(exc, "response", None)
            status_code = getattr(response, "status_code", 0)
            if status_code and not _longcat_proxy_should_retry(status_code):
                raise
            if attempt >= max_retries - 1:
                logging.error(f"[LongCat Proxy] Async stream failed after {max_retries} attempts: {exc}")
                raise
            logging.warning(
                "[LongCat Proxy] Async stream failed with %s. Retrying in %.1fs (attempt %s/%s)...",
                exc,
                retry_delay,
                attempt + 1,
                max_retries,
            )
            await asyncio.sleep(retry_delay)
            retry_delay *= 2
    if last_error:
        raise RuntimeError(last_error)


def _longcat_proxy_should_retry(status_code):
    return int(status_code or 0) in {401, 402, 403, 408, 409, 425, 429, 500, 502, 503, 504}


def _longcat_error_response(message, status=502):
    return jsonify({
        "success": False,
        "error": message,
    }), status


