# ---------------------------------------------------------------------------
# LongCatContextCompressor — adapted from Hermes agent/context_compressor.py
# ---------------------------------------------------------------------------
# Lightweight context-window compressor for LongCat native agent.
# Replaces simple tail-truncation with:
#   1) Prune old tool results (cheap, no LLM call)
#   2) Protect head + tail messages
#   3) Summarize middle turns via auxiliary LLM call
#   4) Clean up orphaned tool_call / tool_result pairs
# ---------------------------------------------------------------------------

_SUMMARY_PREFIX = (
    "【上文已压缩——仅作背景参考】"
    "以下是对话早期内容的结构化摘要，供你理解对话背景使用。"
    "不要回答摘要中提到的问题（它们已被处理过）。"
    "你的当前任务是看用户最新的消息。"
)
_LEGACY_SUMMARY_PREFIX = "【上文摘要】："
_PRUNED_TOOL_PLACEHOLDER = "【旧工具输出已清除以节省上下文空间】"
_CHARS_PER_TOKEN = 4
_MIN_SUMMARY_TOKENS = 2000
_SUMMARY_RATIO = 0.20
_SUMMARY_TOKENS_CEILING = 12000
_SUMMARY_FAILURE_COOLDOWN_SECONDS = 60


def _lccc_content_length_for_budget(raw_content):
    """Estimate char-length of message content for token budgeting."""
    if isinstance(raw_content, str):
        return len(raw_content)
    if not isinstance(raw_content, list):
        return len(str(raw_content or ""))
    total = 0
    for p in raw_content:
        if isinstance(p, str):
            total += len(p)
        elif isinstance(p, dict):
            ptype = p.get("type")
            if ptype in {"image_url", "input_image", "image"}:
                total += 1600 * _CHARS_PER_TOKEN
            else:
                total += len(p.get("text", "") or "")
        else:
            total += len(str(p))
    return total


def _lccc_content_text_for_contains(content):
    """Best-effort text extraction for substring checks."""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, str):
                parts.append(item)
            elif isinstance(item, dict):
                text = item.get("text")
                if isinstance(text, str):
                    parts.append(text)
        return "\n".join(p for p in parts if p)
    return str(content)


def _lccc_append_text_to_content(content, text, *, prepend=False):
    """Safely append/prepend text to message content."""
    if content is None:
        return text
    if isinstance(content, str):
        return text + content if prepend else content + text
    if isinstance(content, list):
        text_block = {"type": "text", "text": text}
        return [text_block, *content] if prepend else [*content, text_block]
    rendered = str(content)
    return text + rendered if prepend else rendered + text


def _lccc_summarize_tool_result(tool_name, tool_args, tool_content):
    """Create a 1-line summary of a tool call + result."""
    try:
        args = json.loads(tool_args) if tool_args else {}
    except (json.JSONDecodeError, TypeError):
        args = {}
    content = tool_content or ""
    content_len = len(content)
    line_count = content.count("\n") + 1 if content.strip() else 0

    if tool_name == "plan_task":
        goal = args.get("goal", "")
        if len(goal) > 60:
            goal = goal[:57] + "..."
        return f"【plan_task】制定计划：{goal}（{content_len} 字符）"

    if tool_name == "terminal":
        cmd = args.get("command", "")
        if len(cmd) > 80:
            cmd = cmd[:77] + "..."
        return f"【terminal】执行 `{cmd}` → {line_count} 行输出"

    if tool_name == "web_search":
        query = args.get("query", "?")
        return f"【web_search】搜索 '{query}'（{content_len} 字符结果）"

    if tool_name == "web_extract":
        urls = args.get("urls", [])
        url_desc = urls[0] if isinstance(urls, list) and urls else "?"
        return f"【web_extract】{url_desc}（{content_len} 字符）"

    if tool_name == "read_file":
        path = args.get("path", "?")
        return f"【read_file】读取 {path}（{content_len} 字符）"

    if tool_name == "write_file":
        path = args.get("path", "?")
        return f"【write_file】写入 {path}（{content_len} 字符）"

    if tool_name == "patch":
        path = args.get("path", "?")
        return f"【patch】修改 {path}（{content_len} 字符）"

    if tool_name in {"browser_navigate", "browser_click", "browser_snapshot",
                     "browser_type", "browser_scroll", "browser_vision"}:
        url = args.get("url", "")
        return f"【{tool_name}】{url}（{content_len} 字符）"

    first_arg = ""
    for k, v in list(args.items())[:2]:
        sv = str(v)[:40]
        first_arg += f" {k}={sv}"
    return f"【{tool_name}】{first_arg}（{content_len} 字符结果）"


def _lccc_estimate_messages_tokens(messages):
    """Rough token estimate for a list of messages."""
    total = 0
    for msg in messages or []:
        if not isinstance(msg, dict):
            continue
        content = msg.get("content") or ""
        total += _memory_approx_token_count(content) + 4
        for tc in msg.get("tool_calls") or []:
            if isinstance(tc, dict):
                args = tc.get("function", {}).get("arguments", "")
                total += _memory_approx_token_count(args) + 4
    return total


class LongCatContextCompressor:
    """Lightweight context compressor for LongCat native agent.

    Algorithm:
    1. Prune old tool results (cheap, no LLM call)
    2. Protect head messages (system prompt + first exchange)
    3. Protect tail messages by token budget
    4. Summarize middle turns with structured LLM prompt
    5. Clean up orphaned tool_call / tool_result pairs
    """

    def __init__(
        self,
        model=None,
        threshold_percent=0.50,
        protect_first_n=3,
        protect_last_n=6,
        summary_target_ratio=0.20,
    ):
        self.model = model or LONGCAT_PROXY_MODEL
        self.threshold_percent = threshold_percent
        self.protect_first_n = protect_first_n
        self.protect_last_n = protect_last_n
        self.summary_target_ratio = max(0.10, min(summary_target_ratio, 0.80))
        # LongCat-2.0-Preview context window
        self.context_length = 128000
        self.threshold_tokens = max(
            int(self.context_length * threshold_percent),
            64000,
        )
        target_tokens = int(self.threshold_tokens * self.summary_target_ratio)
        self.tail_token_budget = target_tokens
        self.max_summary_tokens = min(
            int(self.context_length * 0.05), _SUMMARY_TOKENS_CEILING,
        )
        self.compression_count = 0
        self._previous_summary = None
        self._summary_failure_cooldown_until = 0.0
        self._last_summary_error = None
        self.last_prompt_tokens = 0
        self.last_completion_tokens = 0

    def update_from_response(self, usage):
        """Update tracked token usage from API response."""
        if isinstance(usage, dict):
            self.last_prompt_tokens = usage.get("prompt_tokens", 0)
            self.last_completion_tokens = usage.get("completion_tokens", 0)

    def should_compress(self, prompt_tokens=None):
        """Check if context exceeds the compression threshold."""
        tokens = prompt_tokens if prompt_tokens is not None else self.last_prompt_tokens
        if tokens < self.threshold_tokens:
            return False
        return True

    # ------------------------------------------------------------------
    # Phase 1: Tool output pruning (cheap pre-pass, no LLM call)
    # ------------------------------------------------------------------

    def _prune_old_tool_results(self, messages, protect_tail_count,
                                 protect_tail_tokens=None):
        """Replace old tool result contents with short summaries.

        Returns (pruned_messages, pruned_count).
        """
        if not messages:
            return messages, 0

        result = [m.copy() for m in messages]
        pruned = 0

        # Build index: tool_call_id -> (tool_name, arguments_json)
        call_id_to_tool = {}
        for msg in result:
            if msg.get("role") == "assistant":
                for tc in msg.get("tool_calls") or []:
                    if isinstance(tc, dict):
                        cid = tc.get("id", "")
                        fn = tc.get("function", {})
                        call_id_to_tool[cid] = (fn.get("name", "unknown"),
                                                fn.get("arguments", ""))
                    else:
                        cid = getattr(tc, "id", "") or ""
                        fn = getattr(tc, "function", None)
                        name = getattr(fn, "name", "unknown") if fn else "unknown"
                        args_str = getattr(fn, "arguments", "") if fn else ""
                        call_id_to_tool[cid] = (name, args_str)

        # Determine prune boundary
        if protect_tail_tokens is not None and protect_tail_tokens > 0:
            accumulated = 0
            boundary = len(result)
            min_protect = min(protect_tail_count, len(result))
            for i in range(len(result) - 1, -1, -1):
                msg = result[i]
                raw_content = msg.get("content") or ""
                content_len = _lccc_content_length_for_budget(raw_content)
                msg_tokens = content_len // _CHARS_PER_TOKEN + 10
                for tc in msg.get("tool_calls") or []:
                    if isinstance(tc, dict):
                        args = tc.get("function", {}).get("arguments", "")
                        msg_tokens += len(args) // _CHARS_PER_TOKEN
                if (accumulated + msg_tokens > protect_tail_tokens
                        and (len(result) - i) >= min_protect):
                    boundary = i
                    break
                accumulated += msg_tokens
                boundary = i
            budget_protect_count = len(result) - boundary
            protected_count = max(budget_protect_count, min_protect)
            prune_boundary = len(result) - protected_count
        else:
            prune_boundary = len(result) - protect_tail_count

        # Deduplicate identical tool results (keep newest)
        content_hashes = {}
        for i in range(len(result) - 1, -1, -1):
            msg = result[i]
            if msg.get("role") != "tool":
                continue
            content = msg.get("content") or ""
            if isinstance(content, list):
                continue
            if not isinstance(content, str):
                continue
            if len(content) < 200:
                continue
            h = hashlib.md5(content.encode("utf-8", errors="replace")).hexdigest()[:12]
            if h in content_hashes:
                result[i] = {**msg,
                             "content": "【重复工具输出——与更近期调用内容相同】"}
                pruned += 1
            else:
                content_hashes[h] = (i, msg.get("tool_call_id", "?"))

        # Replace old tool results with informative summaries
        for i in range(prune_boundary):
            msg = result[i]
            if msg.get("role") != "tool":
                continue
            content = msg.get("content", "")
            if not isinstance(content, str):
                continue
            if not content or content == _PRUNED_TOOL_PLACEHOLDER:
                continue
            if content.startswith("【重复工具输出"):
                continue
            if len(content) > 200:
                call_id = msg.get("tool_call_id", "")
                tool_name, tool_args = call_id_to_tool.get(call_id, ("unknown", ""))
                summary = _lccc_summarize_tool_result(tool_name, tool_args, content)
                result[i] = {**msg, "content": summary}
                pruned += 1

        return result, pruned

    # ------------------------------------------------------------------
    # Phase 2 & 4: Boundary determination + assembly
    # ------------------------------------------------------------------

    def compress(self, messages, current_tokens=None, focus_topic=None):
        """Compact the message list and return a new list."""
        if not messages:
            return messages

        # Ensure first message is system
        head_count = self.protect_first_n
        if len(messages) > 0 and messages[0].get("role") == "system":
            head_count = max(1, head_count)  # system counts as 1

        if len(messages) <= head_count + self.protect_last_n:
            # Too short to compress
            return messages

        # Phase 1: Prune old tool results
        pruned, _ = self._prune_old_tool_results(
            messages,
            protect_tail_count=self.protect_last_n,
            protect_tail_tokens=self.tail_token_budget,
        )

        # Re-estimate tokens after pruning
        pruned_tokens = current_tokens
        if pruned_tokens is None:
            pruned_tokens = _lccc_estimate_messages_tokens(pruned)

        # If pruning alone brought us under threshold, return pruned
        if pruned_tokens < self.threshold_tokens:
            return pruned

        # Phase 2: Determine boundaries
        # Find tail cut by token budget
        tail_end = len(pruned)
        tail_start = tail_end
        accumulated = 0
        for i in range(tail_end - 1, -1, -1):
            msg = pruned[i]
            content_len = _lccc_content_length_for_budget(msg.get("content") or "")
            msg_tokens = content_len // _CHARS_PER_TOKEN + 10
            for tc in msg.get("tool_calls") or []:
                if isinstance(tc, dict):
                    args = tc.get("function", {}).get("arguments", "")
                    msg_tokens += len(args) // _CHARS_PER_TOKEN
            if accumulated + msg_tokens > self.tail_token_budget and (tail_end - i) >= self.protect_last_n:
                tail_start = i + 1
                break
            accumulated += msg_tokens
            tail_start = i

        # Ensure at least protect_last_n messages in tail
        min_tail_start = max(head_count, tail_end - self.protect_last_n)
        if tail_start < min_tail_start:
            tail_start = min_tail_start

        # Align boundary backward to avoid splitting tool groups
        tail_start = self._align_boundary_backward(pruned, tail_start)

        middle = pruned[head_count:tail_start]
        if not middle:
            # Nothing to summarize — return pruned
            return pruned

        # Phase 3: Generate summary
        summary = self._generate_summary(middle, focus_topic=focus_topic)

        # Phase 4: Assemble compressed messages
        compressed = pruned[:head_count]

        if summary:
            # Insert summary as a user message to avoid consecutive assistant
            # messages (OpenAI requires alternating roles)
            compressed.append({
                "role": "user",
                "content": _lccc_append_text_to_content(
                    None,
                    f"{_SUMMARY_PREFIX}\n\n{summary}",
                ),
            })
            self.compression_count += 1
        else:
            # Summary failed — drop middle turns without replacement
            logging.warning("Context compression: summary generation failed, "
                            "dropping %d middle turns.", len(middle))

        compressed.extend(pruned[tail_start:])

        # Clean up orphaned tool_call / tool_result pairs
        compressed = self._sanitize_tool_pairs(compressed)
        return compressed

    @staticmethod
    def _align_boundary_backward(messages, idx):
        """Walk backward past consecutive tool results to keep groups intact."""
        if idx <= 0 or idx >= len(messages):
            return idx
        # If idx points at a tool result, walk back to its parent assistant
        while idx > 0 and messages[idx].get("role") == "tool":
            idx -= 1
        # Now idx points at the assistant with tool_calls; keep it
        return idx

    @staticmethod
    def _get_tool_call_id(tc):
        if isinstance(tc, dict):
            return tc.get("call_id", "") or tc.get("id", "") or ""
        return getattr(tc, "call_id", "") or getattr(tc, "id", "") or ""

    def _sanitize_tool_pairs(self, messages):
        """Fix orphaned tool_call / tool_result pairs after compression."""
        if not messages:
            return messages

        # Collect all call IDs still present in assistant messages
        valid_call_ids = set()
        for msg in messages:
            if msg.get("role") == "assistant":
                for tc in msg.get("tool_calls") or []:
                    cid = self._get_tool_call_id(tc)
                    if cid:
                        valid_call_ids.add(cid)

        result = []
        for msg in messages:
            if msg.get("role") == "tool":
                cid = msg.get("tool_call_id", "")
                if cid and cid not in valid_call_ids:
                    # Orphaned result — remove it
                    continue
            result.append(msg)

        # Find assistant messages with tool_calls whose results were dropped
        for i, msg in enumerate(result):
            if msg.get("role") != "assistant" or not msg.get("tool_calls"):
                continue
            kept_call_ids = set()
            for tc in msg["tool_calls"]:
                cid = self._get_tool_call_id(tc)
                if cid:
                    kept_call_ids.add(cid)
            # Check which results still exist after pruning
            existing_result_ids = set()
            for m in result:
                if m.get("role") == "tool":
                    cid = m.get("tool_call_id", "")
                    if cid:
                        existing_result_ids.add(cid)
            missing = kept_call_ids - existing_result_ids
            if missing:
                # Insert stub results right after this assistant message
                stubs = []
                for cid in missing:
                    stubs.append({
                        "role": "tool",
                        "tool_call_id": cid,
                        "content": "【该工具结果在上下文压缩时被省略】",
                    })
                result = result[:i + 1] + stubs + result[i + 1:]
        return result

    # ------------------------------------------------------------------
    # Phase 3: Summarization
    # ------------------------------------------------------------------

    def _compute_summary_budget(self, turns_to_summarize):
        """Scale summary token budget with compressed content size."""
        content_tokens = _lccc_estimate_messages_tokens(turns_to_summarize)
        budget = int(content_tokens * _SUMMARY_RATIO)
        return max(_MIN_SUMMARY_TOKENS, min(budget, self.max_summary_tokens))

    _CONTENT_MAX = 6000
    _CONTENT_HEAD = 4000
    _CONTENT_TAIL = 1500
    _TOOL_ARGS_MAX = 1500
    _TOOL_ARGS_HEAD = 1200

    def _serialize_for_summary(self, turns):
        """Serialize conversation turns into labeled text for summarizer."""
        parts = []
        for msg in turns:
            role = msg.get("role", "unknown")
            content = msg.get("content") or ""

            if role == "tool":
                tool_id = msg.get("tool_call_id", "")
                if isinstance(content, str) and len(content) > self._CONTENT_MAX:
                    content = (content[:self._CONTENT_HEAD]
                               + "\n...[截断]...\n"
                               + content[-self._CONTENT_TAIL:])
                parts.append(f"【工具结果 {tool_id}】: {content}")
                continue

            if role == "assistant":
                if isinstance(content, str) and len(content) > self._CONTENT_MAX:
                    content = (content[:self._CONTENT_HEAD]
                               + "\n...[截断]...\n"
                               + content[-self._CONTENT_TAIL:])
                tool_calls = msg.get("tool_calls", [])
                if tool_calls:
                    tc_parts = []
                    for tc in tool_calls:
                        if isinstance(tc, dict):
                            fn = tc.get("function", {})
                            name = fn.get("name", "?")
                            args = fn.get("arguments", "")
                            if len(args) > self._TOOL_ARGS_MAX:
                                args = args[:self._TOOL_ARGS_HEAD] + "..."
                            tc_parts.append(f"  {name}({args})")
                        else:
                            fn = getattr(tc, "function", None)
                            name = getattr(fn, "name", "?") if fn else "?"
                            tc_parts.append(f"  {name}(...)")
                    content += "\n【工具调用：\n" + "\n".join(tc_parts) + "\n】"
                parts.append(f"【助手】: {content}")
                continue

            if isinstance(content, str) and len(content) > self._CONTENT_MAX:
                content = (content[:self._CONTENT_HEAD]
                           + "\n...[截断]...\n"
                           + content[-self._CONTENT_TAIL:])
            parts.append(f"【{role.upper()}】: {content}")

        return "\n\n".join(parts)

    def _generate_summary(self, turns_to_summarize, focus_topic=None):
        """Generate a structured summary of conversation turns.

        Uses LongCat's proxy LLM for summarization. Returns None on failure.
        """
        import time
        now = time.monotonic()
        if now < self._summary_failure_cooldown_until:
            logging.debug("Skipping context summary during cooldown (%.0fs remaining)",
                          self._summary_failure_cooldown_until - now)
            return None

        summary_budget = self._compute_summary_budget(turns_to_summarize)
        content_to_summarize = self._serialize_for_summary(turns_to_summarize)

        _summarizer_preamble = (
            "你是一个摘要生成助手。请将以下对话内容整理成结构化的上下文摘要，"
            "用于帮助后续模型理解对话背景。只输出摘要内容，不要添加问候或前缀。"
            "使用对话中用户使用的语言撰写摘要，不要翻译成英文。"
        )

        _template_sections = f"""## 当前任务
【最重要的字段。复制用户最近的请求或任务描述原文。如果有多项任务且部分未完成，只列出未完成的。示例："用户要求：'把认证模块改成用 JWT'"
如果没有未完成任务，写"无"。】

## 目标
【用户整体想达成什么】

## 约束与偏好
【用户偏好、编码风格、重要决策】

## 已完成动作
【编号列表，包含具体工具、目标和结果。格式：N. 动作 目标 — 结果 【工具：名称】】

## 活跃状态
【当前工作状态：工作目录、修改的文件、测试状态等】

## 进行中
【当前正在做的工作】

## 阻塞项
【未解决的错误、阻塞项，包含精确错误信息】

## 关键决策
【重要技术决策及原因】

## 已解决问题
【用户已得到回答的问题及答案】

## 待处理请求
【用户尚未得到回答或满足的请求。没有则写"无"。】

## 相关文件
【读取、修改或创建的文件及简要说明】

## 剩余工作
【还需要做什么——作为背景描述，不是指令】

## 关键上下文
【具体值、错误信息、配置细节。不要包含 API 密钥或密码。】

目标约 {summary_budget} tokens。要具体——包含文件路径、命令输出、错误信息、行号和具体值。避免模糊描述如"做了一些修改"——要明确写出改了什么。"""

        if self._previous_summary:
            prompt = f"""{_summarizer_preamble}

你正在更新一个上下文压缩摘要。之前的摘要如下，需要把新的对话内容合并进去。

之前的摘要：
{self._previous_summary}

需要合并的新内容：
{content_to_summarize}

请更新摘要，保留所有仍相关的信息，添加新的已完成动作到编号列表（继续编号）。将"进行中"完成的项目移到"已完成"。将已回答的问题移到"已解决"。更新"活跃状态"反映当前情况。只删除明显过时的信息。必须更新"当前任务"以反映用户最新的未完成请求。

{_template_sections}"""
        else:
            prompt = f"""{_summarizer_preamble}

为以下对话内容创建结构化摘要，保留足够细节以保证连续性。

需要摘要的内容：
{content_to_summarize}

{_template_sections}"""

        if focus_topic:
            prompt += f"""

聚焦主题："{focus_topic}"
请优先保留与"{focus_topic}"相关的所有信息，包含完整细节。对于不相关的内容，可以更激进地压缩。聚焦主题应占摘要 token 预算的 60-70%。"""

        try:
            keys = _longcat_default_api_keys()
            if not keys:
                raise RuntimeError("no API keys configured")

            payload = {
                "model": self.model,
                "messages": [{"role": "user", "content": prompt}],
                "max_tokens": int(summary_budget * 1.3),
                "temperature": 0.3,
            }
            response = _longcat_proxy_request(payload, keys[0], timeout=120)
            data = json.loads(response.read().decode("utf-8"))

            # Extract content from OpenAI-style response
            choices = data.get("choices", [])
            if not choices:
                raise RuntimeError("empty choices in summary response")
            content = choices[0].get("message", {}).get("content", "")
            if not isinstance(content, str):
                content = str(content) if content else ""

            summary = content.strip()
            if not summary:
                raise RuntimeError("empty summary content")

            self._previous_summary = summary
            self._summary_failure_cooldown_until = 0.0
            self._last_summary_error = None
            return summary

        except Exception as e:
            self._summary_failure_cooldown_until = time.monotonic() + _SUMMARY_FAILURE_COOLDOWN_SECONDS
            err_text = str(e).strip() or e.__class__.__name__
            if len(err_text) > 220:
                err_text = err_text[:217].rstrip() + "..."
            self._last_summary_error = err_text
            logging.warning("Failed to generate context summary: %s. "
                            "Further summary attempts paused for %d seconds.",
                            e, _SUMMARY_FAILURE_COOLDOWN_SECONDS)
            return None


# Global compressor instance (lazy init)
_longcat_context_compressor = None


def _get_longcat_context_compressor():
    global _longcat_context_compressor
    if _longcat_context_compressor is None:
        _longcat_context_compressor = LongCatContextCompressor(
            model=LONGCAT_PROXY_MODEL,
            threshold_percent=0.50,
            protect_first_n=3,
            protect_last_n=6,
            summary_target_ratio=0.20,
        )
    return _longcat_context_compressor


def _native_jsonable(value, limit=LONGCAT_NATIVE_TOOL_MAX_OBSERVATION_CHARS):
    """Return a JSON-safe value without collapsing structured data into a raw text blob."""
    def make_safe(item, depth=0):
        if depth > 24:
            return str(item)
        if isinstance(item, dict):
            return {str(key): make_safe(val, depth + 1) for key, val in item.items()}
        if isinstance(item, list):
            return [make_safe(val, depth + 1) for val in item]
        if isinstance(item, tuple):
            return [make_safe(val, depth + 1) for val in item]
        if isinstance(item, (str, int, float, bool)) or item is None:
            return item
        return str(item)

    def json_len(item):
        try:
            return len(json.dumps(item, ensure_ascii=False, default=str))
        except Exception:
            return len(str(item))

    def compact_string(text, budget):
        text = str(text or "")
        if budget <= 0 or len(text) <= budget:
            return text
        suffix = f" …[truncated {max(0, len(text) - max(0, budget - 32))} chars]"
        keep = max(0, budget - len(suffix))
        return text[:keep] + suffix

    def compact_value(item, budget, depth=0):
        item = make_safe(item, depth)
        if budget <= 0 or json_len(item) <= budget:
            return item
        if isinstance(item, str):
            return compact_string(item, max(24, budget - 8))
        if isinstance(item, (int, float, bool)) or item is None:
            return item
        if isinstance(item, list):
            out = []
            remaining = max(80, budget - 40)
            per_item = max(240, remaining // max(1, min(len(item), 12)))
            omitted = 0
            for idx, val in enumerate(item):
                compacted = compact_value(val, per_item, depth + 1)
                trial = out + [compacted]
                if json_len(trial) > remaining:
                    omitted = len(item) - idx
                    break
                out.append(compacted)
            if omitted:
                out.append({"_truncated_items": omitted})
            return out
        if isinstance(item, dict):
            priority = [
                "tool", "success", "summary", "answeringInstruction", "searchQuality",
                "repoContexts", "sourceEvidence", "evidenceMatrix", "facts", "sources",
                "compressedEvidenceBrief", "documentCapsules", "qualityGate",
                "candidatePoolSummary", "queriesTried", "artifacts", "raw", "trace",
            ]
            keys = [key for key in priority if key in item] + [key for key in item.keys() if key not in set(priority)]
            out = {"_truncated": True}
            remaining = max(120, budget - json_len(out) - 24)
            for key in keys:
                val = item.get(key)
                key_weight = 3 if key in {"repoContexts", "sourceEvidence", "evidenceMatrix", "compressedEvidenceBrief", "documentCapsules", "raw"} else 1
                per_key = max(320, min(remaining, (remaining // max(1, len(keys))) * key_weight))
                compacted = compact_value(val, per_key, depth + 1)
                trial = dict(out)
                trial[key] = compacted
                if json_len(trial) > budget and key not in {"tool", "success", "summary", "answeringInstruction"}:
                    continue
                out[key] = compacted
                remaining = max(0, budget - json_len(out) - 16)
                if remaining <= 80:
                    break
            omitted_keys = [key for key in item.keys() if key not in out]
            if omitted_keys:
                out["_truncated_keys"] = omitted_keys[:24]
            return out
        return compact_string(str(item), max(24, budget - 8))

    safe = make_safe(value)
    if not limit or limit <= 0:
        return safe
    try:
        text = json.dumps(safe, ensure_ascii=False, default=str)
    except Exception:
        text = json.dumps({"value": str(safe)}, ensure_ascii=False)
    if len(text) <= limit:
        try:
            return json.loads(text)
        except Exception:
            return {"value": text}
    return compact_value(safe, limit)


def _native_utf8_len(text):
    return len(str(text or "").encode("utf-8"))


def _native_trim_utf8(text, max_bytes, mode="head", marker=""):
    text = str(text or "")
    max_bytes = max(0, int(max_bytes or 0))
    marker = str(marker or "")
    if max_bytes <= 0:
        return ""
    if _native_utf8_len(text) <= max_bytes:
        return text
    marker_bytes = marker.encode("utf-8")
    budget = max(0, max_bytes - len(marker_bytes))
    raw = text.encode("utf-8")
    if mode == "tail":
        chunk = raw[-budget:] if budget else b""
        trimmed = chunk.decode("utf-8", errors="ignore")
        return marker + trimmed
    chunk = raw[:budget] if budget else b""
    trimmed = chunk.decode("utf-8", errors="ignore")
    return trimmed + marker


def _native_truncate_text_lines_bytes(text, max_lines=None, max_bytes=None, mode="head"):
    text = str(text or "")
    mode = "tail" if mode == "tail" else "head"
    max_lines = max(1, int(max_lines or LONGCAT_NATIVE_TOOL_MAX_OBSERVATION_LINES))
    max_bytes = max(128, int(max_bytes or LONGCAT_NATIVE_TOOL_MAX_OBSERVATION_BYTES))
    meta = {
        "truncated": False,
        "mode": mode,
        "original_bytes": _native_utf8_len(text),
        "original_lines": len(text.splitlines()) if text else 0,
        "omitted_lines": 0,
        "omitted_bytes": 0,
    }
    lines = text.splitlines()
    if len(lines) > max_lines:
        meta["truncated"] = True
        meta["omitted_lines"] = len(lines) - max_lines
        lines = lines[-max_lines:] if mode == "tail" else lines[:max_lines]
        text = "\n".join(lines)
    if _native_utf8_len(text) > max_bytes:
        meta["truncated"] = True
        meta["omitted_bytes"] = max(0, _native_utf8_len(text) - max_bytes)
        marker = f"...[truncated {meta['omitted_lines']} lines, {meta['omitted_bytes']} bytes]..."
        text = _native_trim_utf8(text, max_bytes, mode=mode, marker=marker)
    return text, meta


def _native_tool_truncation_mode(tool_name):
    name = str(tool_name or "")
    if name in {"run_shell", "shell", "terminal", "run_command", "execute_code"}:
        return "tail"
    if name in {"search_web", "search_memory", "search_papers"}:
        return "head"
    return "head"


def _native_truncate_structured_value(value, max_bytes, max_lines, mode="head", depth=0):
    try:
        original_dump = json.dumps(_native_jsonable(value, limit=0), ensure_ascii=False, default=str)
    except Exception:
        original_dump = json.dumps({"value": str(value)}, ensure_ascii=False)
    original_too_large = _native_utf8_len(original_dump) > max_bytes or len(original_dump.splitlines()) > max_lines
    safe = _native_jsonable(value, limit=max(max_bytes * 2, 2048))
    try:
        dumped = json.dumps(safe, ensure_ascii=False, default=str)
    except Exception:
        dumped = json.dumps({"value": str(safe)}, ensure_ascii=False)
    if _native_utf8_len(dumped) <= max_bytes and len(dumped.splitlines()) <= max_lines and not original_too_large:
        return safe, {
            "truncated": False,
            "mode": mode,
            "original_bytes": _native_utf8_len(dumped),
            "original_lines": len(dumped.splitlines()),
        }
    if _native_utf8_len(dumped) <= max_bytes and len(dumped.splitlines()) <= max_lines and original_too_large:
        return safe, {
            "truncated": True,
            "mode": mode,
            "original_bytes": _native_utf8_len(original_dump),
            "original_lines": len(original_dump.splitlines()),
        }
    if depth > 10:
        text, meta = _native_truncate_text_lines_bytes(dumped, max_lines=max_lines, max_bytes=max_bytes, mode=mode)
        return {"_truncated_text": text}, meta
    if isinstance(safe, str):
        return _native_truncate_text_lines_bytes(safe, max_lines=max_lines, max_bytes=max_bytes, mode=mode)
    if isinstance(safe, list):
        item_budget = max(512, max_bytes // max(1, min(len(safe), 8)))
        keep_count = min(len(safe), max(1, max_bytes // max(item_budget, 1)))
        selected = safe[-keep_count:] if mode == "tail" else safe[:keep_count]
        items = []
        truncated = len(selected) < len(safe)
        for item in selected:
            compacted, child_meta = _native_truncate_structured_value(item, item_budget, max(8, max_lines // max(1, keep_count)), mode, depth + 1)
            truncated = truncated or bool(child_meta.get("truncated"))
            items.append(compacted)
        if len(selected) < len(safe):
            marker = {"_truncated_items": len(safe) - len(selected), "_mode": mode}
            items = [marker] + items if mode == "tail" else items + [marker]
        return items, {"truncated": truncated, "mode": mode, "original_items": len(safe)}
    if isinstance(safe, dict):
        priority = [
            "tool", "success", "summary", "error", "answeringInstruction", "searchQuality",
            "facts", "sources", "artifacts", "compressedEvidenceBrief",
            "documentCapsules", "sourceEvidence", "queriesTried", "plan", "raw",
        ]
        ordered_keys = [key for key in priority if key in safe] + [key for key in safe.keys() if key not in set(priority)]
        out = {"_truncated": True}
        truncated = True
        omitted = []
        remaining = max(512, max_bytes - _native_utf8_len(json.dumps(out, ensure_ascii=False)))
        for key in ordered_keys:
            per_key = max(320, remaining // max(1, len(ordered_keys)))
            if key in {"raw", "documentCapsules", "sourceEvidence", "compressedEvidenceBrief"}:
                per_key = max(per_key, remaining // 2)
            compacted, child_meta = _native_truncate_structured_value(
                safe.get(key),
                max(256, min(remaining, per_key)),
                max(8, max_lines // max(1, min(len(ordered_keys), 12))),
                mode,
                depth + 1,
            )
            trial = dict(out)
            trial[key] = compacted
            trial_text = json.dumps(trial, ensure_ascii=False, default=str)
            if _native_utf8_len(trial_text) > max_bytes and key not in {"tool", "success", "summary", "error"}:
                omitted.append(key)
                continue
            out[key] = compacted
            truncated = truncated or bool(child_meta.get("truncated"))
            remaining = max(0, max_bytes - _native_utf8_len(trial_text) - 32)
            if remaining <= 96:
                omitted.extend([k for k in ordered_keys if k not in out and k not in omitted])
                break
        if omitted:
            out["_truncated_keys"] = omitted[:24]
        return out, {"truncated": truncated, "mode": mode, "omitted_keys": omitted[:24]}
    text, meta = _native_truncate_text_lines_bytes(str(safe), max_lines=max_lines, max_bytes=max_bytes, mode=mode)
    return text, meta


def _native_tool_message_content(tool_name, model_observation, context=None):
    mode = _native_tool_truncation_mode(tool_name)
    max_bytes = LONGCAT_NATIVE_TOOL_MAX_OBSERVATION_BYTES
    max_lines = LONGCAT_NATIVE_TOOL_MAX_OBSERVATION_LINES
    truncated, meta = _native_truncate_structured_value(model_observation, max_bytes, max_lines, mode=mode)
    content = json.dumps(truncated, ensure_ascii=False, default=str)
    while _native_utf8_len(content) > max_bytes and max_bytes > 1024:
        max_bytes = int(max_bytes * 0.85)
        truncated, meta = _native_truncate_structured_value(model_observation, max_bytes, max_lines, mode=mode)
        content = json.dumps(truncated, ensure_ascii=False, default=str)
    if _native_utf8_len(content) > LONGCAT_NATIVE_TOOL_MAX_OBSERVATION_BYTES:
        text, text_meta = _native_truncate_text_lines_bytes(
            content,
            max_lines=max_lines,
            max_bytes=LONGCAT_NATIVE_TOOL_MAX_OBSERVATION_BYTES - 200,
            mode=mode,
        )
        meta = {**(meta or {}), **text_meta, "fallback_text_envelope": True}
        content = json.dumps({"_truncated_json_text": text, "_truncation": meta}, ensure_ascii=False, default=str)
    if isinstance(context, dict):
        with _native_context_lock(context):
            context.setdefault("tool_truncation_meta", []).append({
                "tool": tool_name,
                **(meta or {}),
                "final_bytes": _native_utf8_len(content),
            })
            context["tool_truncation_meta"] = context["tool_truncation_meta"][-40:]
    return content, meta


def _native_compact_text(value, limit=1200):
    return re.sub(r"\s+", " ", str(value or "")).strip()[:limit]


def _native_json_response_payload(result):
    status = 200
    headers = {}
    body = result
    if isinstance(result, tuple):
        body = result[0]
        if len(result) > 1 and isinstance(result[1], int):
            status = result[1]
        if len(result) > 2 and isinstance(result[2], dict):
            headers = result[2]
    if isinstance(body, Response):
        status = body.status_code
        headers = dict(body.headers or {})
        raw = body.get_data(as_text=True)
        try:
            payload = json.loads(raw) if raw else {}
        except Exception:
            payload = {"text": raw}
        return payload, status, headers
    if hasattr(body, "data") and hasattr(body, "status_code"):
        status = getattr(body, "status_code", status)
        headers = dict(getattr(body, "headers", {}) or {})
        return getattr(body, "data", {}), status, headers
    if isinstance(body, (dict, list)):
        return body, status, headers
    return {"value": str(body)}, status, headers


def _native_invoke_json_route(path, view_func, payload, headers=None):
    with app.test_request_context(path, method="POST", json=payload or {}, headers=headers or {}):
        result = view_func()
    data, status, _headers = _native_json_response_payload(result)
    if status >= 400 or (isinstance(data, dict) and data.get("success") is False):
        raise RuntimeError((data or {}).get("error") or (data or {}).get("message") or f"{path} failed ({status})")
    return data


def _native_sources_from_search(result, limit=8):
    """Build source list from search result.
    Title priority: refs (Baidu API already cleaned) > pages fallback.
    All titles go through _agent_sanitize_title_text to strip markdown noise.
    Display priority: pages (actually fetched) first, then refs.
    """
    # Build URL -> title map; prefer refs titles (Baidu API quality)
    url_to_title = {}
    for item in (result.get("refs") or []):
        url = item.get("url") or ""
        if url:
            raw_title = item.get("title") or ""
            clean_title = _agent_sanitize_title_text(raw_title) if raw_title else ""
            url_to_title[url] = clean_title or url

    # Collect pages URLs; use pages title only if refs has no entry
    pages_urls = []
    for item in (result.get("pages") or []):
        url = item.get("url") or ""
        if url and url not in url_to_title:
            raw_title = item.get("title") or ""
            clean_title = _agent_sanitize_title_text(raw_title) if raw_title else ""
            url_to_title[url] = clean_title or url
        if url and url not in pages_urls:
            pages_urls.append(url)

    sources = []
    seen = set()

    # Round 1: URLs that were actually fetched (type=page), using refs title
    for url in pages_urls:
        if url in seen:
            continue
        seen.add(url)
        sources.append({
            "title": url_to_title.get(url) or url,
            "url": url,
            "type": "page",
        })
        if len(sources) >= limit:
            return sources

    # Round 2: URLs only in refs (not fetched)
    for item in (result.get("refs") or []):
        url = item.get("url") or ""
        if url and url not in seen:
            seen.add(url)
            sources.append({
                "title": url_to_title.get(url) or url,
                "url": url,
                "type": "search_result",
            })
            if len(sources) >= limit:
                return sources

    return sources


def _native_observation(name, summary="", facts=None, cards=None, sources=None, confidence=0.7, raw=None, error="", artifacts=None, display_blocks=None):
    payload = {
        "tool": name,
        "summary": _native_compact_text(summary, 1600),
        "facts": [_native_compact_text(item, 900) for item in (facts or []) if _native_compact_text(item, 900)][:12],
        "cards": cards or [],
        "artifacts": artifacts or [],
        "display_blocks": display_blocks or [],
        "sources": sources or [],
        "confidence": max(0, min(1, float(confidence or 0))),
        "follow_up_suggestions": [],
    }
    if error:
        payload["error"] = _native_compact_text(error, 1200)
        payload["success"] = False
    else:
        payload["success"] = True
    if raw is not None:
        payload["raw"] = _native_jsonable(raw, limit=90000 if name == "search_web" else 6000)
    return payload


def _native_card_artifact_title(card):
    if not isinstance(card, dict):
        return "卡片"
    ctype = str(card.get("type") or "").strip()
    data = card.get("data") if isinstance(card.get("data"), dict) else {}
    if ctype == "merchant":
        pois = ((data.get("result") or {}).get("pois") or [])
        if pois:
            return pois[0].get("name") or "商户卡片"
        return "商户卡片"
    if ctype == "movie":
        movies = data.get("movies") or []
        if movies:
            return movies[0].get("title") or "电影卡片"
        return "电影卡片"
    if ctype == "aps":
        papers = (((data.get("result") or {}).get("data") or {}).get("papers") or [])
        if papers:
            return papers[0].get("title") or "论文卡片"
        return "论文卡片"
    if ctype == "rail12306":
        trains = ((data.get("result") or {}).get("trains") or [])
        if trains:
            return trains[0].get("trainCode") or "车票卡片"
        return "车票卡片"
    if ctype == "weather":
        return data.get("locationName") or "天气卡片"
    if ctype == "navigation":
        return data.get("destination") or "路线卡片"
    if ctype == "time":
        return data.get("label") or data.get("timezone") or "时间卡片"
    return ctype or "卡片"


def _native_card_artifact_summary(card):
    if not isinstance(card, dict):
        return ""
    ctype = str(card.get("type") or "").strip()
    data = card.get("data") if isinstance(card.get("data"), dict) else {}
    if ctype == "merchant":
        pois = ((data.get("result") or {}).get("pois") or [])
        names = [poi.get("name") for poi in pois[:4] if poi.get("name")]
        return f"{len(pois)} 个商户候选" + (f"：{'、'.join(names)}" if names else "")
    if ctype == "movie":
        movies = data.get("movies") or []
        titles = [movie.get("title") for movie in movies[:4] if movie.get("title")]
        return f"{len(movies)} 个电影候选" + (f"：{'、'.join(titles)}" if titles else "")
    if ctype == "aps":
        papers = (((data.get("result") or {}).get("data") or {}).get("papers") or [])
        return f"{len(papers)} 篇论文候选"
    if ctype == "rail12306":
        trains = ((data.get("result") or {}).get("trains") or [])
        return f"{len(trains)} 趟车次"
    if ctype == "weather":
        now = data.get("now") or {}
        return f"{now.get('text') or '天气'} {now.get('temp') or '--'}°C"
    if ctype == "navigation":
        first = (data.get("paths") or [{}])[0]
        return f"{first.get('distance') or '未知'} 米"
    if ctype == "time":
        return data.get("summary") or data.get("iso") or ""
    return ""


def _native_register_card_artifacts(context, tool_name, cards):
    lock = _native_context_lock(context) if isinstance(context, dict) else threading.RLock()
    with lock:
        registry = context.setdefault("card_artifacts", {}) if isinstance(context, dict) else {}
        order = context.setdefault("card_artifact_order", []) if isinstance(context, dict) else []
        latest_by_tool = context.setdefault("latest_card_artifact_ids_by_tool", {}) if isinstance(context, dict) else {}
        artifacts = []
        registered_ids = []
        for card in cards or []:
            if not isinstance(card, dict):
                continue
            artifact_id = f"card_{len(order) + 1}"
            registry[artifact_id] = card
            order.append(artifact_id)
            registered_ids.append(artifact_id)
            artifacts.append({
                "id": artifact_id,
                "type": card.get("type") or tool_name,
                "title": _native_compact_text(_native_card_artifact_title(card), 120),
                "summary": _native_compact_text(_native_card_artifact_summary(card), 260),
                "tool": tool_name,
                "display": {"tool": "display_cards", "mode": "structured"},
            })
        if registered_ids:
            latest_by_tool[tool_name] = registered_ids
            context["latest_card_artifact_ids"] = registered_ids
        return artifacts


