def _agent_record_op_event(event):
    """Persist lane runtime events for crash diagnosis and resume reconstruction."""
    if not isinstance(event, OpEvent):
        return
    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS agent_op_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_id TEXT NOT NULL UNIQUE,
                    seq INTEGER NOT NULL,
                    session_id TEXT NOT NULL,
                    run_id TEXT NOT NULL,
                    op_id TEXT NOT NULL DEFAULT '',
                    parent_op_id TEXT NOT NULL DEFAULT '',
                    trajectory_id TEXT NOT NULL DEFAULT '',
                    cascade_id TEXT NOT NULL DEFAULT '',
                    lane TEXT NOT NULL DEFAULT '',
                    type TEXT NOT NULL,
                    status TEXT NOT NULL,
                    ts_ms INTEGER NOT NULL,
                    payload_json TEXT NOT NULL DEFAULT '{}',
                    error TEXT NOT NULL DEFAULT ''
                )
                """
            )
            conn.execute(
                """
                CREATE INDEX IF NOT EXISTS idx_agent_op_events_session_seq
                ON agent_op_events(session_id, run_id, seq)
                """
            )
            payload_json = json.dumps(event.payload or {}, ensure_ascii=False, default=str)
            conn.execute(
                """
                INSERT OR IGNORE INTO agent_op_events(
                    event_id, seq, session_id, run_id, op_id, parent_op_id,
                    trajectory_id, cascade_id, lane, type, status, ts_ms,
                    payload_json, error
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    event.event_id,
                    int(event.seq),
                    event.session_id,
                    event.run_id,
                    event.op_id,
                    event.parent_op_id,
                    event.trajectory_id,
                    event.cascade_id,
                    event.lane,
                    event.type,
                    event.status,
                    int(event.ts_ms),
                    payload_json,
                    event.error or "",
                ),
            )
            conn.commit()
        finally:
            conn.close()


def _native_legacy_op_event_listener(event_queue):
    def _listener(event):
        _native_emit_queue(event_queue, "op_event", event.to_dict())

    return _listener


def _native_session_runtime(context, event_queue=None):
    if not isinstance(context, dict):
        return None
    runtime = context.get("_session_runtime")
    if isinstance(runtime, SessionRuntime):
        if event_queue is not None and not context.get("_runtime_event_listener_attached"):
            runtime.event_bus.subscribe(
                _native_legacy_op_event_listener(event_queue),
                key=f"legacy-event-queue:{id(event_queue)}",
            )
            context["_runtime_event_listener_attached"] = True
        return runtime
    session_id = str(context.get("session_id") or f"session_{uuid.uuid4().hex[:12]}")[:160]
    context["session_id"] = session_id
    runtime = SessionRuntime(session_id, event_sink=_agent_record_op_event)
    context["_session_runtime"] = runtime
    context["_cancellation_token"] = runtime.token
    if event_queue is not None:
        runtime.event_bus.subscribe(
            _native_legacy_op_event_listener(event_queue),
            key=f"legacy-event-queue:{id(event_queue)}",
        )
        context["_runtime_event_listener_attached"] = True
    agent_runtime.register_session(runtime)
    return runtime


def _native_cancel_session_runtime(context, reason="cancelled"):
    runtime = context.get("_session_runtime") if isinstance(context, dict) else None
    if isinstance(runtime, SessionRuntime):
        runtime.cancel(reason)


def _native_tool_lane(name, args=None, cached=False):
    if cached:
        return "fast"
    name = str(name or "")
    if name == "tool_search":
        return "fast"
    if name in {"plan_task", "ask_user_clarification"}:
        return "plan"
    if name in {"spawn_agent", "task_output"}:
        return "subagent"
    if name in {"task_create", "task_get", "task_list", "task_stop", "create_team", "send_to_agent"}:
        return "fast"
    if name in {"search_web", "search_merchants", "search_movies", "plan_navigation"}:
        return "io"
    if name in {"display_cards", "get_time"}:
        return "fast"
    if name in {"search_papers", "get_weather", "search_train_tickets", "resolve_location_anchor", "search_memory"}:
        return "io"
    return "compute"


def _native_run_runtime_op(context, event_queue, lane, name, fn, budget_cost=1):
    runtime = _native_session_runtime(context, event_queue) if isinstance(context, dict) else None
    if isinstance(runtime, SessionRuntime):
        return runtime.run_op(lane, name, fn, budget_cost=budget_cost)
    return fn()


def _native_consume_subagent_budget(context, cost=1):
    if not isinstance(context, dict):
        return
    budget = context.get("_subagent_budget")
    if budget is None or not hasattr(budget, "consume"):
        return
    if not budget.consume(cost):
        raise RuntimeError("subagent context budget exhausted")


class SubagentContext(ForkedContext):
    """Isolated context fork for parallel tool/subagent work."""

    def __init__(self, parent_context):
        super().__init__(parent_context if isinstance(parent_context, dict) else {})
        runtime = _native_session_runtime(parent_context) if isinstance(parent_context, dict) else None
        if isinstance(runtime, SessionRuntime):
            self["_session_runtime"] = runtime
            self["_cancellation_token"] = runtime.child_token()
            self["_subagent_budget"] = runtime.new_subagent_budget()


def _native_process_isolation_available():
    if not LONGCAT_NATIVE_SUBAGENT_PROCESS_ISOLATION:
        return False
    try:
        return bool(_native_process_start_method())
    except Exception:
        return False


_NATIVE_PROCESS_START_METHOD_CACHE = {"method": "", "diagnostics": [], "checked_at": 0}
_NATIVE_PROCESS_START_METHOD_LOCK = threading.Lock()
_NATIVE_MP_SOCKET_TEMPDIR_CACHE = {"path": "", "reason": ""}
_NATIVE_PROCESS_ISOLATED_TOOLS = {"search_web"}
_NATIVE_INPROC_SANDBOX_TOOLS = {
    "search_merchants",
    "search_movies",
    "plan_navigation",
    "search_papers",
    "get_weather",
    "search_train_tickets",
    "resolve_location_anchor",
    "search_memory",
}
_NATIVE_WASM_SANDBOX_TOOLS = {"run_wasm_python"}


def _native_start_method_probe_entry(result_conn):
    try:
        result_conn.send({"ok": True, "pid": os.getpid()})
    except Exception:
        pass
    finally:
        try:
            result_conn.close()
        except Exception:
            pass


def _native_tempdir_supports_unix_sockets(temp_dir):
    temp_dir = str(temp_dir or "").strip()
    if not temp_dir:
        return False, "empty_tempdir"
    try:
        os.makedirs(temp_dir, exist_ok=True)
        sock_path = os.path.join(temp_dir, f"longcat-forkserver-{uuid.uuid4().hex[:12]}.sock")
        if len(sock_path.encode("utf-8")) >= 100:
            return False, "unix_socket_path_too_long"
        probe_socket = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        try:
            probe_socket.bind(sock_path)
        finally:
            probe_socket.close()
            try:
                os.unlink(sock_path)
            except OSError:
                pass
        return True, ""
    except Exception as exc:
        return False, str(exc)


def _native_multiprocessing_socket_tempdir():
    cached = _NATIVE_MP_SOCKET_TEMPDIR_CACHE.get("path")
    if cached:
        return cached
    candidates = [
        os.environ.get("LONGCAT_MULTIPROCESSING_TMPDIR") or "",
        "/tmp/longcat-multiprocessing",
        "/var/tmp/longcat-multiprocessing",
        tempfile.gettempdir(),
    ]
    seen = set()
    failures = []
    for candidate in candidates:
        path = str(candidate or "").strip()
        if not path or path in seen:
            continue
        seen.add(path)
        ok, reason = _native_tempdir_supports_unix_sockets(path)
        if ok:
            try:
                multiprocessing.current_process()._config["tempdir"] = path
            except Exception:
                pass
            _NATIVE_MP_SOCKET_TEMPDIR_CACHE.update({"path": path, "reason": ""})
            return path
        failures.append(f"{path}:{reason}")
    _NATIVE_MP_SOCKET_TEMPDIR_CACHE.update({"path": "", "reason": "; ".join(failures[:4])})
    return ""


def _native_main_module_importable_for_spawn():
    main_file = str(getattr(sys.modules.get("__main__"), "__file__", "") or "")
    if not main_file or main_file.startswith("<") or main_file.endswith(os.sep + "<stdin>"):
        return False, "main_module_not_file"
    if not os.path.exists(main_file):
        return False, f"main_file_missing:{main_file}"
    return True, ""


def _native_process_start_candidates():
    try:
        methods = multiprocessing.get_all_start_methods()
    except Exception:
        return []
    requested = str(os.environ.get("LONGCAT_NATIVE_SUBAGENT_START_METHODS") or "").strip()
    if requested:
        preferred = [item.strip() for item in requested.split(",") if item.strip()]
    else:
        preferred = ["spawn", "forkserver"]
        if LONGCAT_NATIVE_SUBAGENT_ALLOW_FORK:
            preferred.append("fork")
    importable, _reason = _native_main_module_importable_for_spawn()
    if not importable:
        preferred = [
            method for method in preferred
            if method not in {"spawn", "forkserver"}
        ]
    return [method for method in preferred if method in methods]


def _native_probe_process_start_method(method):
    if method == "fork" and not LONGCAT_NATIVE_SUBAGENT_ALLOW_FORK:
        return False, "fork_disabled_in_threaded_runtime"
    if method in {"spawn", "forkserver"}:
        importable, reason = _native_main_module_importable_for_spawn()
        if not importable:
            return False, reason
    if method == "forkserver":
        socket_tempdir = _native_multiprocessing_socket_tempdir()
        if not socket_tempdir:
            return False, f"forkserver_tempdir_unusable:{_NATIVE_MP_SOCKET_TEMPDIR_CACHE.get('reason') or 'no socket-capable tempdir'}"
    try:
        mp_context = multiprocessing.get_context(method)
        parent_conn, child_conn = mp_context.Pipe(duplex=False)
        process = mp_context.Process(target=_native_start_method_probe_entry, args=(child_conn,))
        process.start()
        try:
            child_conn.close()
        except Exception:
            pass
        try:
            item = parent_conn.recv() if parent_conn.poll(5.0) else {"ok": False, "error": "probe_ack_timeout"}
        except Exception as exc:
            item = {"ok": False, "error": str(exc)}
        process.join(timeout=3.0)
        try:
            parent_conn.close()
        except Exception:
            pass
        if process.is_alive():
            process.terminate()
            process.join(timeout=1.0)
            if process.is_alive():
                process.kill()
            return False, "probe_timeout"
        if process.exitcode != 0:
            return False, f"probe_exitcode:{process.exitcode}"
        if not isinstance(item, dict) or not item.get("ok"):
            return False, f"probe_no_ack:{item}"
        return True, ""
    except Exception as exc:
        return False, str(exc)


def _native_process_start_method(refresh=False):
    if not LONGCAT_NATIVE_SUBAGENT_PROCESS_ISOLATION:
        return ""
    with _NATIVE_PROCESS_START_METHOD_LOCK:
        if not refresh and _NATIVE_PROCESS_START_METHOD_CACHE.get("checked_at"):
            return _NATIVE_PROCESS_START_METHOD_CACHE.get("method") or ""
        diagnostics = []
        candidates = _native_process_start_candidates()
        if not candidates:
            importable, reason = _native_main_module_importable_for_spawn()
            diagnostics.append({
                "method": "spawn/forkserver",
                "ok": False,
                "reason": reason or "no configured start method available",
            })
        for method in candidates:
            ok, reason = _native_probe_process_start_method(method)
            diagnostics.append({"method": method, "ok": ok, "reason": reason})
            if ok:
                _NATIVE_PROCESS_START_METHOD_CACHE.update({
                    "method": method,
                    "diagnostics": diagnostics,
                    "checked_at": _now_ms(),
                })
                return method
        _NATIVE_PROCESS_START_METHOD_CACHE.update({
            "method": "",
            "diagnostics": diagnostics,
            "checked_at": _now_ms(),
        })
        return ""


def _native_process_start_diagnostics():
    _native_process_start_method()
    with _NATIVE_PROCESS_START_METHOD_LOCK:
        return _native_clone_jsonable(_NATIVE_PROCESS_START_METHOD_CACHE)


def _native_tool_requires_process_isolation(name, context):
    forced_mode = ""
    if isinstance(context, dict):
        forced_mode = str(context.get("_sandbox_forced_mode") or "").strip().lower()
    if forced_mode in {"inproc", "wasm"}:
        return False
    if isinstance(context, dict) and context.get("_process_isolated_subagent"):
        return False
    return str(name or "") in _NATIVE_PROCESS_ISOLATED_TOOLS and LONGCAT_NATIVE_SUBAGENT_PROCESS_ISOLATION


def _native_normalize_sandbox_mode(value, default="auto"):
    text = str(value or "").strip().lower()
    if text in {"auto", "inproc", "process", "wasm"}:
        return text
    return default


def _native_default_tool_sandbox_mode(name):
    name = str(name or "")
    if name in _NATIVE_WASM_SANDBOX_TOOLS:
        return "wasm"
    if name in _NATIVE_PROCESS_ISOLATED_TOOLS:
        return "process"
    if name in _NATIVE_INPROC_SANDBOX_TOOLS:
        return "inproc"
    return "inproc"


def _native_resolve_tool_sandbox_mode(name, context=None, args=None):
    requested = ""
    if isinstance(args, dict):
        requested = _native_normalize_sandbox_mode(args.get("isolation") or "")
    if not requested and isinstance(context, dict):
        overrides = context.get("sandbox_mode_overrides")
        if isinstance(overrides, dict):
            requested = _native_normalize_sandbox_mode(overrides.get(str(name or "")) or "")
    if not requested:
        requested = _native_normalize_sandbox_mode(LONGCAT_NATIVE_SANDBOX_MODE, default="auto")
    if requested == "auto":
        requested = _native_default_tool_sandbox_mode(name)
    if requested == "process" and not LONGCAT_NATIVE_SUBAGENT_PROCESS_ISOLATION:
        return "inproc"
    if requested == "wasm" and str(name or "") not in _NATIVE_WASM_SANDBOX_TOOLS:
        return _native_default_tool_sandbox_mode(name)
    return requested


def _native_wasm_isolation_available():
    return wasm_python_sandbox.can_execute(LONGCAT_NATIVE_WASM_RUNTIME_PATH)


def _native_wasm_unavailable_observation(name, reason="wasm runtime unavailable"):
    return _native_observation(
        name,
        "WASM 子代理沙箱当前不可用，已拒绝在未授权路径中执行该任务。",
        facts=[reason],
        confidence=0.1,
        error=f"wasm_sandbox_unavailable: {reason}",
        raw={
            "sandboxMode": "wasm",
            "runtimePath": LONGCAT_NATIVE_WASM_RUNTIME_PATH,
            "wasmtimeAvailable": bool(getattr(wasm_python_sandbox, "available", False)),
        },
    )


def _native_wasm_runtime_root():
    configured = os.path.abspath(LONGCAT_NATIVE_WASM_PREOPEN_DIR) if LONGCAT_NATIVE_WASM_PREOPEN_DIR else ""
    if configured and os.path.isdir(configured):
        return configured
    runtime_path = os.path.abspath(LONGCAT_NATIVE_WASM_RUNTIME_PATH) if LONGCAT_NATIVE_WASM_RUNTIME_PATH else ""
    if runtime_path:
        inferred = os.path.dirname(os.path.dirname(runtime_path))
        if inferred and os.path.isdir(inferred):
            return inferred
    return ""


def _native_wasm_preopen_dirs():
    preopens = {}
    runtime_root = _native_wasm_runtime_root()
    if runtime_root:
        preopens["/"] = runtime_root
    workspace_root = os.path.abspath(LONGCAT_NATIVE_WASM_WORKSPACE_DIR) if LONGCAT_NATIVE_WASM_WORKSPACE_DIR else ""
    if workspace_root and os.path.isdir(workspace_root):
        preopens["/workspace"] = workspace_root
    return preopens


def _native_wasm_sandbox_meta(result):
    return {
        "mode": "wasm",
        "exit_code": int(getattr(result, "exit_code", 0) or 0),
        "timeout": bool(getattr(result, "timeout", False)),
        "module_cached": bool(getattr(result, "module_cached", False)),
        "timings_ms": getattr(result, "timings_ms", {}) if isinstance(getattr(result, "timings_ms", {}), dict) else {},
        "preopen_dirs": sorted(_native_wasm_preopen_dirs().keys()),
    }


def _native_execute_tool_wasm_isolated(name, args, context, event_queue):
    if not _native_wasm_isolation_available():
        return _native_wasm_unavailable_observation(name, "missing runtime binary or wasmtime")
    program = ""
    timeout_ms = LONGCAT_NATIVE_WASM_TIMEOUT_MS
    fuel_budget = LONGCAT_NATIVE_WASM_DEFAULT_FUEL
    if isinstance(args, dict):
        program = str(args.get("_wasm_python") or args.get("code") or args.get("program") or "").strip()
        try:
            timeout_ms = max(100, min(int(args.get("timeout_ms") or args.get("timeoutMs") or LONGCAT_NATIVE_WASM_TIMEOUT_MS), 30000))
        except Exception:
            timeout_ms = LONGCAT_NATIVE_WASM_TIMEOUT_MS
        try:
            requested_fuel = int(args.get("fuel_budget") or args.get("fuelBudget") or LONGCAT_NATIVE_WASM_DEFAULT_FUEL)
            fuel_budget = max(1_000_000, min(requested_fuel, LONGCAT_NATIVE_WASM_MAX_FUEL))
        except Exception:
            fuel_budget = LONGCAT_NATIVE_WASM_DEFAULT_FUEL
    if not program:
        return _native_wasm_unavailable_observation(name, f"tool {name} has no wasm python program")
    try:
        result = wasm_python_sandbox.execute(
            WasmPythonConfig(
                runtime_path=LONGCAT_NATIVE_WASM_RUNTIME_PATH,
                argv=[os.path.basename(LONGCAT_NATIVE_WASM_RUNTIME_PATH), "-c", program],
                env={"LONGCAT_TOOL_NAME": str(name or "")},
                preopen_dirs=_native_wasm_preopen_dirs(),
                stdin_text=json.dumps(args or {}, ensure_ascii=False),
                timeout_ms=timeout_ms,
                fuel_budget=fuel_budget,
            )
        )
        sandbox_meta = _native_wasm_sandbox_meta(result)
        _native_emit_queue(event_queue, "wasm_execution_metrics", {
            "tool": str(name or ""),
            **sandbox_meta,
        })
        if not result.ok:
            return _native_observation(
                name,
                "WASM 子代理执行超时。" if result.timeout else "WASM 子代理执行失败。",
                facts=[result.stderr or result.error or ""],
                confidence=0.1,
                error=result.error or result.stderr or "wasm execution failed",
                raw={"stdout": result.stdout, "stderr": result.stderr, "sandbox": sandbox_meta},
            )
        try:
            parsed = json.loads(result.stdout or "{}")
            if isinstance(parsed, dict):
                if "summary" in parsed or "facts" in parsed or "raw" in parsed or "success" in parsed:
                    return {
                        "tool": name,
                        "summary": _native_compact_text(parsed.get("summary") or "WASM Python 执行完成。", 1600),
                        "facts": parsed.get("facts") if isinstance(parsed.get("facts"), list) else [],
                        "cards": parsed.get("cards") if isinstance(parsed.get("cards"), list) else [],
                        "artifacts": parsed.get("artifacts") if isinstance(parsed.get("artifacts"), list) else [],
                        "sources": parsed.get("sources") if isinstance(parsed.get("sources"), list) else [],
                        "confidence": max(0, min(1, float(parsed.get("confidence") or 0.7))),
                        "success": parsed.get("success") is not False,
                        "raw": parsed.get("raw") if isinstance(parsed.get("raw"), dict) else {"result": parsed},
                        "sandbox": sandbox_meta,
                    }
                return _native_observation(
                    name,
                    "WASM Python 执行完成。",
                    facts=[_native_compact_json_text(parsed, 1200)],
                    confidence=0.7,
                    raw={"result": parsed, "sandbox": sandbox_meta},
                )
        except Exception:
            pass
        return _native_observation(
            name,
            "WASM 子代理已完成执行，但没有返回可解析的结构化结果。",
            facts=[(result.stdout or "").strip()[:600]],
            confidence=0.35,
            raw={"stdout": result.stdout, "sandbox": sandbox_meta},
        )
    except WasmSandboxUnavailable as exc:
        return _native_wasm_unavailable_observation(name, str(exc))
    except Exception as exc:
        return _native_observation(
            name,
            "WASM 子代理执行异常。",
            facts=[str(exc)],
            confidence=0.1,
            error=f"wasm_execution_failed: {exc}",
        )


def _native_execute_tool_sandboxed(name, args, context, event_queue):
    mode = _native_resolve_tool_sandbox_mode(name, context, args)
    _native_emit_queue(event_queue, "sandbox_routed", {
        "tool": name,
        "mode": mode,
    })
    if mode == "process":
        if not _native_should_process_isolate_tool(name, context):
            return _native_process_isolation_unavailable_observation(name)
        _native_prewarm_process_pool()
        return _native_execute_tool_process_isolated(name, args, context, event_queue)
    if mode == "wasm":
        return _native_execute_tool_wasm_isolated(name, args, context, event_queue)
    previous_mode = ""
    if isinstance(context, dict):
        previous_mode = str(context.get("_sandbox_forced_mode") or "")
        context["_sandbox_forced_mode"] = "inproc"
    try:
        return _native_execute_tool(name, args, context, event_queue)
    finally:
        if isinstance(context, dict):
            if previous_mode:
                context["_sandbox_forced_mode"] = previous_mode
            else:
                context.pop("_sandbox_forced_mode", None)


def _native_should_process_isolate_tool(name, context):
    return _native_tool_requires_process_isolation(name, context) and _native_process_isolation_available()


def _native_process_isolation_unavailable_observation(name):
    diagnostics = _native_process_start_diagnostics()
    reasons = [
        f"{item.get('method')}:{item.get('reason') or 'unavailable'}"
        for item in (diagnostics.get("diagnostics") or [])
        if isinstance(item, dict) and not item.get("ok")
    ]
    detail = "；".join(reasons[:4]) or "no usable multiprocessing start method"
    return _native_observation(
        name,
        "子代理进程隔离不可用，已拒绝在主进程内执行重型工具，避免阻塞主 agent。",
        facts=[detail],
        confidence=0.1,
        raw={"processStart": diagnostics},
        error=f"subagent_process_isolation_unavailable: {detail}",
    )


def _native_subagent_context_snapshot(context):
    if not isinstance(context, dict):
        return {}
    safe = {
        key: value
        for key, value in context.items()
        if not str(key).startswith("_")
    }
    safe["subagent_baseline"] = {
        "card_artifact_order": list(context.get("card_artifact_order") or []),
        "tool_cache_keys": list((context.get("tool_cache") or {}).keys()) if isinstance(context.get("tool_cache"), dict) else [],
        "tool_observation_count": int(context.get("tool_observation_count") or 0),
        "tool_observation_history_len": len(context.get("tool_observation_history") or []) if isinstance(context.get("tool_observation_history"), list) else 0,
    }
    return _native_clone_jsonable(safe)


def _native_subagent_context_delta(child_context):
    if not isinstance(child_context, dict):
        return {}
    baseline = child_context.get("subagent_baseline") if isinstance(child_context.get("subagent_baseline"), dict) else {}
    delta = {}
    if isinstance(child_context.get("card_artifacts"), dict):
        delta["card_artifacts"] = _native_clone_jsonable(child_context.get("card_artifacts") or {})
    if isinstance(child_context.get("card_artifact_order"), list):
        baseline_order = set(str(item) for item in (baseline.get("card_artifact_order") or []))
        delta["card_artifact_order"] = [
            item for item in (child_context.get("card_artifact_order") or [])
            if str(item) not in baseline_order
        ]
    if isinstance(child_context.get("tool_cache"), dict):
        baseline_keys = set(str(item) for item in (baseline.get("tool_cache_keys") or []))
        delta["tool_cache"] = {
            key: value
            for key, value in (child_context.get("tool_cache") or {}).items()
            if str(key) not in baseline_keys
        }
    if isinstance(child_context.get("tool_observation_history"), list):
        start = max(0, int(baseline.get("tool_observation_history_len") or 0))
        delta["tool_observation_history"] = _native_clone_jsonable((child_context.get("tool_observation_history") or [])[start:])
    if isinstance(child_context.get("tool_observation_count"), int):
        baseline_count = max(0, int(baseline.get("tool_observation_count") or 0))
        delta["tool_observation_count"] = max(0, int(child_context.get("tool_observation_count") or 0) - baseline_count)
    return delta


def _native_merge_subagent_context_delta(parent_context, delta):
    if not isinstance(parent_context, dict) or not isinstance(delta, dict):
        return
    with _native_context_lock(parent_context):
        if isinstance(delta.get("card_artifacts"), dict):
            parent_context.setdefault("card_artifacts", {}).update(delta.get("card_artifacts") or {})
        if isinstance(delta.get("card_artifact_order"), list):
            order = parent_context.setdefault("card_artifact_order", [])
            for item in delta.get("card_artifact_order") or []:
                if item not in order:
                    order.append(item)
        if isinstance(delta.get("tool_cache"), dict):
            parent_context.setdefault("tool_cache", {}).update(delta.get("tool_cache") or {})
        if isinstance(delta.get("tool_observation_history"), list):
            parent_context.setdefault("tool_observation_history", []).extend(delta.get("tool_observation_history") or [])
            parent_context["tool_observation_history"] = parent_context["tool_observation_history"][-12:]
        if isinstance(delta.get("tool_observation_count"), int):
            parent_context["tool_observation_count"] = int(parent_context.get("tool_observation_count") or 0) + max(0, int(delta.get("tool_observation_count") or 0))


def _native_tool_process_entry(tool_name, args, context_snapshot, result_queue):
    class _ProcessEventQueue:
        def put(self, item):
            try:
                event_name, payload = item
                result_queue.put({"type": "event", "event": event_name, "payload": payload or {}})
            except Exception:
                pass

    child_context = context_snapshot if isinstance(context_snapshot, dict) else {}
    child_context["_runtime_lock"] = threading.RLock()
    child_context["_process_isolated_subagent"] = True
    try:
        if tool_name == "__subagent_sleep_test__" and child_context.get("allow_test_tools"):
            time.sleep(max(0, min(float((args or {}).get("seconds") or 0), 10.0)))
            observation = _native_observation(tool_name, "test sleep completed", confidence=1.0)
        else:
            observation = _native_execute_tool(tool_name, args or {}, child_context, _ProcessEventQueue())
        result_queue.put({
            "type": "result",
            "observation": _native_clone_jsonable(observation),
            "context_delta": _native_subagent_context_delta(child_context),
        })
    except BaseException as exc:
        result_queue.put({
            "type": "error",
            "error": str(exc),
            "context_delta": _native_subagent_context_delta(child_context),
        })


def _native_tool_pool_worker_entry(worker_id, request_queue, result_queue, max_tasks):
    class _ProcessEventQueue:
        def __init__(self, task_id):
            self.task_id = task_id

        def put(self, item):
            try:
                event_name, payload = item
                result_queue.put({
                    "task_id": self.task_id,
                    "type": "event",
                    "event": event_name,
                    "payload": payload or {},
                })
            except Exception:
                pass

    completed = 0
    while completed < max(1, int(max_tasks or 1)):
        task = request_queue.get()
        if not isinstance(task, dict) or task.get("type") == "shutdown":
            break
        task_id = task.get("task_id") or f"task_{uuid.uuid4().hex[:12]}"
        tool_name = task.get("tool_name") or ""
        args = task.get("args") or {}
        child_context = task.get("context_snapshot") if isinstance(task.get("context_snapshot"), dict) else {}
        child_context["_runtime_lock"] = threading.RLock()
        child_context["_process_isolated_subagent"] = True
        try:
            if tool_name == "__subagent_sleep_test__" and child_context.get("allow_test_tools"):
                time.sleep(max(0, min(float((args or {}).get("seconds") or 0), 10.0)))
                observation = _native_observation(tool_name, "test sleep completed", confidence=1.0)
            else:
                observation = _native_execute_tool(tool_name, args or {}, child_context, _ProcessEventQueue(task_id))
            result_queue.put({
                "task_id": task_id,
                "type": "result",
                "observation": _native_clone_jsonable(observation),
                "context_delta": _native_subagent_context_delta(child_context),
                "worker_id": worker_id,
                "pid": os.getpid(),
            })
        except BaseException as exc:
            result_queue.put({
                "task_id": task_id,
                "type": "error",
                "error": str(exc),
                "context_delta": _native_subagent_context_delta(child_context),
                "worker_id": worker_id,
                "pid": os.getpid(),
            })
        completed += 1
    try:
        result_queue.put({"type": "worker_exit", "worker_id": worker_id, "pid": os.getpid(), "completed": completed})
    except Exception:
        pass


_NATIVE_PROCESS_POOL_LOCK = threading.RLock()
_NATIVE_PROCESS_POOL = {"method": "", "workers": [], "prewarm_started": False}


def _native_process_pool_enabled_for_tool(name):
    if not LONGCAT_NATIVE_PROCESS_POOL_ENABLED:
        return False
    return str(name or "") in _NATIVE_PROCESS_ISOLATED_TOOLS or str(name or "") == "__subagent_sleep_test__"


def _native_process_pool_worker_alive(worker):
    process = worker.get("process") if isinstance(worker, dict) else None
    return process is not None and process.is_alive()


def _native_process_pool_create_worker(method):
    if method == "forkserver":
        _native_multiprocessing_socket_tempdir()
    mp_context = multiprocessing.get_context(method)
    request_queue = mp_context.Queue()
    result_queue = mp_context.Queue()
    worker_id = f"isolated_worker_{uuid.uuid4().hex[:10]}"
    process = mp_context.Process(
        target=_native_tool_pool_worker_entry,
        args=(worker_id, request_queue, result_queue, LONGCAT_NATIVE_PROCESS_POOL_MAX_TASKS),
        daemon=True,
    )
    process.start()
    return {
        "id": worker_id,
        "method": method,
        "process": process,
        "request_queue": request_queue,
        "result_queue": result_queue,
        "lock": threading.Lock(),
        "tasks": 0,
        "started_ms": _now_ms(),
    }


def _native_process_pool_retire_worker(worker, reason="retired"):
    if not isinstance(worker, dict):
        return
    process = worker.get("process")
    try:
        if _native_process_pool_worker_alive(worker) and reason in {"max_tasks", "shutdown", "retired"}:
            worker.get("request_queue").put({"type": "shutdown"})
    except Exception:
        pass
    try:
        if process is not None:
            process.join(timeout=0.5 if reason in {"max_tasks", "shutdown", "retired"} else 0.05)
            if process.is_alive():
                process.terminate()
                process.join(timeout=1.0)
            if process.is_alive():
                process.kill()
    except Exception:
        pass
    for key in ("request_queue", "result_queue"):
        q = worker.get(key)
        try:
            q.close()
        except Exception:
            pass


def _native_process_pool_prune_locked():
    workers = []
    for worker in _NATIVE_PROCESS_POOL.get("workers") or []:
        if _native_process_pool_worker_alive(worker) and int(worker.get("tasks") or 0) < LONGCAT_NATIVE_PROCESS_POOL_MAX_TASKS:
            workers.append(worker)
        else:
            _native_process_pool_retire_worker(worker, reason="max_tasks")
    _NATIVE_PROCESS_POOL["workers"] = workers


def _native_process_pool_get_worker(name):
    method = _native_process_start_method()
    if not method:
        raise RuntimeError("no multiprocessing start method available")
    with _NATIVE_PROCESS_POOL_LOCK:
        if _NATIVE_PROCESS_POOL.get("method") and _NATIVE_PROCESS_POOL.get("method") != method:
            for worker in _NATIVE_PROCESS_POOL.get("workers") or []:
                _native_process_pool_retire_worker(worker, reason="method_changed")
            _NATIVE_PROCESS_POOL["workers"] = []
        _NATIVE_PROCESS_POOL["method"] = method
        _native_process_pool_prune_locked()
        workers = _NATIVE_PROCESS_POOL.get("workers") or []
        for worker in workers:
            if worker["lock"].acquire(blocking=False):
                return worker
        if len(workers) < LONGCAT_NATIVE_PROCESS_POOL_SIZE:
            worker = _native_process_pool_create_worker(method)
            _NATIVE_PROCESS_POOL.setdefault("workers", []).append(worker)
            worker["lock"].acquire()
            return worker
        worker = min(workers, key=lambda item: int(item.get("tasks") or 0))
    worker["lock"].acquire()
    with _NATIVE_PROCESS_POOL_LOCK:
        if not _native_process_pool_worker_alive(worker) or int(worker.get("tasks") or 0) >= LONGCAT_NATIVE_PROCESS_POOL_MAX_TASKS:
            try:
                worker["lock"].release()
            except Exception:
                pass
            return _native_process_pool_get_worker(name)
    return worker


def _native_process_pool_release_worker(worker):
    try:
        worker["lock"].release()
    except Exception:
        pass


def _native_process_pool_remove_worker(worker, reason="failed"):
    with _NATIVE_PROCESS_POOL_LOCK:
        workers = _NATIVE_PROCESS_POOL.get("workers") or []
        _NATIVE_PROCESS_POOL["workers"] = [item for item in workers if item is not worker]
    _native_process_pool_retire_worker(worker, reason=reason)


def _native_shutdown_process_pool():
    with _NATIVE_PROCESS_POOL_LOCK:
        workers = list(_NATIVE_PROCESS_POOL.get("workers") or [])
        _NATIVE_PROCESS_POOL["workers"] = []
    for worker in workers:
        _native_process_pool_retire_worker(worker, reason="shutdown")


atexit.register(_native_shutdown_process_pool)


def _native_prewarm_process_pool():
    if not LONGCAT_NATIVE_PROCESS_POOL_PREWARM or not LONGCAT_NATIVE_PROCESS_POOL_ENABLED:
        return
    if not _native_process_isolation_available():
        return
    with _NATIVE_PROCESS_POOL_LOCK:
        if _NATIVE_PROCESS_POOL.get("prewarm_started"):
            return
        _NATIVE_PROCESS_POOL["prewarm_started"] = True

    def _prewarm():
        try:
            method = _native_process_start_method()
            if not method:
                return
            with _NATIVE_PROCESS_POOL_LOCK:
                _native_process_pool_prune_locked()
                while len(_NATIVE_PROCESS_POOL.get("workers") or []) < min(1, LONGCAT_NATIVE_PROCESS_POOL_SIZE):
                    _NATIVE_PROCESS_POOL.setdefault("workers", []).append(_native_process_pool_create_worker(method))
                _NATIVE_PROCESS_POOL["method"] = method
        except Exception as exc:
            logging.debug("LongCat process pool prewarm failed: %s", exc)

    threading.Thread(target=_prewarm, name="longcat-process-pool-prewarm", daemon=True).start()


def _native_process_queue_wait(result_queue, process=None, timeout=None):
    """Wait for a multiprocessing queue item or process exit without sleep polling."""
    reader = getattr(result_queue, "_reader", None)
    handles = []
    if reader is not None:
        handles.append(reader)
    sentinel = getattr(process, "sentinel", None)
    if sentinel is not None:
        handles.append(sentinel)
    if handles:
        ready = _mp_connection_wait(handles, timeout)
        if reader is not None and reader in ready:
            try:
                return result_queue.get_nowait(), "item"
            except queue.Empty:
                return None, "empty"
        if sentinel is not None and sentinel in ready:
            return None, "process_exited"
        return None, "timeout"
    try:
        return result_queue.get(timeout=timeout), "item"
    except queue.Empty:
        return None, "timeout"


def _native_close_process_queue(process_queue):
    if process_queue is None:
        return
    try:
        process_queue.close()
    except Exception:
        pass
    try:
        process_queue.join_thread()
    except Exception:
        pass


def _native_execute_tool_process_isolated_once(name, args, context, event_queue):
    method = _native_process_start_method()
    if not method:
        raise RuntimeError("no multiprocessing start method available")
    if method == "forkserver":
        _native_multiprocessing_socket_tempdir()
    mp_context = multiprocessing.get_context(method)
    result_queue = mp_context.Queue()
    snapshot = _native_subagent_context_snapshot(context)
    process = mp_context.Process(
        target=_native_tool_process_entry,
        args=(name, args or {}, snapshot, result_queue),
        daemon=True,
    )
    process.start()
    process_info = {"pid": process.pid, "tool": name, "method": method, "started_ms": _now_ms()}
    if isinstance(context, dict):
        with _native_context_lock(context):
            context.setdefault("_subagent_processes", {})[process.pid] = process_info
    _native_emit_queue(event_queue, "subagent_process_started", process_info)
    timeout_at = time.monotonic() + max(1.0, LONGCAT_NATIVE_SUBAGENT_PROCESS_TIMEOUT_MS / 1000.0)
    token = context.get("_cancellation_token") if isinstance(context, dict) else None
    observation = None
    error = ""
    context_delta = {}
    try:
        while True:
            if token is not None and getattr(token, "cancelled", False):
                error = getattr(token, "reason", "") or "cancelled"
                break
            if time.monotonic() >= timeout_at:
                error = "subagent_process_timeout"
                break
            remaining = max(0.0, timeout_at - time.monotonic())
            item, wait_state = _native_process_queue_wait(result_queue, process, timeout=remaining)
            if wait_state != "item":
                if wait_state == "process_exited" or not process.is_alive():
                    break
                continue
            if not isinstance(item, dict):
                continue
            if item.get("type") == "event":
                _native_emit_queue(event_queue, item.get("event") or "subagent_event", item.get("payload") or {})
                continue
            context_delta = item.get("context_delta") if isinstance(item.get("context_delta"), dict) else {}
            if item.get("type") == "result":
                observation = item.get("observation") if isinstance(item.get("observation"), dict) else {}
                break
            if item.get("type") == "error":
                error = item.get("error") or "subagent process failed"
                break
        if error and process.is_alive():
            process.terminate()
            process.join(timeout=1.5)
            if process.is_alive():
                process.kill()
        else:
            process.join(timeout=1.0)
        if context_delta:
            _native_merge_subagent_context_delta(context, context_delta)
        _native_emit_queue(event_queue, "subagent_process_exited", {
            "pid": process.pid,
            "tool": name,
            "method": method,
            "exitcode": process.exitcode,
            "error": error,
        })
        if error:
            raise RuntimeError(error)
        if observation is None:
            raise RuntimeError(f"subagent process exited without result (exitcode={process.exitcode})")
        return observation
    finally:
        if isinstance(context, dict):
            with _native_context_lock(context):
                context.get("_subagent_processes", {}).pop(process.pid, None)
        _native_close_process_queue(result_queue)


def _native_execute_tool_process_isolated_pooled(name, args, context, event_queue):
    worker = _native_process_pool_get_worker(name)
    process = worker.get("process")
    task_id = f"tool_{name}_{uuid.uuid4().hex[:12]}"
    process_info = {
        "pid": process.pid,
        "tool": name,
        "method": worker.get("method"),
        "worker_id": worker.get("id"),
        "task_id": task_id,
        "pooled": True,
        "started_ms": _now_ms(),
        "worker_tasks": int(worker.get("tasks") or 0),
    }
    if isinstance(context, dict):
        with _native_context_lock(context):
            context.setdefault("_subagent_processes", {})[process.pid] = process_info
    _native_emit_queue(event_queue, "subagent_process_task_started", process_info)
    timeout_at = time.monotonic() + max(1.0, LONGCAT_NATIVE_SUBAGENT_PROCESS_TIMEOUT_MS / 1000.0)
    token = context.get("_cancellation_token") if isinstance(context, dict) else None
    observation = None
    error = ""
    context_delta = {}
    broken = False
    try:
        worker["request_queue"].put({
            "type": "tool",
            "task_id": task_id,
            "tool_name": name,
            "args": args or {},
            "context_snapshot": _native_subagent_context_snapshot(context),
        })
        while True:
            if token is not None and getattr(token, "cancelled", False):
                error = getattr(token, "reason", "") or "cancelled"
                broken = True
                break
            if time.monotonic() >= timeout_at:
                error = "subagent_process_timeout"
                broken = True
                break
            item, wait_state = _native_process_queue_wait(
                worker["result_queue"],
                process,
                timeout=max(0.0, timeout_at - time.monotonic()),
            )
            if wait_state != "item":
                if wait_state == "process_exited" or not process.is_alive():
                    error = f"subagent process exited unexpectedly (exitcode={process.exitcode})"
                    broken = True
                    break
                continue
            if not isinstance(item, dict):
                continue
            if item.get("type") == "worker_exit":
                broken = True
                if not error:
                    error = "subagent worker exited"
                break
            if item.get("task_id") != task_id:
                continue
            if item.get("type") == "event":
                _native_emit_queue(event_queue, item.get("event") or "subagent_event", item.get("payload") or {})
                continue
            context_delta = item.get("context_delta") if isinstance(item.get("context_delta"), dict) else {}
            if item.get("type") == "result":
                observation = item.get("observation") if isinstance(item.get("observation"), dict) else {}
                break
            if item.get("type") == "error":
                error = item.get("error") or "subagent process failed"
                break
        if context_delta:
            _native_merge_subagent_context_delta(context, context_delta)
        if not error and observation is None:
            error = "subagent process returned no observation"
            broken = True
        if error:
            raise RuntimeError(error)
        worker["tasks"] = int(worker.get("tasks") or 0) + 1
        _native_emit_queue(event_queue, "subagent_process_task_completed", {
            **process_info,
            "duration_ms": _now_ms() - process_info["started_ms"],
            "worker_tasks": int(worker.get("tasks") or 0),
        })
        if int(worker.get("tasks") or 0) >= LONGCAT_NATIVE_PROCESS_POOL_MAX_TASKS:
            broken = True
        return observation
    except Exception:
        if broken:
            _native_process_pool_remove_worker(worker, reason="failed")
            worker = None
        raise
    finally:
        if isinstance(context, dict) and process is not None:
            with _native_context_lock(context):
                context.get("_subagent_processes", {}).pop(process.pid, None)
        if worker is not None:
            if broken:
                _native_process_pool_remove_worker(worker, reason="max_tasks")
            else:
                _native_process_pool_release_worker(worker)


def _native_execute_tool_process_isolated(name, args, context, event_queue):
    if _native_process_pool_enabled_for_tool(name):
        return _native_execute_tool_process_isolated_pooled(name, args, context, event_queue)
    return _native_execute_tool_process_isolated_once(name, args, context, event_queue)


class NativeWorkerSubAgent:
    """Isolated worker subagent that executes specific domain tools to prevent context pollution in the main orchestrator."""
    def __init__(self, name, role_description, target_func, event_queue=None):
        self.name = name
        self.role_description = role_description
        self.target_func = target_func
        self.event_queue = event_queue

    def execute(self, args, context):
        runtime = _native_session_runtime(context, self.event_queue) if isinstance(context, dict) else None
        parent_op_id = runtime.current_op_id() if isinstance(runtime, SessionRuntime) else ""
        subagent_node = None
        work_context = context
        if isinstance(runtime, SessionRuntime) and isinstance(context, dict):
            subagent_node = runtime.create_node(
                self.name,
                "subagent",
                parent_op_id=parent_op_id,
                trajectory_id=f"{self.name}:{uuid.uuid4().hex[:8]}",
                cascade_id=runtime.run_id,
            )
            runtime.event_bus.emit(
                "subagent.started",
                "running",
                op_id=subagent_node.op_id,
                parent_op_id=parent_op_id,
                trajectory_id=subagent_node.trajectory_id,
                cascade_id=subagent_node.cascade_id,
                lane="subagent",
                payload={"name": self.name, "role": self.role_description},
            )
            work_context = runtime.fork_subagent_context(context)
            _native_consume_subagent_budget(work_context, 1)
        # Emit subagent spawn event for trace visibility
        _native_emit_queue(self.event_queue, "status", {
            "title": f"启动子代理: {self.name}",
            "detail": f"正在调遣专职子代理进行【{self.role_description}】...",
        })
        try:
            observation = self.target_func(args, work_context)
            if isinstance(work_context, ForkedContext):
                work_context.merge_back()
            observation["subagent"] = {
                "name": self.name,
                "role": self.role_description,
                "status": "success"
            }
            if isinstance(runtime, SessionRuntime) and subagent_node is not None:
                subagent_node.status = "completed"
                runtime.event_bus.emit(
                    "subagent.completed",
                    "completed",
                    op_id=subagent_node.op_id,
                    parent_op_id=parent_op_id,
                    trajectory_id=subagent_node.trajectory_id,
                    cascade_id=subagent_node.cascade_id,
                    lane="subagent",
                    payload={"name": self.name, "summary": observation.get("summary") or ""},
                )
            _native_emit_queue(self.event_queue, "status", {
                "title": f"子代理 {self.name} 执行成功",
                "detail": f"子代理已将结果规整并回传给主协调器。",
            })
            return observation
        except Exception as exc:
            if isinstance(work_context, ForkedContext):
                work_context.merge_back()
            if isinstance(runtime, SessionRuntime) and subagent_node is not None:
                subagent_node.status = "failed"
                subagent_node.error = str(exc)
                runtime.event_bus.emit(
                    "subagent.failed",
                    "failed",
                    op_id=subagent_node.op_id,
                    parent_op_id=parent_op_id,
                    trajectory_id=subagent_node.trajectory_id,
                    cascade_id=subagent_node.cascade_id,
                    lane="subagent",
                    error=str(exc),
                    payload={"name": self.name},
                )
            _native_emit_queue(self.event_queue, "status", {
                "title": f"子代理 {self.name} 执行异常",
                "detail": f"异常详情：{str(exc)}",
            })
            observation = _native_observation(self.name, "", error=str(exc))
            observation["subagent"] = {
                "name": self.name,
                "role": self.role_description,
                "status": "failed",
                "error": str(exc)
            }
            return observation


SKILLS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", ".hermes_skills")

def _route_procedural_skills(query):
    """
    Skill Router (Procedural Memory Matching) - Phase 3.
    Scans the .hermes_skills directory for matching YAML skills and injects the matched SOP.
    """
    if not os.path.exists(SKILLS_DIR):
        os.makedirs(SKILLS_DIR, exist_ok=True)
        # Pre-populate a default skill to demonstrate matching
        default_skill_path = os.path.join(SKILLS_DIR, "travel_navigation_sop.md")
        with open(default_skill_path, "w", encoding="utf-8") as f:
            f.write('''---
name: travel_navigation_sop
description: 规划前往目的地交通路线的成熟作业程序 (SOP)
triggers:
  - 路线
  - 怎么去
  - 公交
  - 地铁
  - 导航
  - 出行
steps:
  - 先调用 get_time 获取当前时间，以做早晚高峰及客运班次判断。
  - 调用 plan_navigation 获取精准的起点到终点的多模态交通路线方案。
  - 渲染显示卡片，并以友好的口吻为用户提供步行/乘车建议。
---
# 交通路线规划技能书
当你需要为用户规划路线时，请严格遵守以下步骤：
1. 确认起点与终点，并获取当前系统时间。
2. 调用 plan_navigation，并将起点、终点 and 倾向交通工具填入参数。
3. 展现交通卡片，并给出温馨出行提示（如天气状况、预计耗时）。
''')

    query_str = str(query or "").strip().lower()
    if not query_str:
        return None

    matched_skills = []
    try:
        import yaml
        for filename in os.listdir(SKILLS_DIR):
            if not filename.endswith(".md"):
                continue
            filepath = os.path.join(SKILLS_DIR, filename)
            with open(filepath, "r", encoding="utf-8") as f:
                content = f.read()
            parts = content.split("---")
            if len(parts) >= 3:
                frontmatter_str = parts[1]
                body = "---".join(parts[2:])
                try:
                    meta = yaml.safe_load(frontmatter_str)
                    if not isinstance(meta, dict):
                        continue
                    triggers = meta.get("triggers") or []
                    for trigger in triggers:
                        if trigger in query_str:
                            matched_skills.append((meta.get("name"), body))
                            break
                except Exception as ex:
                    logging.warning(f"[Skill Router] Failed to parse YAML frontmatter for {filename}: {ex}")
    except Exception as exc:
        logging.error(f"[Skill Router] Error listing skills directory: {exc}")

    if matched_skills:
        logging.info(f"[Skill Router] Matched skills: {[name for name, _ in matched_skills]}")
        sops = [f"### 匹配到的 Procedural 技能 SOP: {name}\n{body}" for name, body in matched_skills]
        return "\n\n".join(sops)
    return None


def _native_parse_json_object_from_text(text):
    raw = str(text or "").strip()
    if not raw:
        return {}
    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        pass
    match = re.search(r"\{.*\}", raw, re.S)
    if not match:
        return {}
    try:
        parsed = json.loads(match.group(0))
        return parsed if isinstance(parsed, dict) else {}
    except Exception:
        return {}


def _native_loaded_skill_summaries():
    skills = []
    if not os.path.exists(SKILLS_DIR):
        return skills
    try:
        import yaml
        for filename in sorted(os.listdir(SKILLS_DIR)):
            if not filename.endswith(".md"):
                continue
            path = os.path.join(SKILLS_DIR, filename)
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()
            parts = content.split("---")
            meta = {}
            if len(parts) >= 3:
                try:
                    loaded = yaml.safe_load(parts[1])
                    meta = loaded if isinstance(loaded, dict) else {}
                except Exception:
                    meta = {}
            skills.append({
                "name": meta.get("name") or filename[:-3],
                "description": meta.get("description") or "",
                "triggers": meta.get("triggers") or [],
                "path": path,
            })
    except Exception as exc:
        logging.warning("[Review Fork] Failed to list loaded skills: %s", exc)
    return skills


def _native_review_fork_payload(goal, history):
    tool_calls = []
    for msg in history or []:
        if not isinstance(msg, dict):
            continue
        for tc in msg.get("tool_calls") or []:
            if isinstance(tc, dict):
                name = tc.get("function", {}).get("name")
                if name:
                    tool_calls.append(name)
    loaded_skills = _native_loaded_skill_summaries()
    prompt = {
        "role": "user",
        "content": (
            "你是 LongCat 的 Background Review Fork。请按 rubric 复盘本次会话，判断是否应该沉淀或修补 procedural skill。\n"
            "Rubric: success(0-5), tool_order(0-5), evidence_quality(0-5), reusability(0-5), safety(0-5)。\n"
            "优先 patch 已加载技能；只有没有合适技能时才创建 candidate skill。只输出 JSON：\n"
            '{"scores": {...}, "action": "patch_existing|create_candidate|skip", "target_skill": "", '
            '"triggers": [], "steps": [], "rationale": "", "safety_notes": ""}\n\n'
            f"Goal: {goal}\n"
            f"Tool calls: {json.dumps(tool_calls, ensure_ascii=False)}\n"
            f"Loaded skills: {json.dumps([{k: v for k, v in s.items() if k != 'path'} for s in loaded_skills[:20]], ensure_ascii=False)}"
        ),
    }
    return {"tool_calls": tool_calls, "loaded_skills": loaded_skills, "prompt": prompt}


def _native_review_fork_fallback(goal, tool_calls, loaded_skills):
    if len(tool_calls) < 2:
        return {"action": "skip", "scores": {"reusability": 1}, "rationale": "not enough tool calls"}
    goal_text = str(goal or "")
    triggers = []
    for kw in ["车票", "火车", "高铁", "路线", "导航", "怎么去", "天气", "商户", "美食", "电影", "论文", "学术"]:
        if kw in goal_text:
            triggers.append(kw)
    if not triggers and goal_text:
        triggers = [goal_text[:8]]
    target = ""
    for skill in loaded_skills:
        haystack = " ".join([str(skill.get("name") or ""), str(skill.get("description") or ""), " ".join(map(str, skill.get("triggers") or []))])
        if any(trigger and trigger in haystack for trigger in triggers):
            target = skill.get("name") or ""
            break
    return {
        "scores": {"success": 3, "tool_order": 3, "evidence_quality": 3, "reusability": 4, "safety": 4},
        "action": "patch_existing" if target else "create_candidate",
        "target_skill": target,
        "triggers": triggers,
        "steps": [f"调用 {tool} 工具并根据结果调整下一步" for tool in tool_calls],
        "rationale": "fallback rubric based on successful multi-tool trajectory",
        "safety_notes": "由后台复盘生成，进入候选/补丁区等待后续 curator 归档。",
    }


def _native_write_review_artifact(goal, review, loaded_skills):
    os.makedirs(SKILLS_DIR, exist_ok=True)
    os.makedirs(os.path.join(SKILLS_DIR, "review_candidates"), exist_ok=True)
    action = str(review.get("action") or "skip")
    if action == "skip":
        return ""
    target_name = str(review.get("target_skill") or "").strip()
    target_path = ""
    for skill in loaded_skills or []:
        if target_name and target_name == str(skill.get("name") or ""):
            target_path = skill.get("path") or ""
            break
    patch_text = "\n".join([
        "",
        f"## Background Review Patch {datetime.now().isoformat(timespec='seconds')}",
        f"- Goal: {_native_compact_text(goal, 240)}",
        f"- Rationale: {_native_compact_text(review.get('rationale'), 500)}",
        f"- Safety: {_native_compact_text(review.get('safety_notes'), 500)}",
        "- Steps:",
        *[f"  {idx}. {_native_compact_text(step, 300)}" for idx, step in enumerate(review.get("steps") or [], 1)],
        "",
    ])
    if action == "patch_existing" and target_path and os.path.exists(target_path):
        with open(target_path, "a", encoding="utf-8") as f:
            f.write(patch_text)
        return target_path
    import yaml
    skill_name = f"review_candidate_{uuid.uuid4().hex[:8]}"
    meta = {
        "name": skill_name,
        "description": f"Background review candidate: {_native_compact_text(goal, 60)}",
        "triggers": review.get("triggers") or [],
        "scores": review.get("scores") or {},
    }
    candidate_path = os.path.join(SKILLS_DIR, "review_candidates", f"{skill_name}.md")
    with open(candidate_path, "w", encoding="utf-8") as f:
        f.write("---\n")
        f.write(yaml.safe_dump(meta, allow_unicode=True, sort_keys=False))
        f.write("---\n# Background Review Candidate\n")
        f.write(patch_text)
    return candidate_path


def _native_execute_review_fork(review_id, goal, history):
    payload = _native_review_fork_payload(goal, history)
    tool_calls = payload["tool_calls"]
    loaded_skills = payload["loaded_skills"]
    review = {}
    try:
        keys = _longcat_default_api_keys()
        if keys:
            response = _longcat_proxy_request({
                "model": LONGCAT_PROXY_MODEL,
                "messages": [payload["prompt"]],
                "temperature": 0.2,
                "max_tokens": 1200,
            }, keys[0], timeout=45)
            data = json.loads(response.read().decode("utf-8"))
            content = (((data.get("choices") or [{}])[0].get("message") or {}).get("content") or "")
            review = _native_parse_json_object_from_text(content)
    except Exception as exc:
        logging.warning("[Review Fork] LLM review failed, using fallback: %s", exc)
    if not review:
        review = _native_review_fork_fallback(goal, tool_calls, loaded_skills)
    artifact_path = _native_write_review_artifact(goal, review, loaded_skills)
    return {
        "reviewId": review_id,
        "status": "completed",
        "action": review.get("action"),
        "targetSkill": review.get("target_skill") or "",
        "artifactPath": artifact_path,
        "scores": review.get("scores") or {},
        "rationale": _native_compact_text(review.get("rationale"), 500),
        "summary": _native_background_notification_summary("review_fork_completed", {
            "action": review.get("action"),
            "detail": review.get("rationale"),
        }),
    }

def _native_review_fork_process_entry(review_id, goal, history, result_queue):
    try:
        result_queue.put({
            "type": "completed",
            "payload": _native_clone_jsonable(_native_execute_review_fork(review_id, goal, history)),
        })
    except BaseException as exc:
        result_queue.put({
            "type": "failed",
            "payload": {
                "reviewId": review_id,
                "status": "failed",
                "error": str(exc),
                "summary": _native_background_notification_summary("review_fork_failed", {"error": str(exc)}),
            },
        })


def _native_start_background_review_fork(goal, history, session_id="", context=None, event_queue=None):
    review_id = f"review_{uuid.uuid4().hex[:10]}"
    session_id = str(session_id or (context.get("session_id") if isinstance(context, dict) else "") or "").strip()[:160]
    started_payload = {
        "reviewId": review_id,
        "goal": _native_compact_text(goal, 240),
        "sessionId": session_id,
        "mode": "process",
    }
    _native_emit_queue(event_queue, "review_fork_started", started_payload)
    method = _native_process_start_method()
    if not method:
        failed_payload = {
            "reviewId": review_id,
            "status": "failed",
            "error": "review_process_isolation_unavailable",
            "summary": "Background review fork skipped: no usable isolated process start method.",
            "processStart": _native_process_start_diagnostics(),
        }
        _native_store_session_notification(session_id, "review_fork_failed", failed_payload)
        _native_emit_queue(event_queue, "review_fork_failed", failed_payload)
        return review_id
    if method == "forkserver":
        _native_multiprocessing_socket_tempdir()
    mp_context = multiprocessing.get_context(method)
    result_queue = mp_context.Queue()
    snapshot_history = _native_clone_jsonable(history or [])
    process = mp_context.Process(
        target=_native_review_fork_process_entry,
        args=(review_id, goal, snapshot_history, result_queue),
        daemon=True,
    )
    process.start()
    process_info = {
        "pid": process.pid,
        "reviewId": review_id,
        "tool": "background_review_fork",
        "method": method,
        "started_ms": _now_ms(),
    }
    if isinstance(context, dict):
        with _native_context_lock(context):
            context.setdefault("_background_review_processes", {})[process.pid] = process_info

    def _monitor_review_process():
        payload = None
        event_name = "review_fork_failed"
        error = ""
        timeout_at = time.monotonic() + max(1.0, LONGCAT_NATIVE_REVIEW_PROCESS_TIMEOUT_MS / 1000.0)
        try:
            while True:
                if time.monotonic() >= timeout_at:
                    error = "review_fork_timeout"
                    break
                item, wait_state = _native_process_queue_wait(result_queue, process, timeout=max(0.0, timeout_at - time.monotonic()))
                if wait_state != "item":
                    if wait_state == "process_exited" or not process.is_alive():
                        break
                    continue
                if not isinstance(item, dict):
                    continue
                payload = item.get("payload") if isinstance(item.get("payload"), dict) else {}
                event_name = "review_fork_completed" if item.get("type") == "completed" else "review_fork_failed"
                break
            if error and process.is_alive():
                process.terminate()
                process.join(timeout=1.0)
                if process.is_alive():
                    process.kill()
            else:
                process.join(timeout=1.0)
            if not payload:
                payload = {
                    "reviewId": review_id,
                    "status": "failed",
                    "error": error or f"review process exited without result (exitcode={process.exitcode})",
                    "summary": _native_background_notification_summary(
                        "review_fork_failed",
                        {"error": error or f"exitcode={process.exitcode}"},
                    ),
                }
                event_name = "review_fork_failed"
            if isinstance(context, dict):
                with _native_context_lock(context):
                    context.setdefault("review_trace", []).append({
                        "reviewId": payload.get("reviewId") or review_id,
                        "status": payload.get("status") or ("completed" if event_name == "review_fork_completed" else "failed"),
                        "action": payload.get("action") or "",
                        "artifactPath": payload.get("artifactPath") or "",
                        "scores": payload.get("scores") or {},
                    })
                    context["review_trace"] = context["review_trace"][-20:]
            _native_store_session_notification(session_id, event_name, payload)
            _native_emit_queue(event_queue, event_name, payload)
        finally:
            if isinstance(context, dict):
                with _native_context_lock(context):
                    context.get("_background_review_processes", {}).pop(process.pid, None)
            _native_close_process_queue(result_queue)

    threading.Thread(target=_monitor_review_process, name=f"review-monitor-{review_id}", daemon=True).start()
    return review_id


def _native_defer_background_review_fork(goal, history, session_id="", context=None, event_queue=None):
    def _starter():
        try:
            _native_start_background_review_fork(
                goal,
                history,
                session_id=session_id,
                context=context,
                event_queue=event_queue,
            )
        except Exception as exc:
            logging.error("Failed to spawn trajectory reflection: %s", exc)

    threading.Thread(
        target=_starter,
        name=f"review-starter-{uuid.uuid4().hex[:10]}",
        daemon=True,
    ).start()


class _NativeIterationBudget:

    """Enhanced dynamic budget system for engineering-grade agent loops."""

    def __init__(self, hard_limit, wall_timeout_ms, no_plan_soft_rounds, max_token_budget=48000):
        self.hard_limit = max(1, int(hard_limit or 12))
        self.max_rounds = self.hard_limit
        self.wall_timeout_ms = max(1000, int(wall_timeout_ms or 90000))
        self.no_plan_soft_rounds = max(1, int(no_plan_soft_rounds or 3))
        self.max_token_budget = max_token_budget
        self.started_at = time.monotonic()
        self.lock = threading.Lock()
        self.last_unfinished_steps = -1
        self.stuck_rounds = 0

    def elapsed_ms(self):
        return int((time.monotonic() - self.started_at) * 1000)

    def dynamic_limit(self, context):
        plan = context.get("agent_plan") if isinstance(context, dict) else None
        if not isinstance(plan, dict) or not plan.get("created"):
            if isinstance(context, dict):
                if context.get("_native_explicit_scope") or "merchant_state" in context:
                    return max(self.no_plan_soft_rounds, 10)
            return self.no_plan_soft_rounds

        steps = plan.get("steps") if isinstance(plan.get("steps"), list) else []
        unfinished = 0
        for step in steps:
            status = str((step or {}).get("status") or "").strip().lower()
            if status not in _NATIVE_PLAN_DONE_STATUSES:
                unfinished += 1

        # Check if agent is making progress or stuck
        if self.last_unfinished_steps == unfinished and unfinished > 0:
            self.stuck_rounds += 1
        else:
            self.stuck_rounds = 0
            self.last_unfinished_steps = unfinished

        if self.stuck_rounds >= 3:
            logging.warning("[Agent Loop] Agent appears stuck on plan execution. Capping budget.")
            return min(self.hard_limit, self.no_plan_soft_rounds + 2)

        planned_limit = max(self.no_plan_soft_rounds, 3 + len(steps) - unfinished + unfinished * 2)
        max_cap = int(self.hard_limit * 1.5) if self.stuck_rounds == 0 else self.hard_limit
        return min(max_cap, planned_limit)

    def can_start_round(self, round_index, context, messages=None):
        with self.lock:
            # 1. Wall time timeout
            if self.elapsed_ms() >= self.wall_timeout_ms:
                return False, "wall_timeout"

            # 2. Token budget check
            if messages:
                estimated_tokens = _lccc_estimate_messages_tokens(messages)
                if estimated_tokens >= self.max_token_budget * 0.9:
                    logging.warning(f"[Agent Loop] Context token size ({estimated_tokens}) approaching max budget ({self.max_token_budget}). Forcing stop.")
                    return False, "token_budget_exhausted"

            # 3. Dynamic soft limit check
            limit = self.dynamic_limit(context)
            if round_index >= limit:
                # If plan progress is active, allow dynamic round extension up to hard_limit * 1.5
                plan = context.get("agent_plan") if isinstance(context, dict) else None
                if isinstance(plan, dict) and plan.get("created") and self.stuck_rounds == 0 and round_index < int(self.hard_limit * 1.5):
                    pass
                else:
                    return False, "soft_round_budget"

            # 4. Global hard cap limit
            if round_index >= int(self.hard_limit * 1.5):
                return False, "hard_round_limit"

            return True, ""



def _native_context_lock(context):
    if not isinstance(context, dict):
        return threading.RLock()
    lock = context.get("_runtime_lock")
    if lock is None or not hasattr(lock, "acquire"):
        lock = threading.RLock()
        context["_runtime_lock"] = lock
    return lock


def _native_force_stop_running_subagents(context):
    if not isinstance(context, dict):
        return
    lock = _native_context_lock(context)
    with lock:
        running = list(context.get("_running_subagents", {}).values())
    for agent in running:
        agent.should_stop = True
        agent.last_stop_reason = "forced_by_timeout"
        agent_context = getattr(agent, "context", None)
        token = agent_context.get("_cancellation_token") if isinstance(agent_context, dict) else None
        if token is not None and hasattr(token, "cancel"):
            try:
                token.cancel("forced_by_timeout")
            except Exception:
                pass


def _native_intervene_subagents(context, budget, event_queue):
    if not isinstance(context, dict):
        return
    lock = _native_context_lock(context)
    with lock:
        running_subagents = list(context.get("_running_subagents", {}).values())
    
    for agent in running_subagents:
        if getattr(agent, "should_stop", False) or getattr(agent, "is_done", False):
            continue
            
        elapsed = time.monotonic() - getattr(agent, "started_at", time.monotonic())
        remaining_budget_ms = budget.wall_timeout_ms - budget.elapsed_ms()
        
        # 评估干预：抓取了2页及以上且运行超过25秒
        pages_count = len(getattr(agent, "pages", []))
        turns = getattr(agent, "turn_count", 0)
        
        if elapsed > 25.0 and pages_count >= 2:
            _native_emit_queue(event_queue, "status", {
                "title": "主代理智能介入",
                "detail": f"检测到搜索子代理已运行 {elapsed:.1f}s (抓取 {pages_count} 页，第 {turns} 轮)。主代理评估后认为抓取量已满足生成回答的要求，主动收割任务以提高响应速度。",
            })
            agent.should_stop = True
            agent.last_stop_reason = "intervened_sufficient"
        elif remaining_budget_ms < 5000:
            # Wall time 极为紧迫，强制关闭以防客户端超时
            _native_emit_queue(event_queue, "status", {
                "title": "全局时间不足强制关停",
                "detail": f"主对话窗口预算仅剩 {remaining_budget_ms/1000:.1f}s，强制关停未完成的子代理，保护系统不发生严重卡死超时。",
            })
            agent.should_stop = True
            agent.last_stop_reason = "intervened_timeout"
            agent_context = getattr(agent, "context", None)
            token = agent_context.get("_cancellation_token") if isinstance(agent_context, dict) else None
            if token is not None and hasattr(token, "cancel"):
                try:
                    token.cancel("intervened_timeout")
                except Exception:
                    pass


def _native_clone_jsonable(value, _depth=0, _seen=None):
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if _depth > 80:
        return _native_jsonable(value)
    if _seen is None:
        _seen = set()
    obj_id = id(value)
    if obj_id in _seen:
        return None
    if isinstance(value, dict):
        _seen.add(obj_id)
        try:
            return {
                str(key) if not isinstance(key, str) else key: _native_clone_jsonable(item, _depth + 1, _seen)
                for key, item in value.items()
            }
        finally:
            _seen.discard(obj_id)
    if isinstance(value, (list, tuple, set)):
        _seen.add(obj_id)
        try:
            return [_native_clone_jsonable(item, _depth + 1, _seen) for item in value]
        finally:
            _seen.discard(obj_id)
    if isinstance(value, bytes):
        try:
            return value.decode("utf-8")
        except Exception:
            return base64.b64encode(value).decode("ascii")
    return str(value)


def _native_normalize_plan_status(value, fallback="pending"):
    status = re.sub(r"\s+", "_", str(value or "").strip().lower())
    aliases = {
        "todo": "pending",
        "queued": "pending",
        "doing": "in_progress",
        "active": "in_progress",
        "started": "in_progress",
        "complete": "completed",
        "done": "completed",
        "cancelled": "cancelled",
        "canceled": "cancelled",
    }
    status = aliases.get(status, status)
    if status in {"pending", "in_progress", "completed", "blocked", "skipped", "cancelled"}:
        return status
    return fallback


def _native_normalize_plan_step(raw, index):
    item = raw if isinstance(raw, dict) else {}
    step_id = _native_compact_text(item.get("id") or item.get("step_id") or f"step_{index + 1}", 40)
    step_id = re.sub(r"[^a-zA-Z0-9_-]+", "_", step_id).strip("_")[:40] or f"step_{index + 1}"
    depends_on = item.get("depends_on") or item.get("dependsOn") or []
    if isinstance(depends_on, str):
        depends_on = [part.strip() for part in re.split(r"[,，\s]+", depends_on) if part.strip()]
    elif not isinstance(depends_on, list):
        depends_on = []
    
    tool_name = str(item.get("tool_name") or item.get("tool_hint") or item.get("tool") or "").strip()
    args = item.get("args") or item.get("arguments") or {}
    if not isinstance(args, dict):
        args = {}

    return {
        "id": step_id,
        "title": _native_compact_text(item.get("title") or item.get("name") or f"步骤 {index + 1}", 180),
        "tool_name": tool_name,
        "args": _native_jsonable(args),
        "depends_on": [_native_compact_text(dep, 40) for dep in depends_on[:8] if _native_compact_text(dep, 40)],
        "success_criteria": _native_compact_text(item.get("success_criteria") or item.get("successCriteria") or "", 260),
        "status": _native_normalize_plan_status(item.get("status")),
    }


def _native_plan_counts(plan):
    steps = plan.get("steps") if isinstance(plan, dict) and isinstance(plan.get("steps"), list) else []
    total = len(steps)
    done = 0
    blocked = 0
    for step in steps:
        status = str((step or {}).get("status") or "").strip().lower()
        if status in _NATIVE_PLAN_DONE_STATUSES:
            done += 1
        elif status == "blocked":
            blocked += 1
    return {"total": total, "done": done, "blocked": blocked, "unfinished": max(0, total - done - blocked)}


def _native_compact_plan_for_model(plan):
    if not isinstance(plan, dict):
        return {}
    counts = _native_plan_counts(plan)
    return {
        "goal": _native_compact_text(plan.get("goal"), 260),
        "status": plan.get("status") or "active",
        "counts": counts,
        "steps": [
            {
                "id": step.get("id"),
                "title": _native_compact_text(step.get("title"), 140),
                "tool_name": step.get("tool_name") or "",
                "args": step.get("args") or {},
                "depends_on": step.get("depends_on") or [],
                "status": step.get("status") or "pending",
            }
            for step in (plan.get("steps") or [])[:12]
            if isinstance(step, dict)
        ],
    }


def _native_update_agent_plan(args, context):
    args = args or {}
    mode = str(args.get("mode") or "create").strip().lower()
    if mode not in {"create", "update", "replan", "complete"}:
        mode = "create"
    try:
        confidence = max(0, min(1, float(args.get("confidence") or 0.78)))
    except Exception:
        confidence = 0.78
    reason = _native_compact_text(args.get("reason") or "", 320)
    supplied_steps = args.get("steps") if isinstance(args.get("steps"), list) else []
    normalized_steps = [_native_normalize_plan_step(step, index) for index, step in enumerate(supplied_steps[:24])]
    with _native_context_lock(context):
        existing = context.get("agent_plan") if isinstance(context.get("agent_plan"), dict) else {}
        plan = _native_clone_jsonable(existing) if existing else {
            "created": False,
            "goal": "",
            "steps": [],
            "parallel_groups": [],
            "status": "active",
            "revision": 0,
        }
        plan["created"] = True
        plan["revision"] = int(plan.get("revision") or 0) + 1
        plan["updated_at"] = datetime.now().isoformat(timespec="seconds")
        if args.get("goal"):
            plan["goal"] = _native_compact_text(args.get("goal"), 500)
        elif not plan.get("goal"):
            plan["goal"] = _native_compact_text(context.get("latest_user_text"), 500)
        if isinstance(args.get("parallel_groups"), list):
            plan["parallel_groups"] = _native_jsonable(args.get("parallel_groups"), limit=1600)
        if mode == "create":
            plan["steps"] = normalized_steps or plan.get("steps") or []
            plan["status"] = "active"
        elif mode == "update":
            by_id = {
                str(step.get("id")): dict(step)
                for step in (plan.get("steps") or [])
                if isinstance(step, dict) and step.get("id")
            }
            ordered = [str(step.get("id")) for step in (plan.get("steps") or []) if isinstance(step, dict) and step.get("id")]
            for step in normalized_steps:
                step_id = str(step.get("id"))
                merged = dict(by_id.get(step_id) or {})
                merged.update({key: value for key, value in step.items() if value not in (None, "", []) or key == "status"})
                by_id[step_id] = merged
                if step_id not in ordered:
                    ordered.append(step_id)
            plan["steps"] = [by_id[step_id] for step_id in ordered if step_id in by_id]
            plan["status"] = "active"
        elif mode == "replan":
            previous_steps = plan.get("steps") if isinstance(plan.get("steps"), list) else []
            previous_by_id = {
                str(step.get("id")): dict(step)
                for step in previous_steps
                if isinstance(step, dict) and step.get("id")
            }
            next_steps = []
            for step in normalized_steps:
                previous = previous_by_id.get(str(step.get("id"))) or {}
                merged = dict(previous)
                merged.update({key: value for key, value in step.items() if value not in (None, "", []) or key == "status"})
                if str(merged.get("status") or "") in {"blocked", "failed", "in_progress"}:
                    merged["status"] = "pending"
                next_steps.append(merged)
            plan["steps"] = next_steps or [
                {**step, "status": "pending" if str(step.get("status") or "") in {"blocked", "failed", "in_progress"} else step.get("status", "pending")}
                for step in previous_steps
                if isinstance(step, dict)
            ]
            plan["status"] = "active"
            plan["replanned_from_revision"] = max(0, int(plan.get("revision") or 1) - 1)
            plan["needs_replan"] = False
        else:
            if normalized_steps:
                by_id = {str(step.get("id")): dict(step) for step in (plan.get("steps") or []) if isinstance(step, dict) and step.get("id")}
                ordered = [str(step.get("id")) for step in (plan.get("steps") or []) if isinstance(step, dict) and step.get("id")]
                for step in normalized_steps:
                    step["status"] = "completed"
                    step_id = str(step.get("id"))
                    by_id[step_id] = {**by_id.get(step_id, {}), **step}
                    if step_id not in ordered:
                        ordered.append(step_id)
                plan["steps"] = [by_id[step_id] for step_id in ordered if step_id in by_id]
            else:
                for step in plan.get("steps") or []:
                    if isinstance(step, dict):
                        step["status"] = "completed"
            plan["status"] = "completed"
        counts = _native_plan_counts(plan)
        if counts["total"] and counts["unfinished"] == 0 and counts["blocked"] == 0:
            plan["status"] = "completed"
        context["agent_plan"] = plan
        context["plan_replan_pending"] = False
        context["dag_blocked_rounds"] = 0
    event_name = (
        "plan_completed"
        if plan.get("status") == "completed" or mode == "complete"
        else ("plan_replanned" if mode == "replan" else ("plan_created" if mode == "create" and int(plan.get("revision") or 0) == 1 else "plan_updated"))
    )
    facts = [
        f"{step.get('id')}: {step.get('title')} [{step.get('status')}]"
        for step in (plan.get("steps") or [])[:10]
        if isinstance(step, dict)
    ]
    counts = _native_plan_counts(plan)
    action_text = "完成" if event_name == "plan_completed" else ("重构" if event_name == "plan_replanned" else "更新")
    summary = f"计划已{action_text}：{counts['done']}/{counts['total']} 步完成，{counts['unfinished']} 步待处理。"
    observation = _native_observation("plan_task", summary, facts=facts, confidence=confidence, raw={"plan": plan, "reason": reason})
    observation["plan"] = _native_compact_plan_for_model(plan)
    observation["plan_event"] = event_name
    observation["reason"] = reason
    return observation


def _native_plan_completed(context):
    plan = context.get("agent_plan") if isinstance(context, dict) else None
    return isinstance(plan, dict) and plan.get("created") and plan.get("status") == "completed"


def _native_replan_system_message(context):
    plan = context.get("agent_plan") if isinstance(context, dict) else None
    compact_plan = _native_compact_plan_for_model(plan) if isinstance(plan, dict) else {}
    return {
        "role": "system",
        "content": (
            "DAG 调度器检测到当前计划连续 blocked，不能继续空等。\n"
            "你必须调用 plan_task，且 mode 必须为 replan，重构步骤、依赖或参数，使计划恢复可执行。\n"
            "不要直接回答，也不要继续调用被 blocked 的业务工具。\n"
            f"当前压缩计划：{json.dumps(compact_plan, ensure_ascii=False, default=str)}"
        ),
    }


def _native_execute_dag_step_runtime(step, context, event_queue, parent_op_id=""):
    """
    Executes a single step in a DAG plan.
    It builds a synthetic tool call dictionary and runs it via `_native_execute_tool_call_runtime`.
    """
    call = _native_dag_step_tool_call(step)
    step_context = SubagentContext(context) if isinstance(context, dict) else context
    return _native_execute_tool_call_runtime(call, step_context, event_queue, parent_op_id=parent_op_id)


def _native_dag_step_tool_call(step):
    step = step if isinstance(step, dict) else {}
    return {
        "id": str(step.get("id") or f"dag_{uuid.uuid4().hex[:10]}"),
        "type": "function",
        "function": {
            "name": str(step.get("tool_name") or ""),
            "arguments": json.dumps(step.get("args") or {}, ensure_ascii=False),
        },
    }


def _native_prepare_dag_runnable_steps(context, event_queue):
    with _native_context_lock(context):
        plan = context.get("agent_plan")
        if not plan or plan.get("status") == "completed":
            return []
        steps = plan.get("steps") or []
        if not steps:
            return []
        
        completed_ids = {s["id"] for s in steps if s.get("status") in _NATIVE_PLAN_DONE_STATUSES}
        runnable_steps = []
        for s in steps:
            if s.get("status") == "pending":
                deps = s.get("depends_on") or []
                if all(dep in completed_ids for dep in deps):
                    runnable_steps.append(s)
                    
        if not runnable_steps:
            unfinished = [s for s in steps if s.get("status") not in _NATIVE_PLAN_DONE_STATUSES]
            if unfinished:
                for s in unfinished:
                    if s.get("status") == "pending":
                        s["status"] = "blocked"
                blocked_rounds = int(context.get("dag_blocked_rounds") or 0) + 1
                context["dag_blocked_rounds"] = blocked_rounds
                if blocked_rounds >= LONGCAT_NATIVE_DAG_REPLAN_BLOCKED_ROUNDS:
                    plan["needs_replan"] = True
                    context["plan_replan_pending"] = True
                    _native_emit_queue(event_queue, "plan_replan_requested", {
                        "title": "计划需要重构",
                        "detail": f"DAG 计划连续 {blocked_rounds} 轮没有可执行步骤，要求模型用 plan_task(replan) 重构。",
                        "blockedRounds": blocked_rounds,
                        "plan": _native_compact_plan_for_model(plan),
                    })
            return []
            
        for s in runnable_steps:
            s["status"] = "in_progress"
        context["dag_blocked_rounds"] = 0
        context["plan_replan_pending"] = False
        return [_native_clone_jsonable(step) for step in runnable_steps]


def _native_finalize_dag_plan(context):
    with _native_context_lock(context):
        plan = context.get("agent_plan")
        if plan:
            counts = _native_plan_counts(plan)
            if counts["total"] > 0 and counts["unfinished"] == 0 and counts["blocked"] == 0:
                plan["status"] = "completed"


def _native_update_dag_step_status(context, step_id, status):
    with _native_context_lock(context):
        plan = context.get("agent_plan")
        steps = plan.get("steps") if isinstance(plan, dict) else []
        for step in steps or []:
            if str(step.get("id") or "") == str(step_id or ""):
                step["status"] = status
                return


def _native_dag_step_error_result(step, exc):
    return {
        "call_id": str(step.get("id") or f"dag_{uuid.uuid4().hex[:10]}"),
        "name": str(step.get("tool_name") or ""),
        "args": step.get("args") or {},
        "title": step.get("title") or _native_tool_title(step.get("tool_name") or ""),
        "observation": {"success": False, "error": str(exc)},
        "model_observation": {"success": False, "error": str(exc)},
    }


def _native_run_dag_steps_streaming(runnable_steps, context, budget, event_queue):
    runnable_steps = [step for step in (runnable_steps or []) if isinstance(step, dict)]
    if not runnable_steps:
        return
    batch_started = time.monotonic()
    runtime = _native_session_runtime(context, event_queue) if isinstance(context, dict) else None
    scheduler_op_id = runtime.current_op_id() if isinstance(runtime, SessionRuntime) else ""
    
    _native_emit_queue(event_queue, "status", {
        "title": "并发执行 DAG 计划步骤",
        "detail": f"正在并发拉起 {len(runnable_steps)} 个就绪计划步骤：{', '.join(s['title'] for s in runnable_steps)}。",
    })

    dag_calls = [_native_dag_step_tool_call(step) for step in runnable_steps]
    steps_by_id = {str(step.get("id") or ""): step for step in runnable_steps}

    def execute_dag_call(call):
        step = steps_by_id.get(str(call.get("id") or "")) or {}
        return _native_execute_dag_step_runtime(step, context, event_queue, scheduler_op_id)

    try:
        for res in _native_run_tool_batch_streaming(
            dag_calls,
            context,
            event_queue,
            budget,
            parent_op_id=scheduler_op_id,
            batch_kind="dag",
            timeout_reason="dag_batch_timeout",
            execute_call=execute_dag_call,
        ):
            step_id = str((res or {}).get("call_id") or "")
            step = steps_by_id.get(step_id) or {}
            success = (res.get("observation") or {}).get("success") is not False
            _native_update_dag_step_status(context, step_id, "completed" if success else "failed")
            _native_emit_queue(event_queue, "dag_step_completed", {
                "stepId": step_id,
                "title": step.get("title"),
                "tool": step.get("tool_name") or res.get("name"),
                "success": success,
            })
            _native_finalize_dag_plan(context)
            if res:
                yield res
    finally:
        _native_emit_queue(event_queue, "tool_batch_completed", {
            "title": "DAG 并发批次完成",
            "detail": f"并发计划步骤运行完成，耗时 {int((time.monotonic() - batch_started) * 1000)}ms。",
            "tools": [s["tool_name"] for s in runnable_steps],
        })
        _native_finalize_dag_plan(context)


def _native_schedule_dag_plan_steps(context, budget, event_queue):
    """
    Stream DAG scheduling updates.
    Yields a started event with the synthetic assistant tool_calls, then yields
    one result event per completed DAG step.
    """
    runnable_steps = _native_prepare_dag_runnable_steps(context, event_queue)
    if not runnable_steps:
        return
    yield {
        "type": "started",
        "steps": runnable_steps,
        "tool_calls": [_native_dag_step_tool_call(step) for step in runnable_steps],
    }
    for result in _native_run_dag_steps_streaming(runnable_steps, context, budget, event_queue):
        yield {"type": "result", "result": result}


