def _amap_search_around_pages(location, radius=1000, keywords="", types="", sortrule="distance", fetch_limit=None, strategy_trace=None, trace_base=None):
    fetch_limit = _amap_fetch_limit(fetch_limit)
    page_size = min(25, max(1, fetch_limit))
    max_pages = max(1, int(math.ceil(fetch_limit / page_size)))
