@app.route('/mcp/12306/search', methods=['POST'])
def mcp_12306_search():
    data = request.get_json(force=True, silent=True) or {}
    try:
        tool_name, arguments = _rail12306_tool_payload(data)
        fallback = None
        try:
            text = _call_12306_mcp_tool(tool_name, arguments)
        except Exception:
            if tool_name != "get-tickets":
                raise
            text = ""
        if tool_name == "get-tickets" and (not text or _rail12306_json_error_text(text)):
            fallback = _rail12306_official_ticket_query(arguments)
            text = fallback.get("text") or ""
        if not text:
            text = "12306 暂未返回可用结果。"
        trains = (fallback or {}).get("trains")
        if trains is None and tool_name == "get-tickets":
            trains = _rail12306_parse_text_trains(text)
        return jsonify({
            "success": True,
            "tool": tool_name,
            "arguments": arguments,
            "text": text,
            "trains": trains,
            "source": (fallback or {}).get("source") or "12306-mcp",
        })
    except ValueError as exc:
        return jsonify({"success": False, "error": str(exc)}), 400
    except FileNotFoundError:
        return jsonify({"success": False, "error": "服务器缺少 Node/npm，无法运行 12306-mcp。"}), 503
    except (subprocess.TimeoutExpired, asyncio.TimeoutError):
        return jsonify({"success": False, "error": "12306 MCP 查询超时。"}), 504
    except Exception as exc:
        return jsonify({"success": False, "error": str(exc)}), 502


@app.route('/api/longcat/chat', methods=['POST'])
def longcat_chat_proxy():
    payload = request.get_json(silent=True) or {}
    if not isinstance(payload, dict):
        return _longcat_error_response("请求体必须是 JSON 对象", 400)

    payload["model"] = LONGCAT_PROXY_MODEL
    keys = _longcat_proxy_keys(request.headers.get("X-LongCat-Api-Key", ""))
    if not keys:
        return _longcat_error_response("服务端缺少 LongCat API Key", 503)

    wants_stream = bool(payload.get("stream"))
    last_error = ""

    if wants_stream:
        def _stream_response():
            yield b": connected\n\n"
            stream_error = ""
            for index, key in enumerate(keys):
                upstream = None
                try:
                    upstream = _longcat_proxy_request(payload, key)
                    while True:
                        chunk = upstream.read1(8192)
                        if not chunk:
                            break
                        yield chunk
                    return
                except urllib.error.HTTPError as exc:
                    error_body = exc.read() or b""
                    stream_error = error_body.decode("utf-8", errors="replace") or str(exc)
                    if index < len(keys) - 1 and _longcat_proxy_should_retry(exc.code):
                        continue
                    yield _sse_message("error", {
                        "success": False,
                        "status": exc.code,
                        "error": stream_error,
                    }).encode("utf-8")
                    return
                except Exception as exc:
                    stream_error = str(exc)
                    if index < len(keys) - 1:
                        continue
                finally:
                    if upstream is not None:
                        try:
                            upstream.close()
                        except Exception:
                            pass
            yield _sse_message("error", {
                "success": False,
                "error": stream_error or "LongCat 代理请求失败",
            }).encode("utf-8")

        return Response(
            stream_with_context(_stream_response()),
            status=200,
            content_type="text/event-stream; charset=utf-8",
            headers={
                "Cache-Control": "no-cache",
                "X-Accel-Buffering": "no",
            },
        )

    for index, key in enumerate(keys):
        try:
            upstream = _longcat_proxy_request(payload, key)
            content_type = upstream.headers.get("Content-Type") or (
                "text/event-stream; charset=utf-8" if wants_stream else "application/json; charset=utf-8"
            )

            response_body = upstream.read()
            status_code = getattr(upstream, "status", 200)
            upstream.close()
            return Response(response_body, status=status_code, content_type=content_type)
        except urllib.error.HTTPError as exc:
            error_body = exc.read() or b""
            content_type = exc.headers.get("Content-Type") or "application/json; charset=utf-8"
            last_error = error_body.decode("utf-8", errors="replace") or str(exc)
            if index < len(keys) - 1 and _longcat_proxy_should_retry(exc.code):
                continue
            return Response(error_body, status=exc.code, content_type=content_type)
        except Exception as exc:
            last_error = str(exc)
            if index < len(keys) - 1:
                continue

    return _longcat_error_response(last_error or "LongCat 代理请求失败", 502)

@app.route('/api/baidu/chat', methods=['POST'])
def baidu_chat_proxy():
    """Proxy to Baidu Qianfan using server-side encrypted key."""
    if not BAIDU_API_KEY:
        return jsonify({'error': 'Baidu API key not configured'}), 503
    payload = request.get_json(force=True, silent=True) or {}
    body = json.dumps(payload, ensure_ascii=False).encode('utf-8')
    req = urllib.request.Request(
        BAIDU_CHAT_URL, data=body, method='POST',
        headers={'Content-Type': 'application/json',
                 'Authorization': f'Bearer {BAIDU_API_KEY}'})
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            ct = r.headers.get('Content-Type', 'application/json')
            if payload.get('stream'):
                def _s():
                    while True:
                        c = r.read(4096)
                        if not c: break
                        yield c
                return Response(stream_with_context(_s()), status=r.status, content_type=ct)
            return Response(r.read(), status=r.status, content_type=ct)
    except urllib.error.HTTPError as e:
        return Response(e.read(), status=e.code, content_type='application/json')
    except Exception as e:
        return jsonify({'error': str(e)}), 502



@app.route('/api/baidu/search', methods=['POST'])
def baidu_search_proxy():
    """Proxy web search requests to Baidu Qianfan AI Search API."""
    if not LONGCAT_SEARCH_BAIDU_ENABLED:
        return jsonify({
            'references': [],
            'answer': '',
            'provider': 'baidu',
            'available': False,
            'enabled': False,
            'error': 'disabled',
        })
    if not BAIDU_API_KEY:
        return jsonify({'error': 'Baidu API key not configured'}), 503
    data = request.get_json(force=True, silent=True) or {}
    query = (data.get('query') or '').strip()
    if not query:
        return jsonify({'error': 'query is required'}), 400
    payload = {'messages': [{'role': 'user', 'content': query}]}
    body = json.dumps(payload, ensure_ascii=False).encode('utf-8')
    req = urllib.request.Request(
        'https://qianfan.baidubce.com/v2/ai_search/web_search',
        data=body, method='POST',
        headers={'Content-Type': 'application/json',
                 'Authorization': f'Bearer {BAIDU_API_KEY}'})
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            raw = resp.read()
            result = json.loads(raw)
            return jsonify({
                'references': result.get('references', []),
                'answer': (result.get('choices') or [{}])[0].get('message', {}).get('content', ''),
                'request_id': result.get('request_id', ''),
            })
    except urllib.error.HTTPError as exc:
        return Response(exc.read(), status=exc.code,
                        content_type='application/json')
    except Exception as exc:
        return jsonify({'error': str(exc)}), 502


