def _agent_search_depth(value, profile=None):
    depth = str(value or "").strip().lower()
    if depth in AGENT_SEARCH_BUDGETS:
        return depth
    if profile and depth in {"", "auto", "dynamic", "target"}:
        candidate = str(profile.get("expectedDepth") or profile.get("expected_depth") or "").strip().lower()
        if candidate in AGENT_SEARCH_BUDGETS:
            return candidate
    return "fast"


def _agent_clean_search_goal(goal):
    text = str(goal or "")
    text = re.split(r"\n\nAgent orchestration context:", text, flags=re.I)[0]
    text = re.split(r"\n\n记忆召回线索", text)[0]
    text = re.sub(r"^(请|帮我|给我|查一下|搜索|联网搜索|看看|解释一下|讲讲)\s*", "", text.strip(), flags=re.I)
    return re.sub(r"\s+", " ", text).strip()


def _agent_goal_profile(goal):
    clean = _agent_clean_search_goal(goal)
    lowered = clean.lower()
    wants_deep = bool(re.search(r"深度|深入|全面|系统|多源|交叉验证|反复|继续找|换关键词|找不到就|探索|调研|deep\s*research|comprehensive|multi[- ]?source|research", clean, re.I))
    concept_grounding = bool(re.search(r"是什么|什么是|解释|原理|机制|架构|如何理解|讲讲|介绍|对比|区别|综述|定义|含义|怎么工作|why\b|what\s+is|how\s+does|overview|tutorial", clean, re.I))
    freshness = bool(re.search(r"最新|今天|现在|当前|近期|新闻|价格|政策|版本|发布|更新|官网|官方|文档|202\d|latest|current|recent|today", clean, re.I))
    repo_or_code = bool(re.search(r"github|hugging\s*face|huggingface|hf-mirror|仓库|源码|代码|repo|repository|模型权重|数据集|space|readme|implementation", clean, re.I))
    paper = bool(re.search(r"论文|paper|arxiv|doi|pubmed|pmid|综述|学术|benchmark", clean, re.I))
    high_stakes = bool(re.search(r"医疗|法律|金融|股票|投资|政策|法规|签证|税务|药物|疾病|合同|保险|medical|legal|finance|regulation", clean, re.I))
    movie = bool(re.search(r"电影|影片|院线|上映|导演|主演|票房|影评|预告|片长|豆瓣|猫眼|imdb|tmdb|mtime|写给阿嬷的情书", clean, re.I))
    event = bool(re.search(r"大会|会议|峰会|发布会|主题演讲|keynote|conference|developer\s+conference|i/o|io\s*大会|google\s+i/o|谷歌\s*io", clean, re.I))
    product = bool(re.search(r"产品|平台|云|官网|官方|文档|api|服务|模型|千问云|qianwen|qwen\s*cloud", clean, re.I))
    exact_urls = re.findall(r"https?://[^\s<>)\"']+", clean, flags=re.I)
    # Strategy is a *hint* — the LLM decides actual depth via system prompt guidance (MiroFlow-style)
    suggested_strategy = "brief"
    if wants_deep:
        suggested_strategy = "exploratory"
    elif movie or event or product:
        suggested_strategy = "thorough"
    elif concept_grounding or repo_or_code or paper or high_stakes:
        suggested_strategy = "thorough"
    elif freshness and len(clean) > 18:
        suggested_strategy = "thorough"

    # Legacy depth mapping for backward compatibility
    legacy_depth = "fast"
    if suggested_strategy == "exploratory":
        legacy_depth = "deep"
    elif suggested_strategy == "thorough":
        legacy_depth = "adaptive"

    return {
        "goal": clean,
        "intent": "repo_code" if repo_or_code else ("paper" if paper else ("movie" if movie else ("event" if event else ("product" if product else ("concept" if concept_grounding else ("fresh" if freshness else "fact")))))),
        "conceptGrounding": concept_grounding,
        "freshness": "current" if freshness else "stable",
        "repoOrCode": repo_or_code,
        "paper": paper,
        "movie": movie,
        "event": event,
        "product": product,
        "highStakes": high_stakes,
        "wantsDeep": wants_deep,
        "exactUrls": exact_urls[:6],
        "suggestedStrategy": suggested_strategy,
        "expectedDepth": legacy_depth,
        "shouldFetchFullPage": concept_grounding or repo_or_code or wants_deep or high_stakes or movie or event or product or freshness,
        "shouldInspectRepos": repo_or_code or bool(re.search(r"agent|framework|模型|代码|源码|github|hugging", lowered, re.I)),
    }


def _agent_merge_goal_profile(goal, supplied):
    profile = _agent_goal_profile(goal)
    if isinstance(supplied, dict):
        for key, value in supplied.items():
            if key in {"expectedDepth", "expected_depth"} and str(value).strip().lower() in AGENT_SEARCH_BUDGETS:
                profile["expectedDepth"] = str(value).strip().lower()
            elif key in profile and value not in (None, ""):
                profile[key] = value
    return profile


def _agent_budget_for_profile(depth, profile, overrides=None):
    """Build search budget — MiroFlow-style: LLM can override any field.

    Base budget comes from the depth profile (backward compat), but
    `overrides` (supplied by the LLM via tool args) take precedence.
    """
    budget = dict(AGENT_SEARCH_BUDGETS.get(depth) or AGENT_SEARCH_BUDGETS["fast"])
    if profile.get("conceptGrounding") and depth == "fast":
        budget["full_page_limit"] = max(budget["full_page_limit"], 2)
        budget["min_full_pages"] = max(budget["min_full_pages"], 1)
    if profile.get("movie") or profile.get("event") or profile.get("product"):
        if depth == "fast":
            budget["full_page_limit"] = max(budget["full_page_limit"], 1)
            budget["min_full_pages"] = max(budget["min_full_pages"], 1)
        else:
            budget["pages_per_query"] = max(budget["pages_per_query"], 8)
            budget["full_page_limit"] = max(budget["full_page_limit"], 3)
            budget["min_valid_pages"] = max(budget["min_valid_pages"], 2)
            budget["min_full_pages"] = max(budget["min_full_pages"], 2)
            budget["min_score"] = max(float(budget["min_score"]), 2.6)
    if profile.get("repoOrCode") and depth != "fast":
        budget["min_score"] = max(2.0, budget["min_score"] - 0.25)
    if profile.get("highStakes"):
        budget["min_valid_pages"] = max(budget["min_valid_pages"], 3)
        budget["min_full_pages"] = max(budget["min_full_pages"], 2)
        budget["min_score"] = max(budget["min_score"], 3.2)
    # MiroFlow-style: LLM can dynamically override any budget field
    if isinstance(overrides, dict):
        for key, value in overrides.items():
            if key in budget and isinstance(value, (int, float)):
                budget[key] = value
    return budget


def _agent_search_initial_queries(goal, profile, first_query=None, limit=6):
    base = _agent_clean_search_goal(goal)
    first = _agent_clean_search_goal(first_query or "") if first_query else ""
    year = datetime.now().year
    variants = [first, base]
    if profile.get("repoOrCode"):
        variants.extend([
            f"{base} GitHub README",
            f"{base} Hugging Face",
            f"{base} source code implementation",
        ])
    if profile.get("paper"):
        variants.extend([f"{base} arxiv paper", f"{base} benchmark paper", f"{base} survey"])
    if profile.get("conceptGrounding"):
        variants.extend([
            f"{base} 原理 架构",
            f"{base} explained documentation",
            f"{base} implementation details",
        ])
    if profile.get("freshness") == "current":
        variants.extend([f"{base} {year}", f"{base} latest"])
    for url in profile.get("exactUrls") or []:
        variants.insert(0, url)
    seen = set()
    result = []
    for item in variants:
        clean = re.sub(r"\s+", " ", str(item or "")).strip()
        key = _agent_search_query_key(clean)
        if len(clean) < 2 or len(clean) > 140 or key in seen:
            continue
        seen.add(key)
        result.append(clean)
        if len(result) >= limit:
            break
    return result or [base]


def _baidu_search_references(query, timeout=30):
    if not BAIDU_API_KEY:
        raise RuntimeError("Baidu API key not configured")
    query = str(query or "").strip()
    if not query:
        return [], ""
    payload = {'messages': [{'role': 'user', 'content': query}]}
    body = json.dumps(payload, ensure_ascii=False).encode('utf-8')
    req = urllib.request.Request(
        LONGCAT_BAIDU_API_URL,
        data=body, method='POST',
        headers={'Content-Type': 'application/json',
                 'Accept': 'application/json',
                 'User-Agent': 'LongCat/1.0',
                 'Authorization': f'Bearer {BAIDU_API_KEY}'})
    opener = None
    if LONGCAT_BAIDU_PROXY:
        opener = urllib.request.build_opener(
            urllib.request.ProxyHandler({
                "http": LONGCAT_BAIDU_PROXY,
                "https": LONGCAT_BAIDU_PROXY,
            })
        )
    open_fn = opener.open if opener else urllib.request.urlopen
    with open_fn(req, timeout=timeout) as resp:
        raw = resp.read()
    result = json.loads(raw)
    return result.get('references', []) or [], (result.get('choices') or [{}])[0].get('message', {}).get('content', '')


def _agent_ref_snippet(ref):
    if not isinstance(ref, dict):
        return ""
    return (
        ref.get("abstract")
        or ref.get("content")
        or ref.get("summary")
        or ref.get("snippet")
        or ref.get("description")
        or ref.get("body")
        or ""
    )


def _agent_normalize_baidu_refs(refs):
    normalized = []
    for index, ref in enumerate(refs or [], 1):
        if not isinstance(ref, dict):
            continue
        item = dict(ref)
        url = str(item.get("url") or item.get("link") or item.get("href") or "").strip()
        title = str(item.get("title") or item.get("name") or url).strip()
        snippet = _native_compact_text(_agent_ref_snippet(item), 900)
        item["title"] = _native_compact_text(title, 220)
        item["url"] = url
        item["abstract"] = snippet
        item["content"] = snippet
        item["domain"] = item.get("domain") or _agent_url_domain(url)
        item["sourceEngine"] = "baidu"
        item["searchEngine"] = "baidu"
        item["engineRank"] = index
        item["providerRank"] = index
        normalized.append(item)
    return normalized


def _agent_search_baidu_refs(query, use_cache=None, timeout=30):
    """Call Baidu search. Cache is opt-in so production remains fresh by default."""
    if not LONGCAT_SEARCH_BAIDU_ENABLED:
        return [], "", False
    enabled = AGENT_SEARCH_BAIDU_CACHE_ENABLED if use_cache is None else bool(use_cache)
    key = _agent_search_query_key(query)
    now = time.time()
    if enabled and key:
        with AGENT_SEARCH_BAIDU_CACHE_LOCK:
            cached = AGENT_SEARCH_BAIDU_CACHE.get(key)
            if cached and now - float(cached.get("stored_at") or 0) <= AGENT_SEARCH_BAIDU_CACHE_TTL_SECONDS:
                return list(cached.get("refs") or []), str(cached.get("answer") or ""), True
    refs, answer = _baidu_search_references(query, timeout=timeout)
    refs = _agent_normalize_baidu_refs(refs)
    if enabled and key:
        with AGENT_SEARCH_BAIDU_CACHE_LOCK:
            AGENT_SEARCH_BAIDU_CACHE[key] = {
                "stored_at": now,
                "refs": refs,
                "answer": answer,
            }
            if len(AGENT_SEARCH_BAIDU_CACHE) > 128:
                oldest = sorted(AGENT_SEARCH_BAIDU_CACHE.items(), key=lambda item: item[1].get("stored_at") or 0)[:24]
                for old_key, _old_value in oldest:
                    AGENT_SEARCH_BAIDU_CACHE.pop(old_key, None)
    return refs, answer, False


def _agent_search_result_identity(ref):
    url = str((ref or {}).get("url") or "").strip()
    if url:
        parsed = urlparse(url)
        host = (parsed.netloc or "").lower().lstrip("www.")
        path = re.sub(r"/+$", "", parsed.path or "")
        if host or path:
            return f"{host}{path}".strip().lower()
    title = re.sub(r"\s+", " ", str((ref or {}).get("title") or "")).strip().lower()
    return title


def _agent_search_searxng_refs(query, limit=None, timeout=None):
    limit = max(3, min(20, int(limit or LONGCAT_SEARCH_SEARXNG_LIMIT)))
    timeout = LONGCAT_SEARCH_SEARXNG_TIMEOUT_SECONDS if timeout is None else timeout
    allowed_engines = {item.lower() for item in LONGCAT_SEARCH_SEARXNG_ENGINES if item}
    if not LONGCAT_SEARCH_SEARXNG_ENABLED:
        return [], {"provider": "searxng", "available": False, "enabled": False, "error": "disabled", "allowedEngines": sorted(allowed_engines)}
    if not LONGCAT_SEARCH_SEARXNG_URL:
        return [], {"provider": "searxng", "available": False, "enabled": True, "error": "missing_url", "allowedEngines": sorted(allowed_engines)}
    params = {"q": query, "format": "json", "pageno": 1}
    if allowed_engines:
        params["engines"] = ",".join(sorted(allowed_engines))
    endpoint = f"{LONGCAT_SEARCH_SEARXNG_URL}/search?{urlencode(params)}"
    req = urllib.request.Request(
        endpoint,
        headers={
            "Accept": "application/json",
            "User-Agent": "LongCat/1.0",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            data = json.loads(resp.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        return [], {
            "provider": "searxng",
            "available": False,
            "enabled": True,
            "error": str(exc)[:240],
            "url": LONGCAT_SEARCH_SEARXNG_URL,
            "allowedEngines": sorted(allowed_engines),
        }
    raw_results = list(data.get("results") or [])
    raw_results.sort(key=lambda item: float(item.get("score") or 0), reverse=True)
    refs = []
    engine_counts = {}
    raw_engine_counts = {}
    rejected_reasons = {}
    for item in raw_results:
        engines = [str(eng or "").lower() for eng in (item.get("engines") or []) if str(eng or "").strip()]
        for eng in engines:
            raw_engine_counts[eng] = raw_engine_counts.get(eng, 0) + 1

    for item in raw_results:
        url = str(item.get("url") or "").strip()
        title = str(item.get("title") or url).strip()
        abstract = str(
            item.get("content")
            or item.get("description")
            or item.get("snippet")
            or ""
        ).strip()
        engines = [str(eng or "").lower() for eng in (item.get("engines") or []) if str(eng or "").strip()]
        if allowed_engines and engines and not (set(engines) & allowed_engines):
            rejected_reasons["engine_not_allowed"] = rejected_reasons.get("engine_not_allowed", 0) + 1
            continue
        for eng in engines:
            engine_counts[eng] = engine_counts.get(eng, 0) + 1
        provider_rank = len(refs) + 1
        refs.append(
            {
                "title": _native_compact_text(title, 220),
                "url": url,
                "abstract": _native_compact_text(abstract, 900),
                "content": _native_compact_text(abstract, 900),
                "domain": _agent_url_domain(url),
                "sourceEngine": "searxng",
                "searchEngine": "searxng",
                "engineRank": provider_rank,
                "providerRank": provider_rank,
                "engines": engines,
                "publishedDate": item.get("publishedDate") or "",
                "score": float(item.get("score") or 0),
                "rawScore": float(item.get("score") or 0),
            }
        )
        if len(refs) >= limit:
            break
    return refs, {
        "provider": "searxng",
        "available": True,
        "enabled": True,
        "error": "",
        "count": len(refs),
        "url": LONGCAT_SEARCH_SEARXNG_URL,
        "engineCounts": engine_counts,
        "rawEngineCounts": raw_engine_counts,
        "engines": sorted(engine_counts.keys()),
        "allowedEngines": sorted(allowed_engines),
        "rawCount": len(raw_results),
        "rejectedCount": sum(rejected_reasons.values()),
        "rejectedReasons": rejected_reasons,
    }


def _agent_merge_dual_search_refs(query, baidu_refs, searxng_refs, limit=12):
    merged = {}
    query_tokens = _agent_search_tokens(query)
    engine_results = [("baidu", list(baidu_refs or [])), ("searxng", list(searxng_refs or []))]
    for engine_name, refs in engine_results:
        for rank, ref in enumerate(refs, 1):
            if not isinstance(ref, dict):
                continue
            key = _agent_search_result_identity(ref)
            if not key:
                continue
            title = _native_compact_text(ref.get("title") or ref.get("url") or "", 220)
            snippet = _native_compact_text(_agent_ref_snippet(ref), 900)
            item = merged.get(key)
            if item is None:
                item = {
                    "title": title,
                    "url": str(ref.get("url") or "").strip(),
                    "abstract": snippet,
                    "content": snippet,
                    "domain": ref.get("domain") or _agent_url_domain(ref.get("url")),
                    "sourceEngine": engine_name,
                    "searchEngine": engine_name,
                    "engineMatches": [],
                    "_fusionScore": 0.0,
                    "_bestTitleLen": len(title),
                    "_bestSnippetLen": len(snippet),
                    "_rawRefs": [],
                }
                merged[key] = item
            if title and len(title) > item.get("_bestTitleLen", 0):
                item["title"] = title
                item["_bestTitleLen"] = len(title)
            if snippet and len(snippet) > item.get("_bestSnippetLen", 0):
                item["abstract"] = snippet
                item["content"] = snippet
                item["_bestSnippetLen"] = len(snippet)
            if not item.get("domain") and ref.get("url"):
                item["domain"] = _agent_url_domain(ref.get("url"))
            overlap = _agent_text_token_overlap_score(query_tokens, f"{title} {snippet}")
            rrf_score = 1.0 / (60 + rank)
            engine_bonus = 0.04 if engine_name == "baidu" else 0.03
            searx_score_bonus = 0.0
            if engine_name == "searxng":
                try:
                    searx_score_bonus = min(0.06, float(ref.get("score") or 0) * 0.01)
                except Exception:
                    searx_score_bonus = 0.0
            item["_fusionScore"] += rrf_score + engine_bonus + searx_score_bonus + overlap * 0.02
            item["engineMatches"].append(
                {
                    "engine": engine_name,
                    "rank": rank,
                    "score": ref.get("score"),
                }
            )
            item["_rawRefs"].append(ref)
    ranked = []
    for item in merged.values():
        engines = [match.get("engine") for match in item.get("engineMatches") or [] if match.get("engine")]
        if len(set(engines)) > 1:
            item["sourceEngine"] = "baidu+searxng"
            item["searchEngine"] = "baidu+searxng"
            item["_fusionScore"] += 0.08
        item["dualRouteScore"] = round(float(item.get("_fusionScore") or 0.0), 6)
        ranked.append(item)
    ranked.sort(
        key=lambda item: (
            -float(item.get("dualRouteScore") or 0.0),
            len(item.get("engineMatches") or []),
            item.get("title") or "",
        )
    )
    results = []
    for index, item in enumerate(ranked[: max(4, min(20, int(limit or 12)))]):
        # Collect SearxNG internal engines from raw refs
        searxng_engines = []
        for raw_ref in item.get("_rawRefs") or []:
            if raw_ref.get("sourceEngine") == "searxng" or raw_ref.get("searchEngine") == "searxng":
                for eng in raw_ref.get("engines") or []:
                    if eng and eng not in searxng_engines:
                        searxng_engines.append(eng)
        results.append(
            {
                "title": item.get("title") or "",
                "url": item.get("url") or "",
                "abstract": item.get("abstract") or "",
                "content": item.get("content") or "",
                "domain": item.get("domain") or _agent_url_domain(item.get("url")),
                "sourceEngine": item.get("sourceEngine") or "",
                "searchEngine": item.get("searchEngine") or "",
                "engineMatches": item.get("engineMatches") or [],
                "engines": searxng_engines,
                "dualRouteScore": item.get("dualRouteScore") or 0,
                "rank": index + 1,
            }
        )
    return results


def _agent_baidu_network_error(exc):
    message = str(exc)[:240]
    if not LONGCAT_BAIDU_PROXY and re.search(r"SSL|EOF|timed out|Connection reset", message, re.I):
        try:
            host = urlparse(LONGCAT_BAIDU_API_URL).hostname or "qianfan.baidubce.com"
            ip = socket.gethostbyname(host)
        except Exception:
            ip = ""
        if ip.startswith("198.18.") or ip.startswith("198.19."):
            message = (
                message
                + " | baidu_dns_fake_ip_detected:"
                + ip
                + "; set LONGCAT_BAIDU_PROXY or fix DNS/proxy routing"
            )[:360]
    return message


def _agent_search_dual_refs(
    query,
    use_cache=None,
    baidu_limit=10,
    searxng_limit=10,
    merged_limit=12,
    timeout=15,
    context=None,
):
    baidu_meta = {
        "provider": "baidu",
        "available": bool(LONGCAT_SEARCH_BAIDU_ENABLED),
        "enabled": bool(LONGCAT_SEARCH_BAIDU_ENABLED),
        "keyConfigured": bool(BAIDU_API_KEY),
        "cached": False,
        "count": 0,
        "error": "" if LONGCAT_SEARCH_BAIDU_ENABLED else "disabled",
    }
    searxng_meta = {
        "provider": "searxng",
        "available": False,
        "enabled": bool(LONGCAT_SEARCH_SEARXNG_ENABLED),
        "urlConfigured": bool(LONGCAT_SEARCH_SEARXNG_URL),
        "allowedEngines": sorted({item.lower() for item in LONGCAT_SEARCH_SEARXNG_ENGINES if item}),
        "count": 0,
        "error": "" if LONGCAT_SEARCH_SEARXNG_ENABLED else "disabled",
    }
    baidu_refs, baidu_answer = [], ""
    searxng_refs = []

    # 1. Try Baidu first if enabled
    if LONGCAT_SEARCH_BAIDU_ENABLED:
        if isinstance(context, dict):
            context["active_search_engine"] = "Baidu"
        try:
            baidu_timeout = min(float(timeout or LONGCAT_SEARCH_BAIDU_TIMEOUT_SECONDS), LONGCAT_SEARCH_BAIDU_TIMEOUT_SECONDS)
            refs, answer, cached = _agent_search_baidu_refs(query, use_cache, timeout=baidu_timeout)
            baidu_refs = list(refs or [])[: max(3, min(20, int(baidu_limit or 10)))]
            baidu_answer = str(answer or "")
            baidu_meta.update({"available": True, "cached": bool(cached), "count": len(baidu_refs), "error": ""})
        except Exception as exc:
            baidu_meta.update({"available": False, "error": _agent_baidu_network_error(exc)})

    # 2. Check if we need to fall back to SearXNG (if Baidu has 0 results, failed, or is disabled)
    need_searxng = not LONGCAT_SEARCH_BAIDU_ENABLED or not baidu_meta.get("available") or len(baidu_refs) == 0

    if LONGCAT_SEARCH_SEARXNG_ENABLED and need_searxng:
        if isinstance(context, dict):
            context["active_search_engine"] = "SearXNG"
        try:
            searxng_timeout = min(float(timeout or LONGCAT_SEARCH_SEARXNG_TIMEOUT_SECONDS), LONGCAT_SEARCH_SEARXNG_TIMEOUT_SECONDS)
            refs, meta = _agent_search_searxng_refs(query, searxng_limit, timeout=searxng_timeout)
            searxng_refs = list(refs or [])
            if isinstance(meta, dict):
                searxng_meta.update(meta)
        except Exception as exc:
            searxng_meta.update({"available": False, "error": str(exc)[:240]})

    merged_refs = _agent_merge_dual_search_refs(
        query,
        baidu_refs,
        searxng_refs,
        limit=merged_limit,
    )
    meta = {
        "engines": {
            "baidu": baidu_meta,
            "searxng": searxng_meta,
        },
        "providers": [name for name, meta_item in (("baidu", baidu_meta), ("searxng", searxng_meta)) if meta_item.get("enabled")],
        "availableProviders": [name for name, meta_item in (("baidu", baidu_meta), ("searxng", searxng_meta)) if meta_item.get("available")],
        "mergedCount": len(merged_refs),
        "hasAnswerBox": bool(baidu_answer),
        "searxngEngineCounts": searxng_meta.get("engineCounts") or {},
        "searxngRawEngineCounts": searxng_meta.get("rawEngineCounts") or {},
    }
    return merged_refs, baidu_answer, meta


def _agent_search_provider_status():
    baidu_host = urlparse(LONGCAT_BAIDU_API_URL).hostname or "qianfan.baidubce.com"
    baidu_resolved_ip = ""
    try:
        baidu_resolved_ip = socket.gethostbyname(baidu_host)
    except Exception:
        baidu_resolved_ip = ""
    baidu_fake_ip = bool(baidu_resolved_ip.startswith("198.18.") or baidu_resolved_ip.startswith("198.19."))
    return {
        "baidu": {
            "enabled": bool(LONGCAT_SEARCH_BAIDU_ENABLED),
            "available": bool(LONGCAT_SEARCH_BAIDU_ENABLED and BAIDU_API_KEY),
            "keyConfigured": bool(BAIDU_API_KEY),
            "timeoutSeconds": LONGCAT_SEARCH_BAIDU_TIMEOUT_SECONDS,
            "apiHost": baidu_host,
            "resolvedIp": baidu_resolved_ip,
            "fakeIpDetected": baidu_fake_ip,
            "proxyConfigured": bool(LONGCAT_BAIDU_PROXY),
        },
        "searxng": {
            "enabled": bool(LONGCAT_SEARCH_SEARXNG_ENABLED),
            "available": bool(LONGCAT_SEARCH_SEARXNG_ENABLED and LONGCAT_SEARCH_SEARXNG_URL),
            "urlConfigured": bool(LONGCAT_SEARCH_SEARXNG_URL),
            "url": LONGCAT_SEARCH_SEARXNG_URL,
            "allowedEngines": sorted({item.lower() for item in LONGCAT_SEARCH_SEARXNG_ENGINES if item}),
            "timeoutSeconds": LONGCAT_SEARCH_SEARXNG_TIMEOUT_SECONDS,
        },
        "providerTimeoutSeconds": LONGCAT_SEARCH_PROVIDER_TIMEOUT_SECONDS,
        "sourcePolicy": {
            "lowQualityDomains": list(LONGCAT_SEARCH_LOW_QUALITY_DOMAINS),
            "lowQualityPatterns": list(LONGCAT_SEARCH_LOW_QUALITY_PATTERNS),
            "minRelevanceScore": LONGCAT_SEARCH_MIN_RELEVANCE_SCORE,
        },
        "fetch": {
            "markitdown": bool(LONGCAT_FETCH_MARKITDOWN_ENABLED),
            "markitdownUrlFallback": bool(LONGCAT_FETCH_MARKITDOWN_URL_FALLBACK),
            "mineru": bool(LONGCAT_FETCH_MINERU_ENABLED),
            "mineruTokenConfigured": bool(_mineru_token()),
            "jina": bool(LONGCAT_FETCH_JINA_ENABLED),
            "serper": bool(LONGCAT_FETCH_SERPER_ENABLED and LONGCAT_FETCH_SERPER_API_KEY),
        },
    }


def _agent_soup_from_html(html):
    if BeautifulSoup is None:
        return None
    try:
        return BeautifulSoup(html or "", "lxml")
    except Exception:
        return BeautifulSoup(html or "", "html.parser")


def _agent_normalize_clean_text(text, max_chars=None):
    lines = []
    seen = set()
    for raw_line in str(text or "").replace("\r", "\n").split("\n"):
        stripped = raw_line.strip()
        # Detect Markdown structural lines that must be preserved as-is
        is_table_line = "|" in stripped and stripped.count("|") >= 2
        is_list_line = bool(re.match(r"^(\*|-|\+|\d+[.)]) ", stripped))
        is_heading_line = stripped.startswith("#")

        if is_table_line or is_list_line or is_heading_line:
            # Preserve structural formatting — only light trim, no whitespace collapse
            line = stripped
        else:
            line = re.sub(r"\s+", " ", raw_line).strip()

        if not line:
            if lines and lines[-1]:
                lines.append("")
            continue
        lowered = line.lower()
        # Skip very short lines ONLY for non-structural content
        if len(line) <= 2 and not is_table_line and not is_list_line:
            continue
        if re.search(r"^(登录|注册|分享|收藏|广告|相关阅读|相关推荐|免责声明|版权|返回顶部|点击|展开全文)$", line, re.I):
            continue
        key = lowered[:160]
        if key in seen and len(line) < 220:
            continue
        seen.add(key)
        lines.append(line)
    cleaned = "\n".join(lines)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned).strip()
    if max_chars:
        cleaned = cleaned[:max_chars]
    return cleaned


def _agent_meta_content(soup, *names):
    if soup is None:
        return ""
    lookup = {str(name or "").lower() for name in names if name}
    for tag in soup.find_all("meta"):
        attrs = {
            str(tag.get("property") or "").lower(),
            str(tag.get("name") or "").lower(),
            str(tag.get("itemprop") or "").lower(),
        }
        if lookup & attrs:
            value = (tag.get("content") or "").strip()
            if value:
                return value
    return ""


def _agent_extract_page_date(soup, text):
    value = _agent_meta_content(
        soup,
        "article:published_time",
        "article:modified_time",
        "pubdate",
        "publishdate",
        "date",
        "datepublished",
        "datecreated",
        "last-modified",
        "og:updated_time",
    )
    if value:
        return _native_compact_text(value, 80)
    source = str(text or "")
    match = re.search(r"20\d{2}[年./-]\d{1,2}(?:[月./-]\d{1,2}日?)?(?:\s+\d{1,2}:\d{2})?", source)
    if match:
        return match.group(0)
    match = re.search(r"\b20\d{2}\b", source)
    return match.group(0) if match else ""


def _agent_extract_page_images(soup, url, title="", limit=16):
    if soup is None:
        return []
    images = []

    def add(src, alt="", kind="image", width="", height=""):
        src = str(src or "").strip()
        if not src or src.startswith("data:") or src.startswith("blob:"):
            return
        abs_url = urljoin(url, src)
        if not abs_url.startswith(("http://", "https://")):
            return
        if any(item.get("url") == abs_url for item in images):
            return
        images.append({
            "url": abs_url,
            "alt": _native_compact_text(alt, 180),
            "kind": kind,
            "sourcePage": url,
            "pageTitle": _native_compact_text(title, 160),
            "width": str(width or "")[:16],
            "height": str(height or "")[:16],
        })

    for name in ("og:image", "twitter:image", "twitter:image:src", "image"):
        value = _agent_meta_content(soup, name)
        if value:
            add(value, title, "meta")
    for img in soup.find_all("img"):
        src = img.get("src") or img.get("data-src") or img.get("data-original") or img.get("data-lazy-src")
        alt = img.get("alt") or img.get("title") or ""
        add(src, alt, "inline", img.get("width") or "", img.get("height") or "")
        if len(images) >= limit:
            break
    return images[:limit]


def _agent_clean_html_text(html, url=""):
    html = str(html or "")
    extracted = ""
    if _trafilatura is not None:
        try:
            extracted = _trafilatura.extract(
                html,
                url=url or None,
                include_comments=False,
                include_tables=True,
                include_links=False,
                no_fallback=False,
                favor_precision=True,
            ) or ""
        except Exception:
            extracted = ""
    if extracted and len(extracted.strip()) > 180:
        return _agent_normalize_clean_text(extracted, AGENT_SEARCH_PAGE_RAW_MAX_CHARS), "trafilatura"
    if _ReadabilityDocument is not None and BeautifulSoup is not None:
        try:
            doc = _ReadabilityDocument(html)
            summary_html = doc.summary(html_partial=True)
            soup = _agent_soup_from_html(summary_html)
            text = soup.get_text(separator="\n", strip=True) if soup else ""
            if len(text.strip()) > 180:
                return _agent_normalize_clean_text(text, AGENT_SEARCH_PAGE_RAW_MAX_CHARS), "readability"
        except Exception:
            pass
    soup = _agent_soup_from_html(html)
    if soup is None:
        text = re.sub(r"<[^>]+>", " ", html)
        return _agent_normalize_clean_text(text, AGENT_SEARCH_PAGE_RAW_MAX_CHARS), "regex"
    for tag in list(soup.find_all([
        "script", "style", "noscript", "nav", "footer", "header", "aside",
        "iframe", "svg", "form", "button", "input", "select", "textarea",
        "picture", "source",
    ])):
        try:
            tag.decompose()
        except Exception:
            pass
    noise_re = re.compile(r"(nav|footer|header|sidebar|comment|share|advert|ad-|ads|recommend|related|breadcrumb|cookie|login|subscribe|toolbar)", re.I)
    for tag in list(soup.find_all(True)):
        ident = " ".join([
            str(tag.get("id") or ""),
            " ".join(tag.get("class") or []),
            str(tag.get("role") or ""),
        ])
        if ident and noise_re.search(ident):
            try:
                tag.decompose()
            except Exception:
                pass
    main = None
    for selector in [
        lambda s: s.find("article"),
        lambda s: s.find(id=re.compile(r"(article|content|main|post|entry)", re.I)),
        lambda s: s.find("main"),
    ]:
        try:
            candidate = selector(soup)
            if candidate and len(candidate.get_text(strip=True)) > 200:
                main = candidate
                break
        except Exception:
            pass
    text = (main or soup.body or soup).get_text(separator="\n", strip=True)
    return _agent_normalize_clean_text(text, AGENT_SEARCH_PAGE_RAW_MAX_CHARS), "beautifulsoup"


def _agent_clean_page_from_html(url, html, final_url="", content_type="", status_code=200):
    soup = _agent_soup_from_html(html)
    meta_title = _agent_meta_content(soup, "og:title", "twitter:title")
    page_title = meta_title
    if not page_title and soup is not None and soup.title:
        page_title = soup.title.get_text(" ", strip=True)
    # Sanitize title: strip markdown image syntax and common noise
    if page_title:
        page_title = re.sub(r"!\[([^\]]*)\]\([^)]+\)", r"\1", page_title).strip()
        page_title = re.sub(r"^[\s\-–—|]+|[\s\-–—|]+$", "", page_title).strip()
    clean_text, method = _agent_clean_html_text(html, final_url or url)
    date_hint = _agent_extract_page_date(soup, clean_text or html[:4000])
    images = _agent_extract_page_images(soup, final_url or url, title=page_title)
    canonical_url = ""
    if soup is not None:
        try:
            canonical = soup.find("link", rel=lambda value: value and "canonical" in str(value).lower())
            canonical_url = urljoin(final_url or url, canonical.get("href")) if canonical and canonical.get("href") else ""
        except Exception:
            canonical_url = ""
    return {
        "url": final_url or url,
        "canonicalUrl": canonical_url,
        "title": _native_compact_text(page_title or final_url or url, 240),
        "author": _native_compact_text(_agent_meta_content(soup, "author", "article:author", "twitter:creator"), 120),
        "text": clean_text,
        "images": images,
        "dateHint": date_hint,
        "cleanMethod": method,
        "cleanScore": round(min(1.0, len(clean_text) / 2200) + (0.15 if method in {"trafilatura", "readability"} else 0), 3),
        "rawChars": len(str(html or "")),
        "textChars": len(clean_text),
        "contentType": content_type,
        "statusCode": status_code,
        "fetchStatus": "ok" if len(clean_text.strip()) > 120 else "weak_text",
    }


def _agent_sanitize_title_text(text):
    """Remove markdown image syntax and common noise from title text."""
    noise_words = {"logo", "icon", "img", "image", "pic", "photo", "banner", "ad", "广告", "到百度首页", "百度首页", "首页"}

    def img_repl(m):
        alt = m.group(1).strip()
        if len(alt) >= 4 and alt.lower() not in noise_words:
            return alt
        return ""

    text = re.sub(r"!\[([^\]]*)\]\([^)]+\)", img_repl, text)
    text = re.sub(r"^\[([^\]]+)\]\([^)]+\)\s*$", r"\1", text)
    text = re.sub(r"^[\s\-–—|•·]+|[\s\-–—|•·]+$", "", text).strip()
    return text


def _agent_extract_markdown_title(text, fallback=""):
    source = str(text or "")
    # Look for explicit Title: or # heading
    for pattern in (r"^\s*Title:\s*(.+)$", r"^\s*#\s+(.+)$"):
        match = re.search(pattern, source, re.I | re.M)
        if match:
            title = _agent_sanitize_title_text(match.group(1))
            if title:
                return _native_compact_text(title, 240)
    # Find first non-empty, non-image line
    for line in source.splitlines():
        line = line.strip()
        if not line:
            continue
        # Skip pure markdown image lines
        if re.match(r"^!\[([^\]]*)\]\([^)]+\)\s*$", line):
            continue
        # Strip inline markdown images and noise
        clean = _agent_sanitize_title_text(line)
        if clean:
            return _native_compact_text(clean, 240)
    return _native_compact_text(fallback, 240)


def _agent_extract_markdown_images(text, url, title="", limit=16):
    images = []
    seen = set()
    for alt, src in re.findall(r"!\[([^\]]*)\]\((https?://[^)\s]+)\)", str(text or "")):
        src = src.strip()
        if src in seen:
            continue
        seen.add(src)
        images.append({
            "url": src,
            "alt": _native_compact_text(alt or title, 180),
            "kind": "markdown",
            "sourcePage": url,
            "pageTitle": _native_compact_text(title, 160),
        })
        if len(images) >= limit:
            break
    return images


def _agent_clean_page_from_markdown(url, text, method="markdown_reader", fetch_trace=None):
    clean_text = _agent_normalize_clean_text(text, AGENT_SEARCH_PAGE_RAW_MAX_CHARS)
    title = _agent_extract_markdown_title(clean_text, fallback=url)
    return {
        "url": url,
        "canonicalUrl": url,
        "title": title or url,
        "author": "",
        "text": clean_text,
        "images": _agent_extract_markdown_images(clean_text, url, title=title),
        "dateHint": _agent_extract_page_date(None, clean_text),
        "cleanMethod": method,
        "cleanScore": round(min(1.0, len(clean_text) / 2600) + 0.08, 3),
        "rawChars": len(str(text or "")),
        "textChars": len(clean_text),
        "contentType": "text/markdown",
        "statusCode": 200,
        "fetchStatus": "ok" if len(clean_text.strip()) > 120 else "weak_text",
        "fetchTrace": fetch_trace or [],
    }


def _agent_fetch_jina_markdown(url, timeout):
    if not LONGCAT_FETCH_JINA_ENABLED:
        return "", "disabled"
    # Jina's reader endpoint also works without a key for some deployments; use
    # auth only when configured so local/offline deployments still fall through.
    jina_url = f"{LONGCAT_FETCH_JINA_BASE_URL}/{url}"
    headers = {
        "User-Agent": "LongCat/1.0",
        "X-Base": "final",
        "X-Engine": "browser",
        "X-With-Generated-Alt": "true",
        "X-With-Iframe": "true",
        "X-With-Shadow-Dom": "true",
    }
    if LONGCAT_FETCH_JINA_API_KEY:
        headers["Authorization"] = f"Bearer {LONGCAT_FETCH_JINA_API_KEY}"
    try:
        req = urllib.request.Request(jina_url, headers=headers)
        with urllib.request.urlopen(req, timeout=max(timeout, 12)) as resp:
            raw = resp.read(AGENT_SEARCH_PAGE_RAW_MAX_CHARS * 4)
            status = getattr(resp, "status", 200) or 200
            if status >= 400:
                return "", f"http_{status}"
        return raw.decode("utf-8", errors="replace"), ""
    except Exception as exc:
        return "", str(exc)[:240]


def _agent_fetch_serper_markdown(url, timeout):
    if not LONGCAT_FETCH_SERPER_ENABLED or not LONGCAT_FETCH_SERPER_API_KEY:
        return "", "disabled_or_no_key"
    endpoint = LONGCAT_FETCH_SERPER_SCRAPE_URL
    body = json.dumps({"url": url}, ensure_ascii=False).encode("utf-8")
    headers = {
        "X-API-KEY": LONGCAT_FETCH_SERPER_API_KEY,
        "Content-Type": "application/json",
        "User-Agent": "LongCat/1.0",
    }
    try:
        req = urllib.request.Request(endpoint, data=body, method="POST", headers=headers)
        with urllib.request.urlopen(req, timeout=max(timeout, 12)) as resp:
            raw = resp.read(AGENT_SEARCH_PAGE_RAW_MAX_CHARS * 4)
        text = raw.decode("utf-8", errors="replace")
        try:
            data = json.loads(text)
            return str(data.get("text") or data.get("markdown") or data.get("content") or text), ""
        except Exception:
            return text, ""
    except Exception as exc:
        return "", str(exc)[:240]


def _agent_markitdown_text_from_bytes(raw, extension=""):
    if not LONGCAT_FETCH_MARKITDOWN_ENABLED:
        return ""
    tmp_path = ""
    try:
        if extension:
            with tempfile.NamedTemporaryFile(delete=False, suffix=extension) as tmp:
                tmp.write(raw or b"")
                tmp_path = tmp.name
            return md_converter.convert(tmp_path).text_content or ""
        stream = io.BytesIO(raw or b"")
        return md_converter.convert_stream(stream).text_content or ""
    except Exception:
        return ""
    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass


def _agent_markitdown_text_from_url(url):
    """MarkItDown direct URL parsing — skip bytes download for faster fetch."""
    if not LONGCAT_FETCH_MARKITDOWN_ENABLED:
        return ""
    try:
        return md_converter.convert(url).text_content or ""
    except Exception:
        return ""


def _agent_content_extension(content_type, url=""):
    guessed = ""
    if content_type:
        guessed = mimetypes.guess_extension(str(content_type).split(";", 1)[0].strip()) or ""
    if guessed in {".jpe", ".jpeg"}:
        guessed = ".jpg"
    parsed_ext = os.path.splitext(urlparse(str(url or "")).path)[1].lower()
    if parsed_ext and len(parsed_ext) <= 12:
        return parsed_ext
    return guessed or ""


def _agent_fetch_raw_url(url, timeout):
    req = urllib.request.Request(url, headers={
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/pdf,application/octet-stream,*/*;q=0.8',
        'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
        'Connection': 'close',
    })
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read(AGENT_SEARCH_PAGE_RAW_MAX_CHARS * 4)
        return {
            "raw": raw,
            "encoding": resp.headers.get_content_charset() or "",
            "contentType": resp.headers.get('Content-Type', ''),
            "finalUrl": resp.geturl() or url,
            "statusCode": getattr(resp, "status", 200) or 200,
        }


def _agent_mineru_model_for_url(url, content_type=""):
    parsed = urlparse(str(url or ""))
    lower_url = str(url or "").lower()
    lower_type = str(content_type or "").lower()
    if _looks_like_pdf_url(lower_url) or "application/pdf" in lower_type or _is_known_reader_pdf_url(parsed):
        return MINERU_DEFAULT_MODEL
    return MINERU_HTML_MODEL


def _agent_should_try_mineru(url, content_type="", raw=b"", local_text=""):
    if not LONGCAT_FETCH_MINERU_ENABLED:
        return False
    if not _mineru_token():
        return False
    parsed = urlparse(str(url or ""))
    lower_url = str(url or "").lower()
    lower_type = str(content_type or "").lower()
    if _looks_like_pdf_url(lower_url) or "application/pdf" in lower_type or _is_known_reader_pdf_url(parsed):
        return True
    paperish = bool(re.search(r"arxiv|biorxiv|medrxiv|europepmc|pubmed|pmc\.ncbi|doi\.org|openreview", lower_url, re.I))
    if paperish and len(str(local_text or "").strip()) < 600:
        return True
    if raw and len(raw) >= LONGCAT_FETCH_MINERU_MIN_BYTES and len(str(local_text or "").strip()) < 600:
        return True
    return False


def _agent_should_try_mineru_by_url(url):
    """URL-only MinerU trigger — no bytes needed. Used in the direct-URL fetch path."""
    if not LONGCAT_FETCH_MINERU_ENABLED:
        return False
    if not _mineru_token():
        return False
    parsed = urlparse(str(url or ""))
    lower_url = str(url or "").lower()
    if _looks_like_pdf_url(lower_url) or _is_known_reader_pdf_url(parsed):
        return True
    if re.search(r"arxiv|biorxiv|medrxiv|europepmc|pubmed|pmc\.ncbi|doi\.org|openreview", lower_url, re.I):
        return True
    return False


def _agent_clean_page_from_mineru_payload(url, payload, fetch_trace=None):
    content_type = str(payload.get("content_type") or "").lower()
    content = str(payload.get("content") or "")
    text = str(payload.get("text") or "")
    if content_type == "html" and content:
        page = _agent_clean_page_from_html(
            url,
            content,
            final_url=url,
            content_type="text/html; mineru=1",
            status_code=200,
        )
        if text and len(text) > len(page.get("text") or ""):
            page["text"] = _agent_normalize_clean_text(text, AGENT_SEARCH_PAGE_RAW_MAX_CHARS)
            page["textChars"] = len(page["text"])
        page["cleanMethod"] = "mineru_html"
    else:
        source = text or content
        page = _agent_clean_page_from_markdown(url, source, method="mineru_markdown", fetch_trace=fetch_trace)
    page["fetchTrace"] = fetch_trace or []
    page["fetchStatus"] = "ok" if len(str(page.get("text") or "").strip()) > 120 else "weak_text"
    return page


def _agent_fetch_mineru_page(url, timeout=None, fetch_trace=None):
    fetch_trace = fetch_trace if isinstance(fetch_trace, list) else []
    if not LONGCAT_FETCH_MINERU_ENABLED:
        return None, "disabled"
    if not _mineru_token():
        return None, "no_token"
    model_version = _agent_mineru_model_for_url(url)
    deadline = time.time() + float(timeout or LONGCAT_FETCH_MINERU_TIMEOUT_SECONDS)
    try:
        task_payload = _create_mineru_task(url, model_version)
    except Exception as exc:
        return None, str(exc)[:240]
    if task_payload.get("state") == "done" and isinstance(task_payload.get("result"), dict):
        return _agent_clean_page_from_mineru_payload(url, task_payload["result"], fetch_trace=fetch_trace), ""
    task_id = task_payload.get("task_id") or ""
    last_payload = task_payload
    while task_id and time.time() < deadline:
        time.sleep(max(0.2, min(5.0, LONGCAT_FETCH_MINERU_POLL_SECONDS)))
        try:
            last_payload = _poll_mineru_task(task_id)
        except Exception as exc:
            return None, str(exc)[:240]
        if last_payload.get("state") == "done":
            return _agent_clean_page_from_mineru_payload(url, last_payload, fetch_trace=fetch_trace), ""
        if last_payload.get("state") == "failed":
            return None, (last_payload.get("err_msg") or "failed")[:240]
        task_id = last_payload.get("task_id") or task_id
    if task_id:
        return None, f"pending:{task_id}"
    return None, str(last_payload.get("err_msg") or "pending")[:240]


def _agent_cache_clean_page(cache_key, clean_page):
    with AGENT_SEARCH_PAGE_CACHE_LOCK:
        AGENT_SEARCH_PAGE_CACHE[cache_key] = {"stored_at": time.time(), "cleanPage": clean_page}
        if len(AGENT_SEARCH_PAGE_CACHE) > AGENT_SEARCH_PAGE_CACHE_MAX_ITEMS:
            oldest = sorted(AGENT_SEARCH_PAGE_CACHE.items(), key=lambda item: item[1].get("stored_at") or 0)[:32]
            for old_key, _old_value in oldest:
                AGENT_SEARCH_PAGE_CACHE.pop(old_key, None)


def _agent_fetch_clean_page(url, timeout=None):
    url = str(url or "").strip()
    if not url:
        return {"url": "", "text": "", "fetchStatus": "empty_url", "error": "empty url"}
    timeout = AGENT_SEARCH_PAGE_TIMEOUT_SECONDS if timeout is None else timeout
    cache_key = url.lower()
    now = time.time()
    with AGENT_SEARCH_PAGE_CACHE_LOCK:
        cached = AGENT_SEARCH_PAGE_CACHE.get(cache_key)
        if cached and now - float(cached.get("stored_at") or 0) <= AGENT_SEARCH_PAGE_CACHE_TTL_SECONDS:
            if isinstance(cached.get("cleanPage"), dict):
                return dict(cached.get("cleanPage") or {})
            if cached.get("text"):
                return {
                    "url": url,
                    "title": url,
                    "text": str(cached.get("text") or ""),
                    "images": [],
                    "dateHint": "",
                    "cleanMethod": "legacy_cache",
                    "cleanScore": 0.45,
                    "rawChars": len(str(cached.get("text") or "")),
                    "textChars": len(str(cached.get("text") or "")),
                    "fetchStatus": "ok",
                }
    fetch_trace = []
    raw = b""
    enc = ""
    ctype = ""
    final_url = url
    status_code = 0

    # Raw HTTP download first so every parser shares the same timeout-bounded bytes.
    try:
        raw_payload = _agent_fetch_raw_url(url, timeout)
        raw = raw_payload.get("raw") or b""
        enc = raw_payload.get("encoding") or ""
        ctype = raw_payload.get("contentType") or ""
        final_url = raw_payload.get("finalUrl") or url
        status_code = raw_payload.get("statusCode") or 200
        fetch_trace.append({"method": "raw_http", "success": bool(raw), "error": "", "statusCode": status_code, "contentType": ctype})
    except Exception as exc:
        fetch_trace.append({"method": "raw_http", "success": False, "error": str(exc)[:240]})

    local_text = ""
    if raw:
        extension = _agent_content_extension(ctype, final_url or url)
        markdown_text = _agent_markitdown_text_from_bytes(raw, extension=extension)
        markitdown_success = bool(markdown_text and len(markdown_text.strip()) > 120)
        fetch_trace.append({"method": "markitdown_bytes", "success": markitdown_success, "error": "" if markdown_text else "empty"})
        if markitdown_success:
            clean_page = _agent_clean_page_from_markdown(final_url or url, markdown_text, method="markitdown_bytes", fetch_trace=fetch_trace)
            _agent_cache_clean_page(cache_key, clean_page)
            return dict(clean_page)
        local_text = markdown_text or ""

        is_textual = bool(re.search(r"text/html|application/xhtml|text/plain|application/xml|application/json", ctype or "", re.I))
        if is_textual or not ctype or b"<html" in raw[:4096].lower():
            if not enc:
                m = re.search(br'<meta[^>]+charset=["\']?([a-zA-Z0-9_\-]+)', raw[:4096], re.I)
                enc = (m.group(1).decode('ascii', 'ignore') if m else '') or 'utf-8'
            html = raw.decode(enc, errors='replace')
            clean_page = _agent_clean_page_from_html(url, html, final_url=final_url, content_type=ctype, status_code=status_code)
            local_text = clean_page.get("text") or local_text
            fetch_trace.append({"method": clean_page.get("cleanMethod") or "html_extract", "success": clean_page.get("fetchStatus") in {"ok", "weak_text"}, "error": ""})
            if clean_page.get("fetchStatus") == "ok":
                clean_page["fetchTrace"] = fetch_trace
                _agent_cache_clean_page(cache_key, clean_page)
                return dict(clean_page)

    if _agent_should_try_mineru(url, ctype, raw, local_text) or (_agent_should_try_mineru_by_url(url) and not raw):
        mineru_page, mineru_error = _agent_fetch_mineru_page(url, timeout=LONGCAT_FETCH_MINERU_TIMEOUT_SECONDS, fetch_trace=fetch_trace)
        fetch_trace.append({"method": "mineru_url", "success": bool(mineru_page and len(str(mineru_page.get("text") or "").strip()) > 120), "error": mineru_error})
        if mineru_page and len(str(mineru_page.get("text") or "").strip()) > 120:
            mineru_page["fetchTrace"] = fetch_trace
            _agent_cache_clean_page(cache_key, mineru_page)
            return dict(mineru_page)

    if LONGCAT_FETCH_MARKITDOWN_URL_FALLBACK:
        md_url_text = _agent_markitdown_text_from_url(url)
        md_url_success = bool(md_url_text and len(md_url_text.strip()) > 120)
        fetch_trace.append({"method": "markitdown_url", "success": md_url_success, "error": "" if md_url_text else "empty"})
        if md_url_success:
            clean_page = _agent_clean_page_from_markdown(url, md_url_text, method="markitdown_url", fetch_trace=fetch_trace)
            _agent_cache_clean_page(cache_key, clean_page)
            return dict(clean_page)

    # Optional external fallback services stay behind local parsers.
    jina_text, jina_error = _agent_fetch_jina_markdown(url, timeout)
    fetch_trace.append({"method": "jina_reader", "success": bool(jina_text and len(jina_text.strip()) > 120), "error": jina_error})
    if jina_text and len(jina_text.strip()) > 120:
        clean_page = _agent_clean_page_from_markdown(url, jina_text, method="jina_reader", fetch_trace=fetch_trace)
        _agent_cache_clean_page(cache_key, clean_page)
        return dict(clean_page)

    serper_text, serper_error = _agent_fetch_serper_markdown(url, timeout)
    fetch_trace.append({"method": "serper_scrape", "success": bool(serper_text and len(serper_text.strip()) > 120), "error": serper_error})
    if serper_text and len(serper_text.strip()) > 120:
        clean_page = _agent_clean_page_from_markdown(url, serper_text, method="serper_scrape", fetch_trace=fetch_trace)
        _agent_cache_clean_page(cache_key, clean_page)
        return dict(clean_page)

    return {
        "url": final_url or url,
        "title": final_url or url,
        "text": local_text if len(str(local_text or "").strip()) > 40 else "",
        "images": [],
        "fetchStatus": "weak_text" if len(str(local_text or "").strip()) > 40 else "failed",
        "error": "all_fetch_methods_failed",
        "fetchTrace": fetch_trace,
        "cleanMethod": "none",
        "contentType": ctype,
        "statusCode": status_code,
    }


def _agent_fetch_page_text(url, timeout=None):
    page = _agent_fetch_clean_page(url, timeout=timeout)
    return str(page.get("text") or "")


def _agent_page_evidence_text(content, goal, profile=None, max_chars=None):
    """Hermes-style extractive compression: keep relevant chunks, not just the page head."""
    text = str(content or "").strip()
    max_chars = max_chars or AGENT_SEARCH_PAGE_EVIDENCE_MAX_CHARS
    if len(text) <= max_chars:
        return text
    profile = profile or _agent_goal_profile(goal)
    goal_tokens = [token for token in _agent_search_tokens(_agent_clean_search_goal(goal)) if 2 <= len(token) <= 32]
    keyword_patterns = list(goal_tokens[:12])
    if profile.get("movie"):
        keyword_patterns.extend(["电影", "影片", "上映", "导演", "主演", "剧情", "预告", "片长", "票房"])
    if profile.get("event"):
        keyword_patterns.extend(["大会", "会议", "主题", "时间", "日程", "keynote", "schedule", "agenda", "conference"])
    if profile.get("product"):
        keyword_patterns.extend(["官网", "官方", "文档", "产品", "平台", "服务", "发布", "功能", "API", "cloud", "docs"])
    if profile.get("freshness") == "current":
        keyword_patterns.extend([str(datetime.now().year), "最新", "发布", "更新", "recent", "current"])
    chunk_size = 4500
    overlap = 450
    chunks = []
    start = 0
    while start < len(text):
        end = min(len(text), start + chunk_size)
        chunk = text[start:end]
        lowered = chunk.lower()
        score = 0
        for token in keyword_patterns:
            if token and str(token).lower() in lowered:
                score += 1
        score += min(3, len(re.findall(r"20\d{2}", chunk)))
        chunks.append((score, len(chunks), start, end, chunk))
        if end >= len(text):
            break
        start = max(end - overlap, start + 1)
    selected = sorted(chunks, key=lambda item: (-item[0], item[1]))[:3]
    selected.sort(key=lambda item: item[1])
    pieces = []
    remaining = max_chars
    for _score, idx, start, end, chunk in selected:
        if remaining <= 0:
            break
        header = f"[正文相关片段 {idx + 1}, chars {start}-{end}]\n"
        part = header + chunk[: max(0, remaining - len(header))]
        pieces.append(part)
        remaining -= len(part) + 2
    compressed = "\n\n".join(pieces).strip()
    if not compressed:
        compressed = text[:max_chars]
    return compressed[:max_chars] + f"\n\n[已从 {len(text)} 字正文中按相关性抽取，避免只读取网页开头。]"


def _agent_redact_sensitive_text(text):
    value = str(text or "")
    value = re.sub(r"(?i)(api[_ -]?key|token|bearer|authorization|password|passwd|secret|jwt)\s*[:=]\s*['\"]?[^'\"\s]{8,}", r"\1=[REDACTED]", value)
    value = re.sub(r"sk-[A-Za-z0-9_\-]{12,}", "sk-[REDACTED]", value)
    return value


def _agent_context_compression_keywords(goal, profile):
    tokens = [token for token in _agent_search_tokens(_agent_clean_search_goal(goal)) if 2 <= len(token) <= 32][:16]
    extras = []
    if profile.get("movie"):
        extras.extend(["电影", "影片", "上映", "导演", "主演", "剧情", "预告", "片长", "票房"])
    if profile.get("event"):
        extras.extend(["大会", "会议", "主题", "时间", "日程", "keynote", "schedule", "agenda", "conference"])
    if profile.get("product"):
        extras.extend(["官网", "官方", "文档", "产品", "平台", "服务", "发布", "功能", "API", "cloud", "docs"])
    if profile.get("freshness") == "current":
        extras.extend([str(datetime.now().year), "最新", "发布", "更新", "recent", "current"])
    return list(dict.fromkeys(tokens + extras))


def _agent_compress_text_with_context_engine(text, goal, profile, max_chars):
    """Hermes-inspired compaction for one full document.

    This keeps a protected head/tail and compresses the middle by relevance.
    It is not a retrieval result exposed to the model; it is the document
    capsule body produced after the backend has read the whole page.
    """
    source = _agent_redact_sensitive_text(_agent_normalize_clean_text(text))
    if not source or len(source) <= max_chars:
        return source[:max_chars]
    keywords = _agent_context_compression_keywords(goal, profile)
    head_budget = max(420, int(max_chars * 0.18))
    tail_budget = max(260, int(max_chars * 0.10))
    middle_budget = max(600, max_chars - head_budget - tail_budget - 260)
    paragraphs = [block.strip() for block in re.split(r"\n{2,}", source) if len(block.strip()) >= 40]
    scored = []
    for idx, paragraph in enumerate(paragraphs):
        lowered = paragraph.lower()
        score = 0.0
        for keyword in keywords:
            if str(keyword).lower() in lowered:
                score += 1.0
        score += min(2.0, len(re.findall(r"20\d{2}", paragraph)) * 0.35)
        score += 0.25 if idx < 3 else 0.0
        if score > 0:
            scored.append((score, idx, paragraph))
    selected = sorted(scored, key=lambda item: (-item[0], item[1]))[:8]
    selected.sort(key=lambda item: item[1])
    middle_parts = []
    remaining = middle_budget
    for score, idx, paragraph in selected:
        if remaining <= 0:
            break
        header = f"[相关段落 {idx + 1} score={round(score, 2)}]\n"
        part = header + paragraph[: max(0, remaining - len(header))]
        middle_parts.append(part)
        remaining -= len(part) + 2
    if not middle_parts:
        middle_parts = [source[head_budget:head_budget + middle_budget]]
    compressed = "\n\n".join([
        "[文档开头]\n" + source[:head_budget],
        "[与问题相关的正文]\n" + "\n\n".join(middle_parts),
        "[文档结尾]\n" + source[-tail_budget:],
        f"[压缩说明] 已完整读取 {len(source)} 字，按 head/tail 保护和相关段落压缩到 {max_chars} 字以内。",
    ])
    return compressed[:max_chars]


def _agent_capsule_excerpt(text, patterns, limit=360):
    source = str(text or "")
    for pattern in patterns:
        match = re.search(pattern, source, re.I)
        if not match:
            continue
        start = max(0, match.start() - 120)
        end = min(len(source), match.end() + 220)
        return _native_compact_text(source[start:end], limit)
    return ""


def _agent_document_key_facts(goal, profile, text):
    source = str(text or "")
    facts = []
    topic_tokens = [re.escape(token) for token in _agent_search_tokens(_agent_clean_search_goal(goal)) if 2 <= len(token) <= 24][:8]
    topic_excerpt = _agent_capsule_excerpt(source, topic_tokens or [re.escape(_agent_clean_search_goal(goal)[:24])])
    if topic_excerpt:
        facts.append({"fact": "核心主题匹配", "excerpt": topic_excerpt})
    if profile.get("freshness") == "current" or profile.get("event"):
        excerpt = _agent_capsule_excerpt(source, [r"20\d{2}[年./-]\d{1,2}(?:[月./-]\d{1,2}日?)?", r"最新|发布|更新|schedule|agenda|keynote|recent|current"])
        if excerpt:
            facts.append({"fact": "时间/最新信息", "excerpt": excerpt})
    if profile.get("movie"):
        excerpt = _agent_capsule_excerpt(source, [r"电影|影片|上映|导演|主演|剧情|预告|片长|票房|院线|film|movie|cast|director|release"])
        if excerpt:
            facts.append({"fact": "电影信息", "excerpt": excerpt})
    if profile.get("product"):
        excerpt = _agent_capsule_excerpt(source, [r"官网|官方|文档|产品|平台|服务|发布|功能|价格|API|cloud|docs|documentation"])
        if excerpt:
            facts.append({"fact": "产品/平台信息", "excerpt": excerpt})
    return facts[:6]


def _agent_build_document_capsule(goal, profile, page, depth):
    if not page or not page.get("fromPage"):
        return None
    text = str(page.get("fullContent") or page.get("content") or "").strip()
    if len(text) < 120:
        return None
    url = page.get("url") or ""
    capsule_id = "doc_" + hashlib.sha1(f"{url}|{len(text)}|{text[:120]}".encode("utf-8", errors="ignore")).hexdigest()[:16]
    budget = LONGCAT_SEARCH_DOCUMENT_CAPSULE_CHARS
    if depth == "fast":
        budget = max(1800, int(budget * 0.65))
    elif depth == "deep":
        budget = max(budget, 5200)
    compressed = _agent_compress_text_with_context_engine(text, goal, profile, budget)
    missing = []
    if (profile.get("freshness") == "current" or profile.get("event")) and not page.get("dateHint"):
        missing.append("date")
    if not page.get("author"):
        missing.append("author")
    return {
        "documentId": capsule_id,
        "title": page.get("title") or url,
        "url": url,
        "canonicalUrl": page.get("canonicalUrl") or url,
        "domain": page.get("domain") or _agent_url_domain(url),
        "sourceType": page.get("sourceType") or "unknown",
        "baiduRank": page.get("rank"),
        "dateHint": page.get("dateHint") or "",
        "author": page.get("author") or "",
        "cleanMethod": page.get("cleanMethod") or "",
        "cleanScore": page.get("cleanScore") or 0,
        "rawChars": page.get("rawChars") or len(text),
        "textChars": page.get("textChars") or len(text),
        "compressedText": compressed,
        "keyFacts": _agent_document_key_facts(goal, profile, text),
        "missingSignals": missing,
        "imageRefs": (page.get("images") or [])[:6],
    }


def _agent_build_document_capsules(goal, profile, pages, depth):
    capsules = []
    seen = set()
    for page in pages or []:
        capsule = _agent_build_document_capsule(goal, profile, page, depth)
        if not capsule:
            continue
        key = capsule.get("canonicalUrl") or capsule.get("url")
        if key in seen:
            continue
        seen.add(key)
        capsules.append(capsule)
    capsules.sort(key=lambda item: (int(item.get("baiduRank") or 9999), -float(item.get("cleanScore") or 0)))
    return capsules


def _agent_build_compressed_evidence_brief(goal, profile, document_capsules, evidence_matrix, depth):
    domains = sorted({item.get("domain") for item in document_capsules or [] if item.get("domain")})
    lines = [
        f"目标问题：{_agent_clean_search_goal(goal)}",
        f"搜索模式：完整文档读取 + Hermes-style context compression（{depth}）",
        f"已压缩正文来源：{len(document_capsules or [])} 个文档，{len(domains)} 个域名：{', '.join(domains[:8])}",
        "",
        "## 文档证据",
    ]
    remaining = LONGCAT_SEARCH_EVIDENCE_BRIEF_CHARS
    for idx, capsule in enumerate(document_capsules or [], start=1):
        facts = "；".join(f"{fact.get('fact')}：{fact.get('excerpt')}" for fact in (capsule.get("keyFacts") or [])[:3])
        block = "\n".join([
            f"[{idx}] {capsule.get('title')} ({capsule.get('domain')})",
            f"URL: {capsule.get('url')}",
            f"类型: {capsule.get('sourceType')}；日期: {capsule.get('dateHint') or '未知'}；清洗: {capsule.get('cleanMethod')}；正文字符: {capsule.get('textChars')}",
            f"关键事实: {facts or '未抽取到明确事实'}",
            f"压缩正文:\n{capsule.get('compressedText') or ''}",
        ])
        if len("\n\n".join(lines)) + len(block) > remaining:
            break
        lines.append(block)
        lines.append("")
    if evidence_matrix:
        lines.append("## 交叉验证矩阵")
        for item in evidence_matrix[:8]:
            lines.append(f"- {item.get('fact')}：{item.get('status')}；{item.get('note') or ''}")
    brief = "\n".join(lines).strip()
    return _agent_redact_sensitive_text(brief[:LONGCAT_SEARCH_EVIDENCE_BRIEF_CHARS])


def _agent_build_document_source_evidence(document_capsules, limit=12):
    evidence = []
    for capsule in (document_capsules or [])[:limit]:
        evidence.append({
            "title": capsule.get("title") or "网页",
            "url": capsule.get("url") or "",
            "domain": capsule.get("domain") or _agent_url_domain(capsule.get("url")),
            "sourceType": capsule.get("sourceType") or "unknown",
            "fromPage": True,
            "documentId": capsule.get("documentId"),
            "dateHint": capsule.get("dateHint") or "",
            "excerpt": _native_compact_text(capsule.get("compressedText"), 1400),
        })
    return evidence


def _agent_rank_images_from_documents(goal, profile, pages, document_capsules, limit=8):
    document_urls = {capsule.get("url") for capsule in document_capsules or [] if capsule.get("url")}
    tokens = _agent_search_tokens(goal)
    images = []
    seen = set()
    for page in pages or []:
        if page.get("url") not in document_urls:
            continue
        for image in page.get("images") or []:
            url = image.get("url") or ""
            if not url or url in seen:
                continue
            seen.add(url)
            haystack = " ".join([image.get("alt") or "", image.get("pageTitle") or "", page.get("title") or "", url])
            score = 0.7 + _agent_text_token_overlap_score(tokens, haystack)
            score += _agent_source_type_bonus(page.get("sourceType") or "unknown", profile) * 0.25
            if image.get("kind") in {"meta", "markdown"}:
                score += 0.2
            images.append({
                "url": url,
                "alt": image.get("alt") or "",
                "sourcePage": page.get("url") or image.get("sourcePage") or "",
                "sourceTitle": page.get("title") or image.get("pageTitle") or "",
                "domain": page.get("domain") or _agent_url_domain(page.get("url")),
                "kind": image.get("kind") or "image",
                "score": round(score, 3),
            })
    images.sort(key=lambda item: -float(item.get("score") or 0))
    return [item for item in images if item.get("score", 0) >= 0.45][:limit]


def _agent_clean_documents_for_output(pages, limit=12):
    docs = []
    for page in (pages or [])[:limit]:
        if not page.get("fromPage"):
            continue
        text = str(page.get("fullContent") or page.get("content") or "")
        docs.append({
            "title": page.get("title") or "",
            "url": page.get("url") or "",
            "canonicalUrl": page.get("canonicalUrl") or page.get("url") or "",
            "domain": page.get("domain") or _agent_url_domain(page.get("url")),
            "sourceType": page.get("sourceType") or "unknown",
            "dateHint": page.get("dateHint") or "",
            "author": page.get("author") or "",
            "cleanMethod": page.get("cleanMethod") or "",
            "cleanScore": page.get("cleanScore") or 0,
            "textChars": len(text),
            "textPreview": _native_compact_text(text, 2200),
            "imageCount": len(page.get("images") or []),
        })
    return docs


def _agent_build_document_reading_plan(candidate_pool, pages, document_capsules, budget, depth):
    read_urls = {page.get("url") for page in pages or [] if page.get("url")}
    capsule_urls = {capsule.get("url") for capsule in document_capsules or [] if capsule.get("url")}
    top = []
    for item in (candidate_pool or [])[:16]:
        url = item.get("url") or ""
        if url in capsule_urls:
            status = "document_capsule"
            reason = "已完整读取网页并压缩为 DocumentCapsule。"
        elif url in read_urls:
            status = "read_but_not_usable"
            reason = "已尝试读取，但正文质量不足或未进入压缩证据包。"
        else:
            status = "candidate_only"
            reason = "未进入本轮读取预算；摘要只作为候选线索，不作为回答证据。"
        top.append({
            "title": item.get("title"),
            "url": url,
            "domain": item.get("domain"),
            "baiduRank": item.get("rank"),
            "sourceType": item.get("sourceType"),
            "score": item.get("score"),
            "status": status,
            "reason": reason,
        })
    return {
        "policy": "baidu_rank_prior_light_triage_then_full_document_compression",
        "depth": depth,
        "fullPageLimit": int(budget.get("full_page_limit") or 0),
        "readPages": len([page for page in pages or [] if page.get("fromPage")]),
        "documentCapsules": len(document_capsules or []),
        "topCandidates": top,
    }


def _agent_text_token_overlap_score(query_tokens, text):
    haystack = str(text or "").lower()
    if not query_tokens:
        return 0.0
    hits = 0
    weighted = 0.0
    for token in query_tokens:
        token = str(token or "").lower()
        if not token:
            continue
        count = haystack.count(token)
        if count:
            hits += 1
            weighted += min(3, count)
    return (hits / max(1, len(query_tokens))) * 2.0 + min(1.5, weighted * 0.12)


def _agent_search_tokens(text):
    source = str(text or "").lower()
    tokens = set()
    for part in re.findall(r"[a-z0-9][a-z0-9._-]{1,}|[\u4e00-\u9fff]{2,}", source):
        if re.fullmatch(r"[\u4e00-\u9fff]+", part):
            tokens.add(part)
            for idx in range(max(0, len(part) - 1)):
                tokens.add(part[idx:idx + 2])
        elif part not in {"http", "https", "www", "com", "cn", "org", "net", "the", "and", "for", "with", "from"}:
            tokens.add(part)
    return tokens


def _agent_search_score(goal, query, refs, pages, candidate_pool=None, evidence_matrix=None):
    goal_tokens = _agent_search_tokens(f"{goal} {query}")
    score = min(0.8, len(refs or []) / 12)
    for page in (pages or [])[:8]:
        page_content = str(page.get("fullContent") or page.get("content") or "")
        text = f"{page.get('title') or ''} {page.get('url') or ''} {page_content[:2500]}"
        page_tokens = _agent_search_tokens(text)
        overlap = sum(1 for token in goal_tokens if token in page_tokens)
        coverage = overlap / max(1, len(goal_tokens))
        length_score = min(0.75, len(page_content) / 5000)
        score += (0.4 if page.get("fromPage") else 0.16) + length_score + coverage * 2.4
    domains = {_agent_url_domain(page.get("url")) for page in pages or [] if _agent_url_domain(page.get("url"))}
    source_types = {
        item.get("sourceType")
        for item in candidate_pool or []
        if item.get("url") in {page.get("url") for page in pages or []}
    }
    score += min(0.9, max(0, len(domains) - 1) * 0.35)
    score += min(0.6, len([item for item in source_types if item in {"official", "authoritative_media", "movie_database", "encyclopedia", "industry"}]) * 0.18)
    for item in evidence_matrix or []:
        if item.get("status") == "confirmed":
            score += 0.25
    return round(score, 3)


def _agent_search_query_key(query):
    return re.sub(r"\s+", " ", str(query or "").lower()).strip()


def _agent_ref_text(ref):
    return f"{ref.get('title') or ''}\n{ref.get('url') or ''}\n{_agent_ref_snippet(ref)}"


def _agent_ref_relevance(goal, profile, ref, rank):
    goal_tokens = _agent_search_tokens(_agent_clean_search_goal(goal))
    ref_text = _agent_ref_text(ref)
    ref_tokens = _agent_search_tokens(ref_text)
    overlap = sum(1 for token in goal_tokens if token in ref_tokens)
    score = overlap / max(1, min(len(goal_tokens), 18))
    if rank < 2:
        score += 0.35
    url = str(ref.get("url") or "").lower()
    title = str(ref.get("title") or "").lower()
    if profile.get("repoOrCode") and any(host in url for host in ["github.com", "huggingface.co", "hf-mirror.com"]):
        score += 1.2
    if profile.get("conceptGrounding") and any(mark in url for mark in ["wikipedia", "docs.", "developer.", "github.com", "readthedocs", "paperswithcode"]):
        score += 0.45
    if profile.get("paper") and re.search(r"arxiv|doi|paper|openreview|aclanthology|semanticscholar", url + " " + title, re.I):
        score += 0.7
    if profile.get("freshness") == "current" and re.search(r"202\d|latest|更新|发布|新闻|today|current", ref_text, re.I):
        score += 0.35
    return round(score, 3)


def _agent_url_domain(url):
    try:
        host = (urlparse(str(url or "")).hostname or "").lower()
    except Exception:
        host = ""
    if host.startswith("www."):
        host = host[4:]
    return host


def _agent_domain_matches(domain, policy_domain):
    domain = str(domain or "").lower().lstrip(".")
    policy_domain = str(policy_domain or "").lower().lstrip(".")
    return bool(domain and policy_domain and (domain == policy_domain or domain.endswith("." + policy_domain)))


def _agent_source_policy_reason(domain, title="", snippet=""):
    for policy_domain in LONGCAT_SEARCH_LOW_QUALITY_DOMAINS:
        if _agent_domain_matches(domain, policy_domain):
            return f"low_quality_domain:{policy_domain}"
    haystack = f"{title}\n{snippet}"
    for pattern in LONGCAT_SEARCH_LOW_QUALITY_PATTERNS:
        if pattern and re.search(re.escape(pattern), haystack, re.I):
            return f"low_quality_pattern:{pattern[:32]}"
    return ""


def _agent_cjk_entity_query(goal):
    clean = _agent_clean_search_goal(goal)
    clean = re.sub(r"\s+", "", clean)
    if 2 <= len(clean) <= 14 and re.fullmatch(r"[\u4e00-\u9fffA-Za-z0-9·._-]+", clean):
        return clean
    return ""


def _agent_core_query_terms(goal):
    text = _agent_clean_search_goal(goal)
    text = re.sub(
        r"(官方|官网|文档|说明|发布|介绍|是什么|什么|哪些|有哪些|能力|功能|怎么|如何|请|帮我|搜索|查询|相关|最新|新闻|API|api)",
        " ",
        text,
        flags=re.I,
    )
    terms = []
    for part in re.findall(r"[\u4e00-\u9fffA-Za-z0-9·._-]{2,}", text):
        item = part.strip().lower()
        if item and item not in terms:
            terms.append(item)
    return terms[:6]


def _agent_ref_relevance_gate(goal, profile, ref, relevance):
    title = str(ref.get("title") or "")
    snippet = str(_agent_ref_snippet(ref))
    url = str(ref.get("url") or "")
    haystack = f"{title}\n{snippet}\n{url}".lower()
    exact = _agent_cjk_entity_query(goal)
    if exact and exact.lower() in haystack:
        return {"accepted": True, "reason": "exact_query_match", "coverage": 1.0}
    core_terms = _agent_core_query_terms(goal)
    core_hit = any(term and term in haystack for term in core_terms)
    goal_tokens = [token for token in _agent_search_tokens(_agent_clean_search_goal(goal)) if 2 <= len(token) <= 32]
    if not goal_tokens:
        return {"accepted": True, "reason": "no_query_tokens", "coverage": 1.0}
    overlap = sum(1 for token in goal_tokens if token.lower() in haystack)
    coverage = overlap / max(1, min(len(goal_tokens), 12))
    if exact and not core_hit and coverage < LONGCAT_SEARCH_MIN_RELEVANCE_SCORE and relevance < 0.8:
        return {"accepted": False, "reason": "low_entity_relevance", "coverage": round(coverage, 3)}
    if profile.get("exactUrls") and any(str(url).startswith(str(item)) for item in profile.get("exactUrls") or []):
        return {"accepted": True, "reason": "exact_url", "coverage": round(coverage, 3)}
    if coverage >= LONGCAT_SEARCH_MIN_RELEVANCE_SCORE or relevance >= 0.75:
        return {"accepted": True, "reason": "token_relevance", "coverage": round(coverage, 3)}
    if core_hit and re.search(r"官网|官方|百科|文档|新闻|发布|公告|报告|研究|论文|github|docs|documentation|api|平台|服务", haystack, re.I) and coverage >= 0.2:
        return {"accepted": True, "reason": "source_context_relevance", "coverage": round(coverage, 3)}
    return {"accepted": False, "reason": "low_query_relevance", "coverage": round(coverage, 3)}


def _agent_source_type(goal, profile, ref):
    text = _agent_ref_text(ref).lower()
    domain = _agent_url_domain(ref.get("url"))
    if not domain:
        return "unknown"
    policy_reason = _agent_source_policy_reason(domain, ref.get("title") or "", ref.get("abstract") or ref.get("content") or "")
    if policy_reason:
        return "low_quality_generated"
    official_domains = {
        "google.com", "blog.google", "developers.google.com", "io.google",
        "cloud.google.com", "openai.com", "qwenlm.github.io", "alibabacloud.com",
        "aliyun.com", "modelstudio.aliyun.com", "tongyi.aliyun.com",
    }
    authoritative_media = (
        "reuters.com", "apnews.com", "bloomberg.com", "theverge.com",
        "techcrunch.com", "wired.com", "36kr.com", "ifeng.com", "sina.com.cn",
        "qq.com", "163.com", "sohu.com", "people.com.cn", "xinhuanet.com",
        "chinanews.com.cn", "cnbeta.com.tw", "ithome.com", "jiemian.com",
    )
    movie_sources = (
        "douban.com", "maoyan.com", "mtime.com", "m1905.com", "1905.com",
        "imdb.com", "themoviedb.org", "tmdb.org", "boxofficemojo.com",
        "piaofang.maoyan.com",
    )
    encyclopedic = ("wikipedia.org", "baike.baidu.com", "baike.com", "wikidata.org")
    technical = (
        "github.com", "huggingface.co", "readthedocs.io", "docs.", "developer.",
        "cloud.", "help.", "support.", "api.",
    )
    if any(domain == item or domain.endswith("." + item) for item in official_domains):
        return "official"
    if profile.get("event") and "google" in domain and re.search(r"io|i/o|大会|conference|keynote", text, re.I):
        return "official"
    if any(domain == item or domain.endswith("." + item) for item in authoritative_media):
        return "authoritative_media"
    if re.search(r"(^|[.-])(bbs|forum|blog|zhihu|csdn|jianshu|tieba|weibo|toutiao)([.-]|$)", domain, re.I) or re.search(r"转载|搬运|聚合|网友讨论|论坛|问答搬运", text, re.I):
        return "blog_or_forum"
    if profile.get("product") and re.search(r"官网|官方|文档|docs|documentation|platform|console|cloud", text, re.I):
        return "official" if any(mark in domain for mark in ("aliyun", "alibaba", "qwen", "tongyi")) else "industry"
    if profile.get("movie") and any(domain == item or domain.endswith("." + item) for item in movie_sources):
        return "movie_database"
    if any(domain == item or domain.endswith("." + item) for item in encyclopedic):
        return "encyclopedia"
    if any(mark in domain for mark in technical) or any(mark in text for mark in ("github", "hugging face", "documentation", "文档")):
        return "industry"
    if re.search(r"blog|medium|zhihu|csdn|jianshu|bilibili|weibo|xhslink|toutiao", domain + " " + text, re.I):
        return "blog_or_forum"
    return "general"


def _agent_source_type_bonus(source_type, profile):
    base = {
        "official": 1.25,
        "movie_database": 1.0 if profile.get("movie") else 0.35,
        "authoritative_media": 1.05,
        "encyclopedia": 0.55,
        "industry": 0.5,
        "general": 0.15,
        "blog_or_forum": -0.15,
        "low_quality_generated": -1.25,
        "unknown": -0.25,
    }
    return base.get(source_type, 0.0)


def _agent_source_quality_penalty(domain, title, snippet):
    haystack = f"{domain} {title} {snippet}".lower()
    penalty = 0.0
    if _agent_source_policy_reason(domain, title, snippet):
        penalty += 0.65
    if re.search(r"baijiahao|mbd\.baidu|tieba|zhidao|wenku|csdn|jianshu|toutiao|weibo|zhihu", haystack, re.I):
        penalty += 0.22
    if re.search(r"转载|搬运|聚合|广告|推广|登录后|阅读全文|下载|网盘", haystack, re.I):
        penalty += 0.18
    if not domain:
        penalty += 0.18
    return min(0.55, penalty)


def _agent_ref_date_hint(ref):
    text = _agent_ref_text(ref)
    matches = re.findall(r"(?:20\d{2}[年./-]\d{1,2}(?:[月./-]\d{1,2}日?)?|20\d{2})", text)
    return matches[0] if matches else ""


def _agent_ref_image_refs(ref, limit=6):
    images = []

    def add(value, alt=""):
        if isinstance(value, dict):
            src = value.get("url") or value.get("src") or value.get("image") or value.get("thumbnail") or value.get("thumb")
            text = value.get("alt") or value.get("title") or alt
        else:
            src = value
            text = alt
        src = str(src or "").strip()
        if not src or src.startswith("data:") or src.startswith("blob:"):
            return
        if not src.startswith(("http://", "https://")):
            return
        if any(item.get("url") == src for item in images):
            return
        images.append({
            "url": src,
            "alt": _native_compact_text(text, 180),
            "kind": "baidu_ref",
        })

    for key in ("image", "img", "thumbnail", "thumbnail_src", "thumb", "img_src", "image_url", "cover", "poster"):
        if ref.get(key):
            add(ref.get(key), ref.get("title") or "")
    for key in ("images", "imageUrls", "thumbnails"):
        value = ref.get(key)
        if isinstance(value, list):
            for item in value[:limit]:
                add(item, ref.get("title") or "")
    return images[:limit]


def _agent_build_candidate_pool(goal, profile, refs):
    seen = set()
    candidates = []
    for index, ref in enumerate(refs or []):
        if not isinstance(ref, dict):
            continue
        url = str(ref.get("url") or "").strip()
        title = _native_compact_text(ref.get("title") or url, 220)
        if not url and not title:
            continue
        key = (url or title).lower()
        if key in seen:
            continue
        seen.add(key)
        domain = _agent_url_domain(url)
        source_type = _agent_source_type(goal, profile, ref)
        relevance = _agent_ref_relevance(goal, profile, ref, index)
        snippet = _native_compact_text(_agent_ref_snippet(ref), 700)
        relevance_gate = _agent_ref_relevance_gate(goal, profile, ref, relevance)
        policy_reason = _agent_source_policy_reason(domain, title, snippet)
        weak_candidate = bool(policy_reason or source_type == "low_quality_generated")
        if not relevance_gate.get("accepted") and not weak_candidate:
            continue
        rank_prior = max(0.15, 1.65 - index * 0.08)
        quality_adjustment = _agent_source_type_bonus(source_type, profile) - _agent_source_quality_penalty(domain, title, snippet)
        score = rank_prior + relevance * 0.7 + quality_adjustment
        if weak_candidate:
            score -= 0.75
        if profile.get("freshness") == "current" and _agent_ref_date_hint(ref):
            score += 0.3
        if profile.get("movie") and re.search(r"电影|影片|上映|导演|主演|剧情|预告|片长|票房", f"{title} {snippet}", re.I):
            score += 0.45
        if profile.get("event") and re.search(r"时间|日期|主题|keynote|schedule|agenda|developer|conference|大会", f"{title} {snippet}", re.I):
            score += 0.45
        if profile.get("product") and re.search(r"官网|官方|文档|产品|平台|服务|价格|发布|功能|api|cloud", f"{title} {snippet}", re.I):
            score += 0.45
        candidates.append({
            "rank": index + 1,
            "title": title,
            "url": url,
            "domain": domain,
            "sourceType": source_type,
            "score": round(score, 3),
            "baiduRankScore": round(rank_prior, 3),
            "qualityAdjustment": round(quality_adjustment, 3),
            "relevanceScore": round(relevance, 3),
            "relevanceGate": relevance_gate,
            "sourcePolicy": {"weak": weak_candidate, "reason": policy_reason},
            "fetchEligible": bool(relevance_gate.get("accepted") and not weak_candidate),
            "dateHint": _agent_ref_date_hint(ref),
            "snippet": snippet,
            "imageRefs": _agent_ref_image_refs(ref),
            "sourceEngine": ref.get("sourceEngine") or "",
            "searchEngine": ref.get("searchEngine") or "",
            "engines": ref.get("engines") or [],
            "engineMatches": ref.get("engineMatches") or [],
            "selectionReason": f"rank={index + 1}; {source_type}; relevance={round(relevance, 3)}; gate={relevance_gate.get('reason')}; quality={round(quality_adjustment, 3)}",
        })
    candidates.sort(key=lambda item: (-float(item.get("score") or 0), item.get("rank") or 9999))
    return candidates


def _agent_count_types(items):
    counts = {}
    for item in items or []:
        key = item.get("sourceType") or "unknown"
        counts[key] = counts.get(key, 0) + 1
    return counts


def _agent_candidate_pool_summary(candidate_pool, pages):
    read_urls = {
        str(value or "")
        for page in pages or []
        for value in (page.get("url"), page.get("originalUrl"))
        if value
    }
    read_domains = sorted({_agent_url_domain(page.get("url")) for page in pages or [] if _agent_url_domain(page.get("url"))})
    unread = []
    for item in candidate_pool or []:
        if item.get("url") in read_urls:
            continue
        unread.append({
            "title": item.get("title"),
            "url": item.get("url"),
            "domain": item.get("domain"),
            "sourceType": item.get("sourceType"),
            "score": item.get("score"),
            "fetchEligible": item.get("fetchEligible", True),
            "sourcePolicy": item.get("sourcePolicy") or {},
            "relevanceGate": item.get("relevanceGate") or {},
            "notReadReason": "budget_or_lower_triage_rank",
        })
        if len(unread) >= 8:
            break
    return {
        "totalCandidates": len(candidate_pool or []),
        "uniqueDomains": len({item.get("domain") for item in candidate_pool or [] if item.get("domain")}),
        "sourceTypeCounts": _agent_count_types(candidate_pool),
        "readPages": len([page for page in pages or [] if page.get("fromPage")]),
        "readDomains": read_domains,
        "unreadTopCandidates": unread,
    }


def _agent_select_fetch_candidates(candidate_pool, pages, budget, depth, initial=False, attempted_urls=None):
    attempted_urls = set(attempted_urls or [])
    read_urls = {
        str(value or "")
        for page in pages or []
        for value in (page.get("url"), page.get("originalUrl"))
        if value
    }
    read_domains = {_agent_url_domain(page.get("url")) for page in pages or [] if _agent_url_domain(page.get("url"))}
    full_pages = [page for page in pages or [] if page.get("fromPage")]
    remaining = max(0, int(budget.get("full_page_limit") or 0) - len(full_pages))
    if remaining <= 0:
        return []
    first_batch = 1 if depth == "fast" else (3 if depth == "deep" else 2)
    batch_size = min(remaining, first_batch if initial or not full_pages else 1)
    selected = []
    selected_domains = set()
    for candidate in candidate_pool or []:
        url = candidate.get("url") or ""
        domain = candidate.get("domain") or ""
        if not url or url in read_urls or url in attempted_urls:
            continue
        if domain and (domain in read_domains or domain in selected_domains) and len(selected) < batch_size:
            continue
        selected.append(candidate)
        if domain:
            selected_domains.add(domain)
        if len(selected) >= batch_size:
            break
    if len(selected) < batch_size:
        selected_urls = {item.get("url") for item in selected}
        for candidate in candidate_pool or []:
            url = candidate.get("url") or ""
            if not url or url in read_urls or url in selected_urls or url in attempted_urls:
                continue
            selected.append(candidate)
            if len(selected) >= batch_size:
                break
    return selected


def _agent_select_fetch_candidates_by_engine(candidate_pool, pages, attempted_urls=None):
    """Select fetch targets from score, relevance, source policy, and domain diversity."""
    attempted_urls = set(attempted_urls or [])
    read_urls = {
        str(value or "")
        for page in pages or []
        for value in (page.get("url"), page.get("originalUrl"))
        if value
    }
    read_domains = {_agent_url_domain(page.get("url")) for page in pages or [] if _agent_url_domain(page.get("url"))}
    target = max(1, min(
        LONGCAT_SEARCH_DEFAULT_FETCH_BUDGET,
        int(os.environ.get("LONGCAT_SEARCH_MAX_AUTO_FETCH_PER_STEP") or str(LONGCAT_SEARCH_DEFAULT_FETCH_BUDGET)),
    ))
    selected = []
    selected_domains = set()
    selected_urls = set()

    for candidate in candidate_pool or []:
        if len(selected) >= target:
            break
        url = candidate.get("url") or ""
        domain = candidate.get("domain") or ""
        if not url or url in read_urls or url in attempted_urls or url in selected_urls:
            continue
        if candidate.get("fetchEligible") is False or (candidate.get("sourcePolicy") or {}).get("weak"):
            continue
        if domain and (domain in read_domains or domain in selected_domains):
            continue
        selected.append(candidate)
        selected_urls.add(url)
        if domain:
            selected_domains.add(domain)

    if len(selected) < target:
        for candidate in candidate_pool or []:
            if len(selected) >= target:
                break
            url = candidate.get("url") or ""
            domain = candidate.get("domain") or ""
            if not url or url in read_urls or url in attempted_urls or url in selected_urls:
                continue
            if candidate.get("fetchEligible") is False or (candidate.get("sourcePolicy") or {}).get("weak"):
                continue
            selected.append(candidate)
            selected_urls.add(url)
            if domain:
                selected_domains.add(domain)

    return selected


def _agent_excerpt_for_patterns(text, patterns, limit=260):
    source = str(text or "")
    for pattern in patterns:
        match = re.search(pattern, source, re.I)
        if match:
            start = max(0, match.start() - 90)
            end = min(len(source), match.end() + 170)
            return _native_compact_text(source[start:end], limit)
    return _native_compact_text(source, limit)


def _agent_matrix_status(count, min_count=2):
    if count >= min_count:
        return "confirmed"
    if count == 1:
        return "single_source"
    return "unconfirmed"


def _agent_build_evidence_matrix(goal, profile, pages, candidate_pool):
    matrix = []
    full_pages = [page for page in pages or [] if len(str(page.get("fullContent") or page.get("content") or "").strip()) > 120]
    goal_tokens = [token for token in _agent_search_tokens(_agent_clean_search_goal(goal)) if 2 <= len(token) <= 24][:8]

    def support_item(page, patterns):
        return {
            "title": page.get("title") or page.get("url") or "",
            "url": page.get("url") or "",
            "domain": _agent_url_domain(page.get("url")),
            "excerpt": _agent_excerpt_for_patterns(f"{page.get('title') or ''}\n{page.get('fullContent') or page.get('content') or ''}", patterns),
        }

    topic_patterns = [re.escape(token) for token in goal_tokens] or [re.escape(_agent_clean_search_goal(goal)[:24])]
    topic_sources = [
        support_item(page, topic_patterns)
        for page in full_pages
        if any(re.search(pattern, f"{page.get('title') or ''}\n{page.get('fullContent') or page.get('content') or ''}", re.I) for pattern in topic_patterns)
    ]
    matrix.append({
        "fact": "核心主题与查询匹配",
        "status": _agent_matrix_status(len({item["domain"] for item in topic_sources if item.get("domain")})),
        "supportingSources": topic_sources[:6],
        "conflictingSources": [],
        "note": "按标题和正文中的目标关键词交叉确认。",
    })

    if profile.get("freshness") == "current" or profile.get("event"):
        date_patterns = [r"20\d{2}[年./-]\d{1,2}(?:[月./-]\d{1,2}日?)?", r"20\d{2}", r"最新|发布|更新|today|current|recent|schedule|agenda"]
        date_sources = [
            support_item(page, date_patterns)
            for page in full_pages
            if any(re.search(pattern, f"{page.get('title') or ''}\n{page.get('fullContent') or page.get('content') or ''}", re.I) for pattern in date_patterns)
        ]
        matrix.append({
            "fact": "时间/年份/最新信息线索",
            "status": _agent_matrix_status(len({item["domain"] for item in date_sources if item.get("domain")})),
            "supportingSources": date_sources[:6],
            "conflictingSources": [],
            "note": "用于避免只凭模型记忆回答时效信息。",
        })

    if profile.get("movie"):
        movie_patterns = [r"电影|影片|上映|导演|主演|剧情|预告|片长|票房|影评|院线|movie|film|cast|director|release"]
        movie_sources = [
            support_item(page, movie_patterns)
            for page in full_pages
            if any(re.search(pattern, f"{page.get('title') or ''}\n{page.get('fullContent') or page.get('content') or ''}", re.I) for pattern in movie_patterns)
        ]
        matrix.append({
            "fact": "电影相关信息（片名/上映/主创/剧情）",
            "status": _agent_matrix_status(len({item["domain"] for item in movie_sources if item.get("domain")})),
            "supportingSources": movie_sources[:6],
            "conflictingSources": [],
            "note": "电影类查询优先依赖正文页而非搜索摘要。",
        })

    if profile.get("event"):
        event_patterns = [r"大会|会议|主题|时间|日程|agenda|schedule|keynote|conference|developer|I/O|io"]
        event_sources = [
            support_item(page, event_patterns)
            for page in full_pages
            if any(re.search(pattern, f"{page.get('title') or ''}\n{page.get('fullContent') or page.get('content') or ''}", re.I) for pattern in event_patterns)
        ]
        matrix.append({
            "fact": "活动信息（时间/主题/日程）",
            "status": _agent_matrix_status(len({item["domain"] for item in event_sources if item.get("domain")})),
            "supportingSources": event_sources[:6],
            "conflictingSources": [],
            "note": "活动类查询优先官方与权威新闻正文。",
        })

    if profile.get("product"):
        product_patterns = [r"官网|官方|文档|产品|平台|服务|发布|功能|价格|API|cloud|docs|documentation|pricing|release"]
        product_sources = [
            support_item(page, product_patterns)
            for page in full_pages
            if any(re.search(pattern, f"{page.get('title') or ''}\n{page.get('fullContent') or page.get('content') or ''}", re.I) for pattern in product_patterns)
        ]
        matrix.append({
            "fact": "产品/平台信息（官网/文档/发布/功能）",
            "status": _agent_matrix_status(len({item["domain"] for item in product_sources if item.get("domain")})),
            "supportingSources": product_sources[:6],
            "conflictingSources": [],
            "note": "产品类查询优先官方、文档和可信媒体正文。",
        })

    official_or_authoritative = [
        item for item in candidate_pool or []
        if item.get("url") in {
            value
            for page in full_pages
            for value in (page.get("url"), page.get("originalUrl"))
            if value
        }
        and item.get("sourceType") in {"official", "authoritative_media", "movie_database", "encyclopedia", "industry"}
    ]
    matrix.append({
        "fact": "来源质量",
        "status": _agent_matrix_status(len({item.get("domain") for item in official_or_authoritative if item.get("domain")})),
        "supportingSources": [
            {
                "title": item.get("title"),
                "url": item.get("url"),
                "domain": item.get("domain"),
                "excerpt": f"{item.get('sourceType')} score={item.get('score')}",
            }
            for item in official_or_authoritative[:6]
        ],
        "conflictingSources": [],
        "note": "至少两个不同域名的高质量来源才算交叉验证较强。",
    })
    return matrix


def _agent_should_fetch_ref(goal, profile, ref, rank, fetched_count, budget):
    if fetched_count >= int(budget.get("full_page_limit") or 0):
        return False
    if profile.get("exactUrls") and any(str(ref.get("url") or "").startswith(url) for url in profile.get("exactUrls") or []):
        return True
    if rank < (2 if budget.get("full_page_limit", 0) <= 2 else 3):
        return True
    relevance = _agent_ref_relevance(goal, profile, ref, rank)
    threshold = 0.55 if profile.get("shouldFetchFullPage") else 0.8
    return relevance >= threshold


def _agent_evaluate_search_sufficiency(goal, evidence_summary, pages_count, domains_count, depth, api_key=""):
    """MiroFlow-style: Ask LLM whether current evidence is sufficient.

    Returns a dict with sufficiency_score, reasoning, suggested_action.
    If LLM call fails, returns None (caller falls back to hardcoded heuristics).
    """
    prompt = f"""你是一个搜索质量评估器。用户的问题是：

【用户问题】
{goal}

【当前已收集的证据摘要】
{evidence_summary[:3000]}

【统计】
- 已读取网页正文：{pages_count} 页
- 来源域名数：{domains_count} 个
- 当前搜索深度模式：{depth}

请评估当前证据是否足以回答用户问题。返回 JSON：
{{
  "sufficiency_score": 0-10,
  "reasoning": "简要说明",
  "suggested_action": "stop" | "continue" | "refocus",
  "missing_aspects": ["缺失的方面1", "缺失的方面2"],
  "suggested_queries": ["建议的新查询1", "建议的新查询2"]
}}

sufficiency_score 标准：
- 10：证据完全充分，可以直接回答
- 7-9：证据基本充分，可能缺 minor 细节
- 4-6：证据部分充分，需要补充
- 0-3：证据严重不足，需要大幅扩展

只返回 JSON，不要其他内容。"""

    try:
        payload = {
            "model": LONGCAT_PROXY_MODEL,
            "messages": [{"role": "user", "content": prompt}],
            "max_tokens": 800,
            "temperature": 0.2,
        }
        key = api_key or (_longcat_default_api_keys()[0] if _longcat_default_api_keys() else "")
        if not key:
            return None
        response = _longcat_proxy_request(payload, key, timeout=30)
        data = json.loads(response.read().decode("utf-8"))
        content = data.get("choices", [{}])[0].get("message", {}).get("content", "")
        # Extract JSON from possible markdown fences
        raw = str(content).strip()
        if raw.startswith("```"):
            raw = raw.split("\n", 1)[1].rsplit("\n", 1)[0]
            if raw.startswith("json"):
                raw = raw[4:].strip()
        result = json.loads(raw)
        if isinstance(result, dict) and "sufficiency_score" in result:
            return result
    except Exception as e:
        logging.debug("Search sufficiency evaluation failed: %s", e)
    return None


def _agent_search_stop_state(profile, budget, depth, pages, evidence_score, repo_contexts=None, evidence_matrix=None):
    valid_pages = [page for page in (pages or []) if len(str(page.get("fullContent") or page.get("content") or "").strip()) > 120]
    full_pages = [page for page in valid_pages if page.get("fromPage") and len(str(page.get("fullContent") or page.get("content") or "")) > 300]
    full_domains = {_agent_url_domain(page.get("url")) for page in full_pages if _agent_url_domain(page.get("url"))}
    if profile.get("repoOrCode") and repo_contexts:
        return True, "repo_context_found"
    if len(valid_pages) < int(budget.get("min_valid_pages") or 1):
        return False, "need_more_pages"
    if len(full_pages) < int(budget.get("min_full_pages") or 0):
        return False, "need_full_pages"
    min_cross_domains = 1
    if depth == "adaptive":
        min_cross_domains = 2
    elif depth == "deep":
        min_cross_domains = 3
    if profile.get("highStakes"):
        min_cross_domains = max(min_cross_domains, 2)
    if (profile.get("movie") or profile.get("event") or profile.get("product")) and depth != "fast":
        min_cross_domains = max(min_cross_domains, 2)
    if len(full_domains) < min_cross_domains:
        return False, "need_cross_check"
    matrix = evidence_matrix or []
    required_items = [
        item for item in matrix
        if item.get("fact") != "来源质量" and item.get("status") == "unconfirmed"
    ]
    if required_items and depth != "fast":
        return False, "need_fact_confirmation"
    if evidence_score < float(budget.get("min_score") or 0):
        return False, "need_better_evidence"
    if depth == "fast":
        return True, "fast_evidence_ready"
    if profile.get("highStakes") and len(full_pages) < 2:
        return False, "need_cross_check"
    return True, "evidence_ready"


def _agent_search_followups(goal, state, profile=None, limit=3):
    base = re.sub(r"^(请|帮我|给我|查一下|搜索|联网搜索|看看)\s*", "", str(goal or "").strip(), flags=re.I)
    base = re.sub(r"[？?。！!]+$", "", base).strip()
    profile = profile or _agent_goal_profile(base)
    tokens = [token for token in _agent_search_tokens(base) if 2 <= len(token) <= 32]
    english = [token for token in tokens if re.fullmatch(r"[a-z0-9._-]+", token, re.I)]
    chinese = [token for token in tokens if re.search(r"[\u4e00-\u9fff]", token)]
    year = datetime.now().year
    variants = [
        base,
        " ".join(english),
        " ".join(chinese[:6]),
        f"{' '.join(english)} {' '.join(chinese[:4])}".strip(),
        f"{base} GitHub README" if profile.get("repoOrCode") else "",
        f"{base} Hugging Face" if profile.get("repoOrCode") else "",
        f"{base} source code implementation" if profile.get("repoOrCode") else "",
        f"{base} paper arxiv" if profile.get("paper") else "",
        f"{base} survey benchmark" if profile.get("paper") else "",
        f"{base} 原理 架构 机制" if profile.get("conceptGrounding") else "",
        f"{base} official documentation explained" if profile.get("conceptGrounding") else "",
        f"{base} {year} latest" if profile.get("freshness") == "current" else "",
    ]
    tried = {_agent_search_query_key(item.get("query")) for item in state.get("queriesTried", [])}
    result = []
    for item in variants:
        clean = re.sub(r"\s+", " ", str(item or "")).strip()
        key = _agent_search_query_key(clean)
        if len(clean) < 2 or len(clean) > 120 or key in tried or key in {_agent_search_query_key(x) for x in result}:
            continue
        result.append(clean)
        if len(result) >= limit:
            break
    return result


def _agent_extract_repo_queries(text, limit=6):
    raw = str(text or "")
    candidates = []
    for match in re.finditer(r"https?://(?:www\.)?(?:github\.com|huggingface\.co|hf-mirror\.com)/[^\s<>)\"']+", raw, flags=re.I):
        url = match.group(0).rstrip(".,;:!?)\"]}")
        candidates.append(url)
    for match in re.finditer(r"\bgithub(?:\s+repo(?:sitory)?|\s+仓库)?\s*[:：]?\s*([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+)", raw, flags=re.I):
        candidates.append(f"https://github.com/{match.group(1)}")
    seen = set()
    result = []
    for item in candidates:
        key = item.lower()
        if key in seen:
            continue
        seen.add(key)
        result.append(item)
        if len(result) >= limit:
            break
    return result


def _agent_inspect_repos_from_search(pages, refs, goal, limit=4):
    haystacks = []
    for page in (pages or [])[:8]:
        haystacks.append(f"{page.get('title') or ''}\n{page.get('url') or ''}\n{str(page.get('fullContent') or page.get('content') or '')[:5000]}")
    for ref in (refs or [])[:10]:
        haystacks.append(f"{ref.get('title') or ''}\n{ref.get('url') or ''}\n{ref.get('content') or ''}")
    queries = []
    for text in haystacks:
        queries.extend(_agent_extract_repo_queries(text, limit=limit))
    if not queries and re.search(r"github|hugging\s*face|huggingface|仓库|代码|模型|数据集|repo|repository", goal, re.I):
        queries.append(goal)
    seen = set()
    contexts = []
    for query in queries:
        key = str(query).lower()
        if key in seen:
            continue
        seen.add(key)
        try:
            payload = _build_repo_inspect_payload(query, provider="auto")
            if payload.get("success") and payload.get("artifacts"):
                contexts.append({
                    "query": query,
                    "provider": payload.get("provider") or "auto",
                    "context": payload.get("context") or "",
                    "artifacts": payload.get("artifacts") or [],
                    "warnings": payload.get("warnings") or [],
                })
        except Exception as exc:
            contexts.append({"query": query, "error": str(exc), "artifacts": [], "warnings": [str(exc)]})
        if len(contexts) >= limit:
            break
    return contexts



def _agent_search_agent_payload(payload, emit=None):
    """Run the MiroFlow-style search sub-agent once."""
    payload = payload or {}
    goal = str(payload.get("query") or payload.get("goal") or payload.get("text") or "").strip()
    if not goal:
        raise ValueError("query is required")

    event_queue = queue.Queue() if emit else None
    context = payload.get("context") if isinstance(payload.get("context"), dict) else {}
    context = dict(context)
    context.setdefault("session_id", str(payload.get("session_id") or payload.get("sessionId") or f"search_{uuid.uuid4().hex[:12]}")[:160])
    context.setdefault("latest_user_text", goal)
    context.setdefault("user", payload.get("user") if isinstance(payload.get("user"), dict) else {})
    runtime = _native_session_runtime(context, event_queue)
    agent_context = runtime.fork_subagent_context(context) if isinstance(runtime, SessionRuntime) else context
    agent = SearchSubAgent(
        goal=goal,
        api_key=payload.get("apiKey") or payload.get("api_key") or (_longcat_proxy_keys()[0] if _longcat_proxy_keys() else ""),
        max_iterations=payload.get("maxIterations") or payload.get("max_turns"),
        parent_event_queue=event_queue,
        context=agent_context,
    )

    def run_agent_once():
        if isinstance(runtime, SessionRuntime):
            return runtime.run_op("subagent", "standalone_search_agent", agent.run)
        return agent.run()

    try:
        if emit and event_queue is not None:
            done = object()

            def run_agent():
                try:
                    result = run_agent_once()
                    event_queue.put(("result", result))
                except Exception as exc:
                    event_queue.put(("error", {"success": False, "error": str(exc)}))
                finally:
                    event_queue.put(done)

            threading.Thread(target=run_agent, daemon=True).start()
            final_result = None
            final_error = None
            while True:
                item = event_queue.get()
                if item is done:
                    break
                event_name, data = item
                if event_name == "result":
                    final_result = data
                elif event_name == "error":
                    final_error = data
                else:
                    emit(event_name, data)
            if final_error:
                raise RuntimeError(final_error.get("error") or "search agent failed")
            return final_result or {"success": False, "error": "search agent produced no result"}

        return run_agent_once()
    finally:
        if isinstance(agent_context, ForkedContext):
            agent_context.merge_back()
        if isinstance(runtime, SessionRuntime):
            agent_runtime.discard(runtime.session_id)


@app.route('/api/agent/search', methods=['POST'])
def agent_search():
    """MiroFlow-style search agent: providerized search, snippet evidence, page fetch, and quality gate."""
    payload = request.get_json(force=True, silent=True) or {}
    try:
        return jsonify(_agent_search_agent_payload(payload))
    except ValueError as exc:
        return jsonify({"success": False, "error": str(exc)}), 400
    except Exception as exc:
        return jsonify({"success": False, "error": str(exc)}), 502


@app.route('/api/agent/search/stream', methods=['POST'])
def agent_search_stream():
    """Stream observable MiroFlow search-agent steps over SSE."""
    payload = request.get_json(force=True, silent=True) or {}

    def generate():
        event_queue = queue.Queue()
        done = object()

        def emit(event_name, data):
            event_queue.put((event_name, data))

        def worker():
            try:
                result = _agent_search_agent_payload(payload, emit=emit)
                event_queue.put(("result", result))
            except Exception as exc:
                event_queue.put(("error", {"success": False, "error": str(exc)}))
            finally:
                event_queue.put(done)

        threading.Thread(target=worker, daemon=True).start()
        yield "retry: 1000\n\n"
        while True:
            item = event_queue.get()
            if item is done:
                break
            event_name, data = item
            yield _sse_message(event_name, data)

    return Response(
        stream_with_context(generate()),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
        },
    )


# ---------------------------------------------------------------------------
# SearchSubAgent — MiroFlow-style sub-worker with dual-route search
# ---------------------------------------------------------------------------


class SearchSubAgent(MiroFlowSearchSubAgent):
    MAX_ITERATIONS = 12
    TOOLS = MiroFlowSearchSubAgent.tool_compat_definitions()
    SYSTEM_PROMPT = "MiroFlow-style dual-route search sub-agent"

    def __init__(self, goal, api_key=None, max_iterations=None, parent_event_queue=None, context=None):
        config = MiroFlowSearchAgentConfig(
            max_turns=max_iterations or self.MAX_ITERATIONS,
            max_tool_calls_per_turn=1,
            max_parallel_fetches=AGENT_SEARCH_MAX_PARALLEL_FETCHES,
            default_fetch_budget=LONGCAT_SEARCH_DEFAULT_FETCH_BUDGET,
            chinese_context=True,
            page_evidence_max_chars=AGENT_SEARCH_PAGE_EVIDENCE_MAX_CHARS,
            page_raw_max_chars=AGENT_SEARCH_PAGE_RAW_MAX_CHARS,
            llm_temperature=0.2,
            llm_max_tokens=2400,
            llm_timeout_seconds=60,
        )
        hooks = MiroFlowSearchAgentHooks(
            longcat_request=_longcat_proxy_request,
            default_api_key=lambda: (_longcat_proxy_keys()[0] if _longcat_proxy_keys() else ""),
            dual_search=lambda query, use_cache=None, merged_limit=12: _agent_search_dual_refs(
                query,
                use_cache=use_cache,
                merged_limit=merged_limit,
                context=self.context,
            ),
            fetch_clean_page=lambda url, timeout=None: _agent_fetch_clean_page(url, timeout=timeout),
            build_candidate_pool=_agent_build_candidate_pool,
            candidate_pool_summary=_agent_candidate_pool_summary,
            build_document_capsules=_agent_build_document_capsules,
            build_evidence_matrix=_agent_build_evidence_matrix,
            build_compressed_evidence_brief=_agent_build_compressed_evidence_brief,
            evaluate_search_sufficiency=lambda goal_text, evidence_summary, pages_count, domains_count, depth: _agent_evaluate_search_sufficiency(
                goal=goal_text,
                evidence_summary=evidence_summary,
                pages_count=pages_count,
                domains_count=domains_count,
                depth=depth,
            ),
            search_stop_state=lambda profile, budget, depth, pages, evidence_score: _agent_search_stop_state(
                profile,
                budget,
                depth,
                pages,
                evidence_score,
            ),
            build_document_source_evidence=_agent_build_document_source_evidence,
            clean_documents_for_output=_agent_clean_documents_for_output,
            page_evidence_text=_agent_page_evidence_text,
            url_domain=_agent_url_domain,
            compact_text=_native_compact_text,
            goal_profile=_agent_goal_profile,
            search_depth=_agent_search_depth,
            budget_for_profile=_agent_budget_for_profile,
            select_fetch_candidates=_agent_select_fetch_candidates_by_engine,
        )
        super().__init__(
            goal=goal,
            hooks=hooks,
            config=config,
            api_key=api_key or (_longcat_proxy_keys()[0] if _longcat_proxy_keys() else ""),
            event_queue=parent_event_queue,
        )
        self.context = context


def _unique_hosts(*hosts):
    seen = set()
    result = []
    for host in hosts:
        normalized = _normalize_api_host(host, "")
        if normalized and normalized not in seen:
            seen.add(normalized)
            result.append(normalized)
    return result


def _qweather_auth_variants():
    if not QWEATHER_KEY:
        return []
    key = QWEATHER_KEY.strip()
    looks_like_jwt = key.startswith("eyJ") or key.count(".") >= 2
    header_variants = [
        {"headers": {"X-QW-Api-Key": key}, "params": {}},
        {"headers": {"Authorization": f"Bearer {key}"}, "params": {}},
    ]
    if QWEATHER_AUTH_MODE == "bearer" or looks_like_jwt:
        header_variants = [header_variants[1], header_variants[0]]
    elif QWEATHER_AUTH_MODE in ("x-qw-api-key", "api-key", "apikey", "header"):
        header_variants = [header_variants[0], header_variants[1]]
    return header_variants + [{"headers": {}, "params": {"key": key}}]


def _read_json_response(resp):
    raw = resp.read()
    encoding = ""
    try:
        encoding = resp.headers.get("Content-Encoding") or ""
    except Exception:
        encoding = ""
    if raw and ("gzip" in encoding.lower() or raw[:2] == b"\x1f\x8b"):
        try:
            raw = gzip.decompress(raw)
        except Exception:
            pass
    text = raw.decode("utf-8", errors="replace")
    try:
        return json.loads(text)
    except Exception:
        return {"code": str(getattr(resp, "status", 0) or 0), "raw": text[:2000]}


def _qweather_get_json(hosts, path, params, timeout=15):
    last_error = None
    last_payload = None
    auth_variants = _qweather_auth_variants()
    if not auth_variants:
        raise RuntimeError("Weather API key not configured")

    for host in _unique_hosts(*hosts):
        endpoint = f"{host}{path}"
        for variant in auth_variants:
            query = dict(params or {})
            query.update(variant.get("params") or {})
            url = f"{endpoint}?{urlencode(query)}"
            headers = {
                "Accept": "application/json",
                "Accept-Encoding": "gzip",
                "User-Agent": "blanket-weather/1.0",
            }
            headers.update(variant.get("headers") or {})
            req = urllib.request.Request(url, headers=headers)
            try:
                with urllib.request.urlopen(req, timeout=timeout) as resp:
                    payload = _read_json_response(resp)
                last_payload = payload
                if str(payload.get("code")) == "200":
                    return payload
            except urllib.error.HTTPError as exc:
                try:
                    payload = _read_json_response(exc)
                    last_payload = payload
                    last_error = payload.get("info") or payload.get("message") or f"HTTP {exc.code}"
                except Exception:
                    last_error = f"HTTP {exc.code}"
            except Exception as exc:
                last_error = str(exc)

    if last_payload is not None:
        return last_payload
    raise RuntimeError(last_error or "QWeather request failed")


def _qweather_payload_error_text(payload):
    if not isinstance(payload, dict):
        return ""
    parts = [
        payload.get("info"),
        payload.get("message"),
        payload.get("title"),
        payload.get("detail"),
    ]
    err = payload.get("error")
    if isinstance(err, dict):
        parts.extend([err.get("info"), err.get("message"), err.get("title"), err.get("detail")])
    return " ".join(str(item) for item in parts if item)


def _qweather_invalid_host(payload):
    text = _qweather_payload_error_text(payload).lower()
    return "invalid host" in text or "unauthorized api host" in text


QWEATHER_FORECAST_DAYS = {"3d", "7d", "10d", "15d", "30d"}
QWEATHER_GRID_FORECAST_DAYS = {"3d", "7d"}


def _qweather_normalize_days(value="", query=""):
    text = f"{value or ''} {query or ''}".lower()
    if re.search(r"30\s*(?:天|日|d|day)|一个月|一月", text):
        return "30d"
    if re.search(r"15\s*(?:天|日|d|day)|半个月|两周|2\s*(?:周|week)", text):
        return "15d"
    if re.search(r"10\s*(?:天|日|d|day)", text):
        return "10d"
    if re.search(r"7\s*(?:天|日|d|day)|一周|1\s*(?:周|week)|未来一?周", text):
        return "7d"
    if str(value or "").strip().lower() in QWEATHER_FORECAST_DAYS:
        return str(value).strip().lower()
    return "3d"


def _qweather_is_coordinate_location(value):
    return bool(_amap_normalize_location(value))


def _qweather_location_reject_reason(location, query=""):
    value = re.sub(r"\s+", "", str(location or "")).strip()
    if not value:
        return "missing_location"
    if _qweather_is_coordinate_location(value):
        return ""
    if re.fullmatch(r"\d{6,12}", value):
        return ""
    if len(value) > 36:
        return "location_too_long"
    if len(value) > 22 and not re.search(r"(省|市|区|县|镇|乡|村|路|街|巷|商圈|广场|公园|机场|车站|火车站|高铁站|大学|学院|医院|酒店|商场|小区|写字楼|公司|店|馆|城|园|步行街)$", value):
        return "looks_like_full_prompt"
    if re.search(r"(帮我|规划|安排|推荐|出去玩|老公|老婆|孩子|小孩|别离|太远|适合|方案|理由|购买|团购票|美团|大众点评)", value):
        return "looks_like_task_text"
    if query and value == re.sub(r"\s+", "", str(query or "")).strip() and len(value) > 12:
        return "location_equals_full_query"
    return ""


def _qweather_clean_daily_item(item):
    if not isinstance(item, dict):
        return {}
    keys = [
        "fxDate", "sunrise", "sunset", "moonrise", "moonset", "moonPhase", "moonPhaseIcon",
        "tempMax", "tempMin", "iconDay", "textDay", "iconNight", "textNight",
        "wind360Day", "windDirDay", "windScaleDay", "windSpeedDay",
        "wind360Night", "windDirNight", "windScaleNight", "windSpeedNight",
        "humidity", "precip", "pressure", "vis", "cloud", "uvIndex", "dew",
    ]
    return {key: _amap_clean_string(item.get(key)) for key in keys if item.get(key) is not None}


def _qweather_daily(location_id, days="3d", lang="zh", unit="m", grid=False):
    days = _qweather_normalize_days(days)
    if grid and days not in QWEATHER_GRID_FORECAST_DAYS:
        days = "7d"
    path = f"/v7/{'grid-weather' if grid else 'weather'}/{days}"
    params = {"location": location_id, "lang": lang or "zh", "unit": unit or "m"}
    return _qweather_get_json(
        _unique_hosts(QWEATHER_HOST, "https://devapi.qweather.com"),
        path,
        params,
        timeout=12,
    )


def _qweather_lookup_city(location, adm="", range_code="", lang="zh", number=5):
    params = {
        "location": location,
        "number": max(1, min(int(number or 5), 20)),
        "lang": lang or "zh",
    }
    if adm:
        params["adm"] = adm
    if range_code:
        params["range"] = range_code
    payload = _qweather_get_json(
        _unique_hosts(QWEATHER_GEO_HOST, QWEATHER_HOST, "https://geoapi.qweather.com", "https://devapi.qweather.com"),
        "/geo/v2/city/lookup",
        params,
        timeout=12,
    )
    if str(payload.get("code")) == "200":
        return payload

    # Legacy public GeoAPI uses /v2/city/lookup, while custom API Host uses /geo/v2/city/lookup.
    legacy_payload = _qweather_get_json(
        ["https://geoapi.qweather.com"],
        "/v2/city/lookup",
        params,
        timeout=12,
    )
    if str(legacy_payload.get("code")) == "200":
        return legacy_payload
    return payload


def _qweather_now(location_id, lang="zh"):
    return _qweather_get_json(
        _unique_hosts(QWEATHER_HOST, "https://devapi.qweather.com"),
        "/v7/weather/now",
        {"location": location_id, "lang": lang or "zh"},
        timeout=12,
    )


@app.route('/api/weather', methods=['POST'])
def weather_proxy():
    """Validate a weather location, then query QWeather now + daily forecast."""
    if not QWEATHER_KEY:
        return jsonify({'code': 'CONFIG_MISSING', 'error': 'Weather API key not configured'}), 503
    if not QWEATHER_HOST_RAW:
        return jsonify({
            'code': 'CONFIG_MISSING',
            'error': '和风天气 API Host 未配置。请在服务器配置 QWEATHER_API_HOST 或 /opt/longcat/.qweather_host。',
        }), 503
    data = request.get_json(force=True, silent=True) or {}
    query = (data.get('query') or '').strip()
    location = (data.get('location') or '').strip()
    if not location:
        return jsonify({
            'code': 'NEEDS_WEATHER_LOCATION',
            'error': '天气查询需要城市、地点、LocationID 或经纬度。',
            'query': query,
            'needsRepair': True,
            'repairInstruction': '请用 get_weather 原生 function calling 重试：location 只填写城市、区县、POI、LocationID 或经纬度；如果用户指当前位置，设置 use_gps=true。',
            'resolutionAttempts': [{"candidate": location, "status": "rejected", "reason": "missing_location"}],
        })

    lang = (data.get('lang') or 'zh').strip() or 'zh'
    unit = (data.get('unit') or 'm').strip() or 'm'
    adm = (data.get('adm') or '').strip()
    range_code = (data.get('range') or '').strip()
    number = data.get('number') or 5
    days = _qweather_normalize_days(data.get("days"), query=query)
    api_type = (data.get("type") or "city").strip().lower()
    resolution_attempts = []

    reject_reason = _qweather_location_reject_reason(location, query=query)
    if reject_reason:
        resolution_attempts.append({"candidate": location, "status": "rejected", "reason": reject_reason})
        return jsonify({
            "code": "NEEDS_WEATHER_LOCATION_REPAIR",
            "error": "天气 location 参数不像有效地点，不能使用完整用户句子查询天气。",
            "query": query,
            "location": location,
            "forecastDays": days,
            "needsRepair": True,
            "repairInstruction": "请让模型重新调用 get_weather：query 保留原始需求，location 只填城市/区县/POI/LocationID/经纬度，不要填完整句子。",
            "resolutionAttempts": resolution_attempts,
        })

    try:
        lookup_payload = {}
        locations = []
        selected = {}
        grid = api_type == "grid" and _qweather_is_coordinate_location(location)
        if _qweather_is_coordinate_location(location):
            normalized_location = _amap_normalize_location(location)
            location_id = normalized_location
            selected = {
                "name": data.get("location_name") or data.get("locationName") or "当前位置",
                "id": normalized_location,
                "lon": normalized_location.split(",")[0],
                "lat": normalized_location.split(",")[1],
                "type": "coordinate",
            }
            resolution_attempts.append({"candidate": location, "status": "accepted", "reason": "coordinate"})
        else:
            lookup_payload = _qweather_lookup_city(location, adm=adm, range_code=range_code, lang=lang, number=number)
            if str(lookup_payload.get("code")) != "200":
                if _qweather_invalid_host(lookup_payload):
                    return jsonify({
                        "code": "CONFIG_MISSING",
                        "error": "和风天气 API Host 未配置或与当前 Key 不匹配。请在服务器配置 QWEATHER_API_HOST 或 /opt/longcat/.qweather_host。",
                        "raw": lookup_payload,
                    }), 503
                resolution_attempts.append({"candidate": location, "status": "rejected", "reason": lookup_payload.get("code") or "lookup_failed"})
                return jsonify({
                    "code": "NEEDS_WEATHER_LOCATION_REPAIR",
                    "error": lookup_payload.get("info") or lookup_payload.get("message") or "城市/地点解析失败",
                    "query": query,
                    "location": location,
                    "forecastDays": days,
                    "needsRepair": True,
                    "repairInstruction": "QWeather GeoAPI 没有识别该 location。请重新调用 get_weather，location 填更短、更明确的城市、区县、POI 或经纬度。",
                    "raw": lookup_payload,
                    "resolutionAttempts": resolution_attempts,
                })

            locations = lookup_payload.get("location") or []
            if not locations:
                resolution_attempts.append({"candidate": location, "status": "rejected", "reason": "no_location_candidates"})
                return jsonify({
                    "code": "NEEDS_WEATHER_LOCATION_REPAIR",
                    "error": "没有找到匹配的城市或位置",
                    "query": query,
                    "location": location,
                    "forecastDays": days,
                    "locations": [],
                    "needsRepair": True,
                    "repairInstruction": "请重新调用 get_weather，location 填城市、区县、POI 或经纬度；不要传完整用户句子。",
                    "resolutionAttempts": resolution_attempts,
                })

            selected = locations[0]
            location_id = selected.get("id") or location
            resolution_attempts.append({"candidate": location, "status": "accepted", "reason": "geo_lookup", "selected": selected})

        now_payload = _qweather_now(location_id, lang=lang)
        if str(now_payload.get("code")) != "200":
            if _qweather_invalid_host(now_payload):
                return jsonify({
                    "code": "CONFIG_MISSING",
                    "error": "和风天气 API Host 未配置或与当前 Key 不匹配。请在服务器配置 QWEATHER_API_HOST 或 /opt/longcat/.qweather_host。",
                    "raw": now_payload,
                    "location": selected,
                    "locations": locations,
                }), 503
            return jsonify({
                "code": now_payload.get("code") or "WEATHER_FAILED",
                "error": now_payload.get("info") or now_payload.get("message") or "weather lookup failed",
                "raw": now_payload,
                "location": selected,
                "locations": locations,
            }), 502

        daily_payload = _qweather_daily(location_id, days=days, lang=lang, unit=unit, grid=grid)
        if str(daily_payload.get("code")) != "200":
            if _qweather_invalid_host(daily_payload):
                return jsonify({
                    "code": "CONFIG_MISSING",
                    "error": "和风天气 API Host 未配置或与当前 Key 不匹配。请在服务器配置 QWEATHER_API_HOST 或 /opt/longcat/.qweather_host。",
                    "raw": daily_payload,
                    "location": selected,
                    "locations": locations,
                }), 503
            daily_payload = {
                "code": daily_payload.get("code") or "FORECAST_FAILED",
                "daily": [],
                "error": daily_payload.get("info") or daily_payload.get("message") or "forecast lookup failed",
                "raw": daily_payload,
            }

        return jsonify({
            "code": "200",
            "query": location,
            "requestQuery": query,
            "location": selected,
            "resolvedLocation": selected,
            "locationCandidates": locations,
            "locations": locations,
            "forecastDays": days,
            "now": now_payload.get("now") or {},
            "daily": [_qweather_clean_daily_item(item) for item in (daily_payload.get("daily") or [])],
            "dailyRawCode": daily_payload.get("code"),
            "dailyError": daily_payload.get("error") or "",
            "fxLink": daily_payload.get("fxLink") or now_payload.get("fxLink") or "",
            "updateTime": now_payload.get("updateTime") or daily_payload.get("updateTime") or "",
            "refer": daily_payload.get("refer") or now_payload.get("refer") or lookup_payload.get("refer") or {},
            "resolutionAttempts": resolution_attempts,
        })
    except Exception as exc:
        return jsonify({'code': 'WEATHER_PROXY_ERROR', 'error': str(exc)}), 502


@app.route('/api/repo/inspect', methods=['POST'])
def repo_inspect_proxy():
    """Inspect public GitHub/Hugging Face repositories without requiring user login."""
    payload = request.get_json(force=True, silent=True) or {}
    query = str(payload.get("query") or payload.get("url") or payload.get("repo") or "").strip()
    provider = str(payload.get("provider") or "auto").strip().lower()
    try:
        return jsonify(_build_repo_inspect_payload(query, provider=provider))
    except urllib.error.HTTPError as exc:
        body = ""
        try:
            body = exc.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            pass
        status = exc.code if exc.code in {400, 401, 403, 404, 429} else 502
        if exc.code == 403:
            message = "公开仓库读取被 GitHub/Hugging Face 限流或拒绝；稍后再试，或在服务端配置可选 Token 提高限额。"
        elif exc.code == 404:
            message = "没有找到这个公开仓库，或仓库不是公开可读。"
        else:
            message = body or str(exc)
        return jsonify({"success": False, "error": message}), status
    except (urllib.error.URLError, TimeoutError) as exc:
        return jsonify({
            "success": False,
            "error": f"公开仓库网络读取超时或不可达：{str(exc)}",
        }), 502
    except Exception as exc:
        return jsonify({"success": False, "error": str(exc)}), 400


@app.route('/api/read-page', methods=['POST'])
def read_page_proxy():
    """Fetch a URL and extract main text with proper Chinese encoding + BeautifulSoup."""
    import urllib.request as _ureq
    import re as _re

    payload = request.get_json(force=True, silent=True) or {}
    url = (payload.get('url') if isinstance(payload, dict) else None) or ''
    url = url.strip()
    if not url:
        return jsonify({'error': 'url required', 'text': ''}), 400

    UA = (
        'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
        'AppleWebKit/537.36 (KHTML, like Gecko) '
        'Chrome/124.0.0.0 Safari/537.36'
    )
    try:
        req = _ureq.Request(url, headers={
            'User-Agent': UA,
            'Accept': 'text/html,application/xhtml+xml,*/*;q=0.8',
            'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
            'Accept-Encoding': 'identity',
        })
        with _ureq.urlopen(req, timeout=20) as resp:
            raw = resp.read(512 * 1024)
            ct = ''
            try:
                ct = resp.headers.get('Content-Type') or ''
            except Exception:
                ct = ''

        # Detect encoding
        enc = 'utf-8'
        m = _re.search(r'charset[=\s]+([\w-]+)', ct, _re.I)
        if m:
            enc = m.group(1).strip()
        else:
            sniff = raw[:4096].decode('latin-1', errors='replace')
            m2 = _re.search(r'charset[=\s]+([\w-]+)', sniff, _re.I)
            if m2:
                enc = m2.group(1).strip()

        enc_norm = enc.lower().replace('-', '')
        if enc_norm in ('gb2312', 'gbk', 'gb18030', 'cngb'):
            enc = 'gb18030'
        try:
            html = raw.decode(enc, errors='replace')
        except Exception:
            html = raw.decode('utf-8', errors='replace')

        if BeautifulSoup is None:
            # Fallback: strip tags with regex
            text = _re.sub(r'<[^>]+>', ' ', html)
            text = _re.sub(r'\s+', ' ', text).strip()
            return jsonify({'text': text[:10000], 'encoding': enc})

        soup = BeautifulSoup(html, 'lxml')

        # Remove noise tags by type (collect list first, then decompose)
        noise_tags = ['script', 'style', 'noscript', 'nav', 'footer',
                      'header', 'aside', 'iframe', 'figure', 'form',
                      'button', 'svg', 'img', 'picture']
        for tag in list(soup.find_all(noise_tags)):
            try:
                tag.decompose()
            except Exception:
                pass

        # Remove noise tags by class/id (collect list first, then decompose)
        noise_words = ('nav', 'menu', 'sidebar', 'footer', 'header',
                       'comment', ' ad ', 'banner', 'cookie', 'popup',
                       'recommend', 'related', 'share', 'social', 'toolbar')
        candidates = list(soup.find_all(True))
        for tag in candidates:
            try:
                attrs = getattr(tag, 'attrs', None) or {}
                cls_list = attrs.get('class') or []
                if isinstance(cls_list, str):
                    cls_list = [cls_list]
                cls = ' ' + ' '.join(cls_list).lower() + ' '
                tid = ' ' + str(attrs.get('id') or '').lower() + ' '
                if any(n in cls or n in tid for n in noise_words):
                    tag.decompose()
            except Exception:
                pass

        # Find best content container
        main = None
        for selector in [
            lambda s: s.find('article'),
            lambda s: s.find(id='article'),
            lambda s: s.find(id='content'),
            lambda s: s.find(id='main'),
            lambda s: s.find(class_='article'),
            lambda s: s.find(class_='content'),
            lambda s: s.find(class_='main'),
            lambda s: s.find('main'),
        ]:
            try:
                result = selector(soup)
                if result and len(result.get_text(strip=True)) > 200:
                    main = result
                    break
            except Exception:
                pass

        if main is None:
            main = soup.body or soup

        try:
            text = main.get_text(separator='\n', strip=True)
        except Exception:
            text = soup.get_text(separator='\n', strip=True)

        # Collapse blank lines
        text = _re.sub(r'\n{3,}', '\n\n', text).strip()

        return jsonify({'text': text[:10000], 'encoding': enc, 'length': len(text)})

    except Exception as exc:
        import traceback
        tb = traceback.format_exc()
        app.logger.error(f'[read-page] {exc}\n{tb}')
        return jsonify({'error': str(exc), 'text': ''}), 502


@app.route('/api/memory/context', methods=['POST'])
def memory_context():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({
            "success": True,
            "persist": False,
            "memoryBlock": "",
            "memories": [],
            "atomicFacts": [],
            "episodes": [],
            "foresights": [],
            "candidates": [],
            "locationAnchors": [],
            "retrievalTrace": {},
            "personalizationPrompt": "",
            "selectedMemories": [],
            "selectionTrace": {},
            "conflictSummary": {},
            "threadSummary": "",
            "crossSummaries": [],
        })

    query = str(payload.get("query") or "").strip()[:2000]
    session_id = str(payload.get("session_id") or payload.get("sessionId") or "").strip()[:160]
    include_inferred = payload.get("include_inferred")
    if include_inferred is None:
        include_inferred = payload.get("includeInferred")
    include_inferred = include_inferred is not False
    user_key = user_info["user_key"]
    with _MemoryDbLockAttempt() as lock_acquired:
        if not lock_acquired:
            return jsonify({
                "success": True,
                "persist": True,
                "degraded": True,
                "memoryBlock": "",
                "memories": [],
                "atomicFacts": [],
                "episodes": [],
                "foresights": [],
                "candidates": [],
                "locationAnchors": [],
                "retrievalTrace": {"reason": "memory_db_busy", "waitMs": MEMORY_READ_LOCK_WAIT_MS},
                "personalizationPrompt": "",
                "selectedMemories": [],
                "selectionTrace": {"reason": "memory_db_busy", "waitMs": MEMORY_READ_LOCK_WAIT_MS},
                "conflictSummary": {},
                "threadSummary": "",
                "crossSummaries": [],
                "tdai": {"enabled": bool(MEMORY_TDAI_GATEWAY_URL), "available": False, "reason": "memory_db_busy"},
            })
        conn = _memory_connect()
        try:
            _memory_ensure_layers(conn, user_key)
            thread_summary = ""
            if session_id:
                row = conn.execute(
                    "SELECT summary FROM thread_summaries WHERE user_key = ? AND session_id = ?",
                    (user_key, session_id),
                ).fetchone()
                thread_summary = (row["summary"] if row else "") or ""

            summary_rows = conn.execute(
                """
                SELECT session_id, summary, updated_at FROM thread_summaries
                WHERE user_key = ? AND session_id != ?
                ORDER BY updated_at DESC
                LIMIT 60
                """,
                (user_key, session_id or "__none__"),
            ).fetchall()
            query_tokens = _memory_tokens(query)
            scored_summaries = []
            for row in summary_rows:
                summary = row["summary"] or ""
                overlap = len(query_tokens & _memory_tokens(summary))
                recency = max(0, 1 - ((_memory_now_ms() - int(row["updated_at"] or 0)) / (1000 * 60 * 60 * 24 * 30)))
                score = overlap * 2 + recency
                if overlap or score > 0.45:
                    scored_summaries.append((score, {
                        "sessionId": row["session_id"],
                        "summary": summary,
                        "updatedAt": int(row["updated_at"] or 0),
                    }))
            scored_summaries.sort(key=lambda pair: pair[0], reverse=True)
            cross_summaries = [summary for _score, summary in scored_summaries[:4] if summary.get("summary")]
            retrieval = _memory_agentic_retrieve(conn, user_key, query, session_id=session_id, include_inferred=include_inferred)
            memories = retrieval["memories"]
            scenes = retrieval["scenes"]
            l0_snippets = retrieval["l0Snippets"]
            atomic_facts = retrieval["atomicFacts"]
            episodes = retrieval["episodes"]
            foresights = retrieval["foresights"]
            retrieval_trace = retrieval["retrievalTrace"]
            candidates = _memory_search_candidates(conn, user_key, query, limit=5)
            promoted_candidates = _memory_bump_candidate_reuse(conn, user_key, candidates, session_id=session_id)
            if promoted_candidates:
                _memory_rebuild_scenes_for_user(conn, user_key)
                _memory_refresh_profile(conn, user_key)
                _memory_rebuild_units_for_user(conn, user_key, sync_vector=False)
                candidates = _memory_search_candidates(conn, user_key, query, limit=5)
            location_anchors = _memory_list_location_anchors(conn, user_key)
            persona = _memory_get_profile(conn, user_key) if include_inferred else ""
            personalization = _memory_build_personalization_context(
                conn,
                user_key,
                query,
                session_id=session_id,
                recent_messages=payload.get("recent_messages") or payload.get("recentMessages") or [],
                include_inferred=include_inferred,
            )
            conn.commit()
        finally:
            conn.close()

    tdai_recall = _memory_tencentdb_recall(user_key, session_id, query)
    memory_block = _memory_build_context_block(
        memories,
        thread_summary,
        cross_summaries,
        scenes=scenes,
        persona=persona,
        l0_snippets=l0_snippets,
        gateway_context=tdai_recall.get("context") if tdai_recall.get("available") else "",
        atomic_facts=atomic_facts,
        episodes=episodes,
        foresights=foresights,
        retrieval_trace=retrieval_trace,
    )

    return jsonify({
        "success": True,
        "persist": True,
        "memoryBlock": memory_block,
        "memories": memories,
        "atomicFacts": atomic_facts,
        "episodes": episodes,
        "foresights": foresights,
        "candidates": candidates,
        "locationAnchors": location_anchors,
        "retrievalTrace": retrieval_trace,
        "personalizationPrompt": personalization.get("personalizationPrompt") if isinstance(personalization, dict) else "",
        "selectedMemories": personalization.get("selectedMemories") if isinstance(personalization, dict) else [],
        "selectionTrace": personalization.get("selectionTrace") if isinstance(personalization, dict) else {},
        "conflictSummary": personalization.get("conflictSummary") if isinstance(personalization, dict) else {},
        "scenes": scenes,
        "persona": persona,
        "l0Snippets": l0_snippets,
        "threadSummary": thread_summary,
        "crossSummaries": cross_summaries,
        "tdai": tdai_recall,
    })


@app.route('/api/memory/ingest-turn', methods=['POST'])
def memory_ingest_turn():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({"success": True, "persist": False, "accepted": [], "candidates": [], "locationAnchors": []})

    user_key = user_info["user_key"]
    session_id = str(payload.get("session_id") or payload.get("sessionId") or "").strip()[:160]
    turn_id = str(payload.get("turn_id") or payload.get("turnId") or f"turn_{uuid.uuid4().hex[:18]}").strip()[:160]
    remember_intent = str(payload.get("remember_intent") or payload.get("rememberIntent") or "model_decide").strip()[:40]
    raw_messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    recent_messages = payload.get("recent_messages") or payload.get("recentMessages") or raw_messages
    runtime_context = _memory_clean_runtime_context(payload.get("runtime_context") or payload.get("runtimeContext") or payload)
    source_message_id = str(payload.get("source_message_id") or payload.get("sourceMessageId") or "").strip()[:160]
    custom_key = request.headers.get("X-LongCat-Api-Key", "")
    sanitized_turn = _memory_sanitize_messages(raw_messages, max_content=12000)
    if not sanitized_turn:
        return jsonify({"success": False, "error": "缺少可写入的 turn messages"}), 400

    accepted = []
    candidates = []
    promoted = []
    location_anchors = []
    extraction = {}
    segment_id = None
    consolidation = {"ran": False, "reason": "not_due"}
    existing_bits = []
    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            _memory_ensure_layers(conn, user_key)
            persona = _memory_get_profile(conn, user_key)
            if persona:
                existing_bits.append(persona[:1600])
            anchors = _memory_list_location_anchors(conn, user_key)
            if anchors:
                existing_bits.append("位置锚点（无精确坐标）：" + json.dumps(anchors[:8], ensure_ascii=False))
            conn.commit()
        finally:
            conn.close()

    extraction = _memory_extract_turn_with_llm(
        sanitized_turn,
        runtime_context,
        remember_intent=remember_intent,
        existing_context="\n\n".join(existing_bits),
        custom_key=custom_key,
    )
    segment_summary = extraction.get("segmentSummary") or _memory_build_recent_summary(sanitized_turn)

    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            session_message_ids = _memory_record_session_messages(conn, user_key, session_id, turn_id, sanitized_turn, runtime_context)
            l0_ids = _memory_record_l0_messages(conn, user_key, session_id, recent_messages or sanitized_turn, source_message_id)
            segment_id = _memory_upsert_session_segment(conn, user_key, session_id, session_message_ids, summary=segment_summary)
            if session_id and segment_summary:
                conn.execute(
                    """
                    INSERT INTO thread_summaries(user_key, session_id, summary, updated_at)
                    VALUES (?, ?, ?, ?)
                    ON CONFLICT(user_key, session_id)
                    DO UPDATE SET summary = excluded.summary, updated_at = excluded.updated_at
                    """,
                    (user_key, session_id, segment_summary[:3000], _memory_now_ms()),
                )
            commit_memcell_id = _memory_upsert_memcell(
                conn,
                user_key,
                session_id,
                l0_ids=l0_ids,
                summary=segment_summary,
                metadata={"source": "memory_ingest_turn", "turnId": turn_id, "rememberIntent": remember_intent},
            )
            layer = "explicit" if remember_intent in {"explicit", "manual"} else "inferred"
            accepted = _memory_store_accepted_items(
                conn,
                user_key,
                session_id,
                source_message_id,
                [str(item) for item in session_message_ids + l0_ids],
                extraction.get("acceptedMemories") or [],
                layer=layer,
                memcell_id=commit_memcell_id,
            )
            candidates, promoted = _memory_upsert_candidates(
                conn,
                user_key,
                session_id,
                turn_id,
                [str(item) for item in session_message_ids + l0_ids],
                extraction.get("candidateMemories") or [],
            )
            location_anchors = _memory_upsert_location_anchors(
                conn,
                user_key,
                session_id,
                turn_id,
                runtime_context,
                extraction.get("locationAnchors") or [],
            )
            if accepted or promoted:
                _memory_rebuild_scenes_for_user(conn, user_key)
                _memory_refresh_profile(conn, user_key)
                if commit_memcell_id:
                    _memory_build_episode_for_memcell(conn, user_key, commit_memcell_id, accepted[0].get("sceneName") if accepted else "")
            consolidation = _memory_consolidate_user(conn, user_key, force=False)
            _memory_insert_event(conn, user_key, "memory_ingest_turn", None, {
                "sessionId": session_id,
                "turnId": turn_id,
                "accepted": len(accepted),
                "candidates": len(candidates),
                "promoted": len(promoted),
                "locationAnchors": len(location_anchors),
                "llmError": extraction.get("llmError") or "",
            })
            conn.commit()
        finally:
            conn.close()

    return jsonify({
        "success": True,
        "persist": True,
        "turnId": turn_id,
        "accepted": accepted,
        "candidates": candidates,
        "promoted": promoted,
        "locationAnchors": location_anchors,
        "segmentSummary": extraction.get("segmentSummary") or "",
        "segmentId": segment_id,
        "followupQuestion": extraction.get("followupQuestion") or "",
        "reason": extraction.get("reason") or "",
        "llmError": extraction.get("llmError") or "",
        "maintenance_result": consolidation,
    })


@app.route('/api/memory/search-history', methods=['POST'])
def memory_search_history():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({"success": True, "persist": False, "sessions": [], "segments": [], "messageSnippets": [], "sources": []})
    user_key = user_info["user_key"]
    query = str(payload.get("query") or "").strip()[:2000]
    time_range = payload.get("time_range") or payload.get("timeRange") or {}
    if not isinstance(time_range, dict):
        time_range = {}
    start_ms = int(float(time_range.get("startMs") or time_range.get("start") or 0) or 0)
    end_ms = int(float(time_range.get("endMs") or time_range.get("end") or 0) or 0)
    if end_ms <= 0:
        end_ms = _memory_now_ms() + 24 * 60 * 60 * 1000
    session_scope = str(payload.get("session_scope") or payload.get("sessionScope") or "").strip()[:160]
    limit = max(4, min(int(payload.get("limit") or 12), 40))
    query_tokens = _memory_tokens(query)
    fts_query = _memory_fts_query(query, max_terms=28)

    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            message_rows = []
            segment_rows = []
            if fts_query:
                try:
                    params = [fts_query, user_key, user_key, start_ms, end_ms]
                    session_clause = ""
                    if session_scope:
                        session_clause = "AND m.session_id = ?"
                        params.append(session_scope)
                    params.append(max(limit * 4, 40))
                    message_rows = conn.execute(
                        f"""
                        SELECT m.*, bm25(session_messages_fts) AS fts_rank
                        FROM session_messages_fts
                        JOIN session_messages m ON m.id = session_messages_fts.message_id
                        WHERE session_messages_fts MATCH ?
                          AND session_messages_fts.user_key = ?
                          AND m.user_key = ?
                          AND m.created_at BETWEEN ? AND ?
                          {session_clause}
                        ORDER BY fts_rank
                        LIMIT ?
                        """,
                        tuple(params),
                    ).fetchall()
                except Exception:
                    message_rows = []
                try:
                    params = [fts_query, user_key, user_key, start_ms, end_ms]
                    session_clause = ""
                    if session_scope:
                        session_clause = "AND s.session_id = ?"
                        params.append(session_scope)
                    params.append(max(limit * 3, 24))
                    segment_rows = conn.execute(
                        f"""
                        SELECT s.*, bm25(session_segments_fts) AS fts_rank
                        FROM session_segments_fts
                        JOIN session_segments s ON s.id = session_segments_fts.segment_id
                        WHERE session_segments_fts MATCH ?
                          AND session_segments_fts.user_key = ?
                          AND s.user_key = ?
                          AND COALESCE(s.end_at, s.updated_at) BETWEEN ? AND ?
                          {session_clause}
                        ORDER BY fts_rank
                        LIMIT ?
                        """,
                        tuple(params),
                    ).fetchall()
                except Exception:
                    segment_rows = []

            if not message_rows:
                params = [user_key, start_ms, end_ms]
                session_clause = ""
                if session_scope:
                    session_clause = "AND session_id = ?"
                    params.append(session_scope)
                params.append(max(limit * 8, 80))
                rows = conn.execute(
                    f"""
                    SELECT * FROM session_messages
                    WHERE user_key = ? AND created_at BETWEEN ? AND ?
                    {session_clause}
                    ORDER BY created_at DESC
                    LIMIT ?
                    """,
                    tuple(params),
                ).fetchall()
                scored = []
                for row in rows:
                    tokens = _memory_tokens(row["content"])
                    overlap = len(query_tokens & tokens)
                    recency = max(0, 1 - ((_memory_now_ms() - int(row["created_at"] or 0)) / (1000 * 60 * 60 * 24 * 120)))
                    score = overlap * 2.0 + recency
                    if not query_tokens or overlap:
                        scored.append((score, row))
                scored.sort(key=lambda pair: pair[0], reverse=True)
                message_rows = [row for _score, row in scored[:max(limit * 2, 20)]]

            if not segment_rows:
                params = [user_key, start_ms, end_ms]
                session_clause = ""
                if session_scope:
                    session_clause = "AND session_id = ?"
                    params.append(session_scope)
                params.append(max(limit * 3, 24))
                segment_rows = conn.execute(
                    f"""
                    SELECT * FROM session_segments
                    WHERE user_key = ? AND COALESCE(end_at, updated_at) BETWEEN ? AND ?
                    {session_clause}
                    ORDER BY updated_at DESC
                    LIMIT ?
                    """,
                    tuple(params),
                ).fetchall()

            snippets = []
            seen_messages = set()
            for row in message_rows[: max(limit * 2, 20)]:
                if row["id"] in seen_messages:
                    continue
                seen_messages.add(row["id"])
                snippets.append({
                    "id": row["id"],
                    "sessionId": row["session_id"],
                    "turnId": row["turn_id"],
                    "role": row["role"],
                    "content": row["content"],
                    "createdAt": row["created_at"],
                    "score": round(_memory_bm25_to_score(row["fts_rank"]) if "fts_rank" in row.keys() else 1.0, 3),
                })

            segments = [
                {
                    "id": row["id"],
                    "sessionId": row["session_id"],
                    "segmentKey": row["segment_key"],
                    "summary": row["summary"],
                    "keywords": _memory_safe_json(row["keywords"], []),
                    "messageIds": _memory_safe_json(row["message_ids"], []),
                    "startAt": row["start_at"],
                    "endAt": row["end_at"],
                    "updatedAt": row["updated_at"],
                    "score": round(_memory_bm25_to_score(row["fts_rank"]) if "fts_rank" in row.keys() else 1.0, 3),
                }
                for row in segment_rows[:limit]
            ]

            sessions_map = {}
            for item in snippets:
                sid = item.get("sessionId") or ""
                if not sid:
                    continue
                bucket = sessions_map.setdefault(sid, {"sessionId": sid, "messageCount": 0, "snippets": [], "updatedAt": 0})
                bucket["messageCount"] += 1
                bucket["updatedAt"] = max(bucket["updatedAt"], int(item.get("createdAt") or 0))
                if len(bucket["snippets"]) < 4:
                    bucket["snippets"].append(item)
            for seg in segments:
                sid = seg.get("sessionId") or ""
                if sid:
                    bucket = sessions_map.setdefault(sid, {"sessionId": sid, "messageCount": 0, "snippets": [], "updatedAt": 0})
                    bucket["updatedAt"] = max(bucket["updatedAt"], int(seg.get("updatedAt") or 0))
            sessions_result = sorted(sessions_map.values(), key=lambda item: item.get("updatedAt") or 0, reverse=True)[:limit]
            conn.commit()
        finally:
            conn.close()

    sources = [
        {"title": f"历史会话 {item['sessionId']}", "url": f"longcat://session/{item['sessionId']}", "type": "session"}
        for item in sessions_result[:8]
    ]
    return jsonify({
        "success": True,
        "persist": True,
        "sessions": sessions_result,
        "segments": segments,
        "messageSnippets": snippets[:limit],
        "sources": sources,
    })


@app.route('/api/memory/commit', methods=['POST'])
def memory_commit():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({"success": True, "persist": False, "saved": 0})

    user_key = user_info["user_key"]
    session_id = str(payload.get("session_id") or payload.get("sessionId") or "").strip()[:160]
    source_message_id = str(payload.get("source_message_id") or payload.get("sourceMessageId") or "").strip()[:160]
    recent_messages = payload.get("recent_messages") or payload.get("recentMessages") or []
    thread_summary = str(payload.get("thread_summary") or payload.get("threadSummary") or "").strip()
    if not thread_summary:
        thread_summary = _memory_build_recent_summary(recent_messages)
    thread_summary = thread_summary[:3000]

    long_term_mode = str(
        payload.get("long_term_mode")
        or payload.get("longTermMode")
        or payload.get("memory_mode")
        or payload.get("memoryMode")
        or ""
    ).strip().lower()
    raw_items = payload.get("items") if isinstance(payload.get("items"), list) else []
    if long_term_mode not in {"explicit", "auto", "summary_only"}:
        long_term_mode = "auto" if raw_items else "summary_only"
    if long_term_mode == "summary_only":
        raw_items = []
    memory_layer = _memory_user_controlled_layer(long_term_mode)
    now = _memory_now_ms()
    saved = 0
    skipped = 0
    saved_items = []
    l0_ids = []
    consolidation = {"ran": False, "reason": "not_due"}
    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            l0_ids = _memory_record_l0_messages(conn, user_key, session_id, recent_messages, source_message_id)
            commit_memcell_id = _memory_upsert_memcell(
                conn,
                user_key,
                session_id,
                l0_ids=l0_ids,
                summary=thread_summary,
                metadata={"source": "memory_commit", "mode": long_term_mode},
            )
            if session_id and thread_summary:
                conn.execute(
                    """
                    INSERT INTO thread_summaries(user_key, session_id, summary, updated_at)
                    VALUES (?, ?, ?, ?)
                    ON CONFLICT(user_key, session_id)
                    DO UPDATE SET summary = excluded.summary, updated_at = excluded.updated_at
                    """,
                    (user_key, session_id, thread_summary, now),
                )
                _memory_insert_event(conn, user_key, "thread_summary_upsert", None, {
                    "sessionId": session_id,
                    "summaryChars": len(thread_summary),
                })

            for raw in raw_items[:12]:
                if not isinstance(raw, dict):
                    skipped += 1
                    continue
                content = re.sub(r"\s+", " ", str(raw.get("content") or "").strip())
                if len(content) < 8 or len(content) > 800 or not _memory_sensitive_category_allowed(content, explicit=(long_term_mode == "explicit")):
                    skipped += 1
                    continue
                safe_for_prompt, unsafe_reason = _memory_safe_for_prompt(content)
                if not safe_for_prompt and unsafe_reason in {"prompt_injection", "secret", "control_char"}:
                    skipped += 1
                    continue
                kind = str(raw.get("kind") or "note").strip().lower()[:40] or "note"
                if kind not in {"profile", "preference", "project", "constraint", "note"}:
                    kind = "note"
                tags = raw.get("tags") if isinstance(raw.get("tags"), list) else []
                tags = [str(tag).strip()[:40] for tag in tags if str(tag).strip()][:12]
                confidence = max(0.1, min(float(raw.get("confidence") or 0.72), 1.0))
                if long_term_mode != "explicit" and not _memory_auto_item_allowed(kind, content, confidence):
                    skipped += 1
                    continue
                scene_name = _memory_clean_scene_name(raw.get("scene") or raw.get("sceneName") or _memory_infer_scene_name(kind, content, tags))
                memory_type = _memory_classify_memory_type(kind, content, tags)
                partition = _memory_partition_for(kind, memory_type, tags, scene_name, content)
                facet_path = _memory_facet_path_for(kind, content, tags, partition)
                source_message_ids = raw.get("source_message_ids") or raw.get("sourceMessageIds") or []
                if not isinstance(source_message_ids, list):
                    source_message_ids = []
                source_message_ids = [str(item).strip()[:160] for item in source_message_ids if str(item).strip()]
                if source_message_id:
                    source_message_ids.append(source_message_id)
                source_message_ids.extend(str(item) for item in l0_ids[-4:])
                source_message_ids = list(dict.fromkeys(source_message_ids))[:12]
                content_hash = _memory_content_hash(kind, content)
                existing = conn.execute(
                    "SELECT id FROM memory_items WHERE user_key = ? AND content_hash = ?",
                    (user_key, content_hash),
                ).fetchone()
                merge_candidate = None if existing else _memory_find_merge_candidate(conn, user_key, kind, content)
                if existing or merge_candidate:
                    current_row = existing if existing else merge_candidate
                    item_id = current_row["id"]
                    current_layer = current_row["memory_layer"] if "memory_layer" in current_row.keys() else "explicit"
                    stored_layer = "explicit" if memory_layer == "explicit" or current_layer == "explicit" else memory_layer
                    conn.execute(
                        """
                        UPDATE memory_items
                        SET content = ?, kind = ?, tags = ?, confidence = MAX(confidence, ?),
                            source_session_id = COALESCE(?, source_session_id),
                            source_message_id = COALESCE(?, source_message_id),
                            source_message_ids = ?, scene_name = ?, metadata_json = ?,
                            memory_layer = ?, memcell_id = COALESCE(NULLIF(?, ''), memcell_id),
                            memory_type = ?, support_count = COALESCE(support_count, 1) + 1,
                            resolution_status = 'active', facet_path = ?,
                            updated_at = ?, deleted_at = NULL
                        WHERE id = ? AND user_key = ?
                        """,
                        (
                            content,
                            kind,
                            json.dumps(tags, ensure_ascii=False),
                            confidence,
                            session_id or None,
                            source_message_id or None,
                            json.dumps(source_message_ids, ensure_ascii=False),
                            scene_name,
                            json.dumps({"layer": "L1", "source": "longcat"}, ensure_ascii=False),
                            stored_layer,
                            commit_memcell_id,
                            memory_type,
                            facet_path,
                            now,
                            item_id,
                            user_key,
                        ),
                    )
                    _memory_insert_event(conn, user_key, "memory_update", item_id, {"content": content, "kind": kind})
                else:
                    cur = conn.execute(
                        """
                        INSERT INTO memory_items(
                            user_key, kind, content, content_hash, tags, confidence,
                            source_session_id, source_message_id, source_message_ids, scene_name,
                            metadata_json, memory_layer, memcell_id, memory_type, support_count,
                            resolution_status, facet_path, created_at, updated_at
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            user_key,
                            kind,
                            content,
                            content_hash,
                            json.dumps(tags, ensure_ascii=False),
                            confidence,
                            session_id or None,
                            source_message_id or None,
                            json.dumps(source_message_ids, ensure_ascii=False),
                            scene_name,
                            json.dumps({"layer": "L1", "source": "longcat"}, ensure_ascii=False),
                            memory_layer,
                            commit_memcell_id,
                            memory_type,
                            1,
                            "active",
                            facet_path,
                            now,
                            now,
                        ),
                    )
                    item_id = cur.lastrowid
                    _memory_insert_event(conn, user_key, "memory_create", item_id, {"content": content, "kind": kind})
                _memory_sync_item_fts(conn, item_id)
                _memory_sync_item_unit(conn, item_id, sync_vector=True)
                _memory_supersede_conflicts_for_item(conn, user_key, item_id)
                row = conn.execute(
                    "SELECT * FROM memory_items WHERE user_key = ? AND id = ?",
                    (user_key, item_id),
                ).fetchone()
                if row:
                    _memory_upsert_atomic_fact_for_item(conn, user_key, row, commit_memcell_id)
                    row = conn.execute(
                        "SELECT * FROM memory_items WHERE user_key = ? AND id = ?",
                        (user_key, item_id),
                    ).fetchone()
                    _memory_sync_item_unit(conn, item_id, sync_vector=False)
                    saved_items.append(_memory_row_to_item(row))
                saved += 1
            if saved_items:
                if commit_memcell_id:
                    first_scene = saved_items[0].get("sceneName") or ""
                    if first_scene:
                        conn.execute(
                            "UPDATE memory_memcells SET scene_name = ?, updated_at = ? WHERE user_key = ? AND memcell_id = ?",
                            (_memory_clean_scene_name(first_scene), now, user_key, commit_memcell_id),
                        )
                _memory_rebuild_scenes_for_user(conn, user_key)
                _memory_refresh_profile(conn, user_key)
                if commit_memcell_id:
                    _memory_build_episode_for_memcell(conn, user_key, commit_memcell_id, saved_items[0].get("sceneName") or "")
            consolidation = _memory_consolidate_user(conn, user_key, force=False)
            conn.commit()
        finally:
            conn.close()

    user_content, assistant_content = _memory_latest_turn(recent_messages)
    tdai_capture = _memory_tencentdb_capture(user_key, session_id, user_content, assistant_content, recent_messages)

    return jsonify({
        "success": True,
        "persist": True,
        "saved": saved,
        "skipped": skipped,
        "items": saved_items,
        "l0Recorded": len(l0_ids),
        "consolidation": consolidation,
        "tdai": tdai_capture,
    })


@app.route('/api/memory/list', methods=['POST'])
def memory_list():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({
            "success": True,
            "persist": False,
            "items": [],
            "threadSummaries": [],
            "atomicFacts": [],
            "episodes": [],
            "foresights": [],
            "candidates": [],
            "locationAnchors": [],
        })
    include_inferred = bool(payload.get("include_inferred") or payload.get("includeInferred"))

    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            _memory_ensure_layers(conn, user_info["user_key"])
            rows = conn.execute(
                f"""
                SELECT * FROM memory_items
                WHERE user_key = ? AND deleted_at IS NULL
                  {"AND memory_layer IN ('explicit', 'inferred')" if include_inferred else "AND memory_layer = 'explicit'"}
                ORDER BY updated_at DESC
                LIMIT 300
                """,
                (user_info["user_key"],),
            ).fetchall()
            summaries = conn.execute(
                """
                SELECT session_id, summary, updated_at FROM thread_summaries
                WHERE user_key = ?
                ORDER BY updated_at DESC
                LIMIT 80
                """,
                (user_info["user_key"],),
            ).fetchall()
            scenes = conn.execute(
                """
                SELECT * FROM memory_scenes
                WHERE user_key = ?
                ORDER BY updated_at DESC
                LIMIT 60
                """,
                (user_info["user_key"],),
            ).fetchall()
            atomic_rows = conn.execute(
                f"""
                SELECT * FROM memory_atomic_facts
                WHERE user_key = ? AND deleted_at IS NULL
                  {"AND memory_layer IN ('explicit', 'inferred')" if include_inferred else "AND memory_layer = 'explicit'"}
                ORDER BY updated_at DESC
                LIMIT 300
                """,
                (user_info["user_key"],),
            ).fetchall()
            episode_rows = conn.execute(
                """
                SELECT * FROM memory_episodes
                WHERE user_key = ? AND deleted_at IS NULL
                ORDER BY updated_at DESC
                LIMIT 120
                """,
                (user_info["user_key"],),
            ).fetchall()
            if not include_inferred:
                episode_rows = [
                    row for row in episode_rows
                    if not (_memory_safe_json(row["metadata_json"], {}).get("layerCounts") or {}).get("inferred")
                ]
            foresight_rows = conn.execute(
                f"""
                SELECT * FROM memory_foresights
                WHERE user_key = ? AND deleted_at IS NULL
                  {"AND memory_layer IN ('explicit', 'inferred')" if include_inferred else "AND memory_layer = 'explicit'"}
                ORDER BY updated_at DESC
                LIMIT 120
                """,
                (user_info["user_key"],),
            ).fetchall()
            candidate_rows = conn.execute(
                """
                SELECT * FROM memory_candidates
                WHERE user_key = ? AND status = 'pending'
                ORDER BY updated_at DESC
                LIMIT 120
                """,
                (user_info["user_key"],),
            ).fetchall()
            location_anchors = _memory_list_location_anchors(conn, user_info["user_key"])
            persona = _memory_get_profile(conn, user_info["user_key"])
            conn.commit()
        finally:
            conn.close()
    return jsonify({
        "success": True,
        "persist": True,
        "items": [_memory_row_to_item(row) for row in rows],
        "threadSummaries": [
            {"sessionId": row["session_id"], "summary": row["summary"], "updatedAt": row["updated_at"]}
            for row in summaries
        ],
        "scenes": [
            {
                "id": row["id"],
                "sceneName": row["scene_name"],
                "summary": row["summary"],
                "keywords": _memory_safe_json(row["keywords"], []),
                "itemIds": _memory_safe_json(row["item_ids"], []),
                "updatedAt": row["updated_at"],
            }
            for row in scenes
        ],
        "atomicFacts": [_memory_row_to_atomic_fact(row) for row in atomic_rows],
        "episodes": [_memory_row_to_episode(row) for row in episode_rows],
        "foresights": [_memory_row_to_foresight(row) for row in foresight_rows],
        "candidates": [_memory_row_to_candidate(row) for row in candidate_rows],
        "locationAnchors": location_anchors,
        "persona": persona,
    })


@app.route('/api/memory/delete', methods=['POST'])
def memory_delete():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({"success": True, "persist": False, "deleted": 0})

    user_key = user_info["user_key"]
    item_id = payload.get("id")
    query = str(payload.get("query") or payload.get("selector") or payload.get("target") or "").strip()
    delete_all = bool(payload.get("all") or payload.get("delete_all") or payload.get("deleteAll"))
    now = _memory_now_ms()
    custom_key = request.headers.get("X-LongCat-Api-Key", "")
    rejected = 0
    selection = {}
    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            if delete_all:
                cur = conn.execute(
                    "UPDATE memory_items SET deleted_at = ?, updated_at = ? WHERE user_key = ? AND deleted_at IS NULL",
                    (now, now, user_key),
                )
                conn.execute("DELETE FROM thread_summaries WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_l0_messages WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_scenes WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_profiles WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_memcells WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_atomic_facts WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_episodes WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_foresights WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_candidates WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_units WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_location_anchors WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM memory_location_secrets WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM session_messages WHERE user_key = ?", (user_key,))
                conn.execute("DELETE FROM session_segments WHERE user_key = ?", (user_key,))
                _memory_rebuild_fts(conn)
                _memory_insert_event(conn, user_key, "memory_delete_all", None, {})
                deleted = cur.rowcount or 0
            elif query:
                item_rows = conn.execute(
                    """
                    SELECT * FROM memory_items
                    WHERE user_key = ? AND deleted_at IS NULL
                    ORDER BY updated_at DESC
                    LIMIT 260
                    """,
                    (user_key,),
                ).fetchall()
                candidate_rows = conn.execute(
                    """
                    SELECT * FROM memory_candidates
                    WHERE user_key = ? AND status = 'pending'
                    ORDER BY updated_at DESC
                    LIMIT 160
                    """,
                    (user_key,),
                ).fetchall()
                selection = _memory_select_deletions_with_llm(query, item_rows, candidate_rows, custom_key=custom_key)
                selected_item_ids = set(selection.get("itemIds") or [])
                selected_candidate_ids = set(selection.get("candidateIds") or [])
                deleted = 0
                if selected_item_ids:
                    placeholders = ",".join("?" for _ in selected_item_ids)
                    params = [now, now, user_key] + list(selected_item_ids)
                    cur = conn.execute(
                        f"""
                        UPDATE memory_items
                        SET deleted_at = ?, updated_at = ?
                        WHERE user_key = ? AND deleted_at IS NULL AND id IN ({placeholders})
                        """,
                        tuple(params),
                    )
                    deleted = cur.rowcount or 0
                    for numeric_id in selected_item_ids:
                        _memory_sync_item_fts(conn, numeric_id)
                        _memory_sync_item_unit(conn, numeric_id, sync_vector=False)
                        _memory_mark_evercore_deleted_for_item(conn, user_key, numeric_id, deleted_at=now)
                if selected_candidate_ids:
                    placeholders = ",".join("?" for _ in selected_candidate_ids)
                    params = [now, user_key] + list(selected_candidate_ids)
                    cur = conn.execute(
                        f"""
                        UPDATE memory_candidates
                        SET status = 'rejected', updated_at = ?
                        WHERE user_key = ? AND status = 'pending' AND candidate_id IN ({placeholders})
                        """,
                        tuple(params),
                    )
                    rejected = cur.rowcount or 0
                    for candidate_id in selected_candidate_ids:
                        row = conn.execute(
                            "SELECT id FROM memory_candidates WHERE user_key = ? AND candidate_id = ?",
                            (user_key, candidate_id),
                        ).fetchone()
                        if row:
                            _memory_sync_candidate_fts(conn, row["id"])
                if deleted:
                    _memory_rebuild_scenes_for_user(conn, user_key)
                    _memory_refresh_profile(conn, user_key)
                    _memory_rebuild_evercore_for_user(conn, user_key)
                    _memory_rebuild_units_for_user(conn, user_key, sync_vector=False)
                _memory_insert_event(conn, user_key, "memory_delete_by_query", None, {
                    "query": query[:400],
                    "itemIds": list(selected_item_ids),
                    "candidateIds": list(selected_candidate_ids),
                    "deleted": deleted,
                    "rejected": rejected,
                    "reason": selection.get("reason") or "",
                })
            else:
                candidate_id = ""
                if isinstance(item_id, str) and item_id.startswith("candidate:"):
                    candidate_id = item_id.split(":", 1)[1].strip()
                if candidate_id:
                    row = conn.execute(
                        "SELECT id FROM memory_candidates WHERE user_key = ? AND candidate_id = ? AND status = 'pending'",
                        (user_key, candidate_id),
                    ).fetchone()
                    if not row:
                        return jsonify({"success": False, "error": "候选记忆不存在"}), 404
                    cur = conn.execute(
                        "UPDATE memory_candidates SET status = 'rejected', updated_at = ? WHERE user_key = ? AND candidate_id = ? AND status = 'pending'",
                        (now, user_key, candidate_id),
                    )
                    _memory_sync_candidate_fts(conn, row["id"])
                    _memory_rebuild_units_for_user(conn, user_key, sync_vector=False)
                    _memory_insert_event(conn, user_key, "memory_candidate_reject", None, {"candidateId": candidate_id})
                    deleted = cur.rowcount or 0
                else:
                    try:
                        numeric_id = int(item_id)
                    except Exception:
                        return jsonify({"success": False, "error": "缺少有效记忆 ID"}), 400
                    cur = conn.execute(
                        "UPDATE memory_items SET deleted_at = ?, updated_at = ? WHERE user_key = ? AND id = ? AND deleted_at IS NULL",
                        (now, now, user_key, numeric_id),
                    )
                    if cur.rowcount:
                        _memory_sync_item_fts(conn, numeric_id)
                        _memory_sync_item_unit(conn, numeric_id, sync_vector=False)
                        _memory_mark_evercore_deleted_for_item(conn, user_key, numeric_id, deleted_at=now)
                        _memory_rebuild_scenes_for_user(conn, user_key)
                        _memory_refresh_profile(conn, user_key)
                        _memory_rebuild_evercore_for_user(conn, user_key)
                        _memory_rebuild_units_for_user(conn, user_key, sync_vector=False)
                    _memory_insert_event(conn, user_key, "memory_delete", numeric_id, {})
                    deleted = cur.rowcount or 0
            conn.commit()
        finally:
            conn.close()
    return jsonify({
        "success": True,
        "persist": True,
        "deleted": deleted,
        "rejected": rejected,
        "selection": selection,
    })


@app.route('/api/memory/update', methods=['POST'])
def memory_update():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({"success": True, "persist": False, "updated": 0})

    try:
        item_id = int(payload.get("id"))
    except Exception:
        return jsonify({"success": False, "error": "缺少有效记忆 ID"}), 400

    content = re.sub(r"\s+", " ", str(payload.get("content") or "").strip())
    if len(content) < 8 or len(content) > 800:
        return jsonify({"success": False, "error": "记忆内容长度不合适"}), 400
    if not _memory_sensitive_category_allowed(content, explicit=True):
        return jsonify({"success": False, "error": "记忆内容包含敏感信息，已拒绝保存"}), 400
    safe_for_prompt, unsafe_reason = _memory_safe_for_prompt(content)
    if not safe_for_prompt and unsafe_reason in {"prompt_injection", "secret", "control_char"}:
        return jsonify({"success": False, "error": "记忆内容疑似提示词注入或敏感信息，已拒绝保存"}), 400

    kind = str(payload.get("kind") or "note").strip().lower()[:40] or "note"
    if kind not in {"profile", "preference", "project", "constraint", "note"}:
        kind = "note"
    tags = payload.get("tags") if isinstance(payload.get("tags"), list) else []
    tags = [str(tag).strip()[:40] for tag in tags if str(tag).strip()][:12]
    confidence = max(0.1, min(float(payload.get("confidence") or 0.78), 1.0))
    scene_name = _memory_clean_scene_name(payload.get("scene") or payload.get("sceneName") or _memory_infer_scene_name(kind, content, tags))
    memory_type = _memory_classify_memory_type(kind, content, tags)
    partition = _memory_partition_for(kind, memory_type, tags, scene_name, content)
    facet_path = _memory_facet_path_for(kind, content, tags, partition)
    content_hash = _memory_content_hash(kind, content)
    now = _memory_now_ms()

    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            duplicate = conn.execute(
                "SELECT id FROM memory_items WHERE user_key = ? AND content_hash = ? AND id != ? AND deleted_at IS NULL",
                (user_info["user_key"], content_hash, item_id),
            ).fetchone()
            if duplicate:
                return jsonify({"success": False, "error": "已有相同记忆"}), 409
            cur = conn.execute(
                """
                UPDATE memory_items
                SET kind = ?, content = ?, content_hash = ?, tags = ?, confidence = ?,
                    scene_name = ?, memory_type = ?, metadata_json = ?,
                    resolution_status = 'active', conflict_group_id = '', supersedes_item_id = NULL,
                    facet_path = ?, updated_at = ?, deleted_at = NULL
                WHERE user_key = ? AND id = ? AND deleted_at IS NULL
                """,
                (
                    kind,
                    content,
                    content_hash,
                    json.dumps(tags, ensure_ascii=False),
                    confidence,
                    scene_name,
                    memory_type,
                    json.dumps({"layer": "L1", "source": "manual_update"}, ensure_ascii=False),
                    facet_path,
                    now,
                    user_info["user_key"],
                    item_id,
                ),
            )
            if not cur.rowcount:
                return jsonify({"success": False, "error": "记忆不存在"}), 404
            _memory_sync_item_fts(conn, item_id)
            _memory_sync_item_unit(conn, item_id, sync_vector=True)
            _memory_supersede_conflicts_for_item(conn, user_info["user_key"], item_id)
            row = conn.execute(
                "SELECT * FROM memory_items WHERE user_key = ? AND id = ?",
                (user_info["user_key"], item_id),
            ).fetchone()
            if row:
                memcell_id = _memory_ensure_item_memcell(conn, user_info["user_key"], row)
                _memory_upsert_atomic_fact_for_item(conn, user_info["user_key"], row, memcell_id)
                _memory_build_episode_for_memcell(conn, user_info["user_key"], memcell_id, scene_name)
            _memory_rebuild_scenes_for_user(conn, user_info["user_key"])
            _memory_refresh_profile(conn, user_info["user_key"])
            _memory_rebuild_evercore_for_user(conn, user_info["user_key"])
            _memory_rebuild_units_for_user(conn, user_info["user_key"], sync_vector=False)
            _memory_insert_event(conn, user_info["user_key"], "memory_manual_update", item_id, {
                "content": content,
                "kind": kind,
            })
            conn.commit()
        finally:
            conn.close()
    return jsonify({"success": True, "persist": True, "updated": 1})


@app.route('/api/memory/consolidate', methods=['POST'])
def memory_consolidate():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({"success": True, "persist": False, "consolidated": False})

    force = bool(payload.get("force"))
    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            result = _memory_consolidate_user(conn, user_info["user_key"], force=force)
            conn.commit()
        finally:
            conn.close()
    return jsonify({"success": True, "persist": True, "consolidated": bool(result.get("ran")), "result": result})


@app.route('/api/agent/run', methods=['POST'])
def agent_run_commit():
    payload = request.get_json(silent=True) or {}
    user_info = _memory_normalize_user(payload)
    if not user_info["persist"]:
        return jsonify({"success": True, "persist": False})

    run = payload.get("run") if isinstance(payload.get("run"), dict) else payload
    run_id = str(run.get("id") or "").strip()[:160]
    if not run_id:
        return jsonify({"success": False, "error": "缺少 run id"}), 400
    session_id = str(payload.get("session_id") or payload.get("sessionId") or run.get("sessionId") or "").strip()[:160]
    now = _memory_now_ms()
    with MEMORY_DB_LOCK:
        conn = _memory_connect()
        try:
            conn.execute(
                """
                INSERT INTO agent_runs(
                    run_id, user_key, session_id, status, input, plan, framework,
                    tool_pool, command_graph, blackboard, events, observations,
                    started_at, completed_at, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(run_id)
                DO UPDATE SET status = excluded.status,
                    input = excluded.input,
                    plan = excluded.plan,
                    framework = excluded.framework,
                    tool_pool = excluded.tool_pool,
                    command_graph = excluded.command_graph,
                    blackboard = excluded.blackboard,
                    events = excluded.events,
                    observations = excluded.observations,
                    completed_at = excluded.completed_at,
                    updated_at = excluded.updated_at
                """,
                (
                    run_id,
                    user_info["user_key"],
                    session_id or None,
                    str(run.get("status") or "unknown")[:40],
                    str(run.get("input") or "")[:4000],
                    json.dumps(run.get("plan") or {}, ensure_ascii=False),
                    json.dumps(run.get("framework") or {}, ensure_ascii=False),
                    json.dumps(run.get("toolPool") or run.get("tool_pool") or {}, ensure_ascii=False),
                    json.dumps(run.get("commandGraph") or run.get("command_graph") or {}, ensure_ascii=False),
                    json.dumps(run.get("blackboard") or {}, ensure_ascii=False),
                    json.dumps(run.get("events") or [], ensure_ascii=False),
                    json.dumps(run.get("observations") or [], ensure_ascii=False),
                    int(run.get("startedAt") or now),
                    int(run.get("completedAt") or 0) or None,
                    now,
                    now,
                ),
            )
            conn.commit()
        finally:
            conn.close()
    return jsonify({"success": True, "persist": True})



@app.route('/', methods=['GET'])
def serve_index():
    """Serve the main local UI from the same backend origin."""
    return send_from_directory(BASE_DIR, 'index.html')


@app.route('/manifest.webmanifest', methods=['GET'])
def serve_manifest():
    """Serve the PWA manifest with the correct MIME type."""
    manifest_path = os.path.join(BASE_DIR, 'manifest.webmanifest')
