@app.route('/api/favicon', methods=['GET'])
def favicon_proxy():
    """Serve cached site favicons without depending on overseas favicon aggregators."""
    domain = _normalize_favicon_domain(request.args.get("domain") or request.args.get("url") or "")
    try:
        size = max(16, min(64, int(request.args.get("size") or 16)))
    except Exception:
        size = 16
    if not domain:
        return Response("", status=404)

    cached = _read_favicon_cache(domain, size)
    if cached:
        data, content_type = cached
        response = Response(data, mimetype=content_type)
        response.headers["Cache-Control"] = "public, max-age=2592000, stale-while-revalidate=15552000, immutable"
        return response

    for url in _favicon_site_icon_urls(domain):
        try:
            fetched = _fetch_favicon_candidate(url)
            if not fetched:
                continue
            data, content_type = fetched
            _write_favicon_cache(domain, size, data, content_type)
            response = Response(data, mimetype=content_type)
            response.headers["Cache-Control"] = "public, max-age=2592000, stale-while-revalidate=15552000, immutable"
            return response
        except Exception:
            continue
    return Response("", status=404)


@app.route('/convert', methods=['POST'])
def convert_file():
    """接收文件并使用 MarkItDown 转换为 Markdown"""
    if 'file' not in request.files:
        return jsonify({'success': False, 'error': '未提供文件'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'success': False, 'error': '文件名为空'}), 400

    # 检查文件扩展名
    _, ext = os.path.splitext(file.filename.lower())
    if ext not in SUPPORTED_EXTENSIONS:
        return jsonify({
            'success': False,
            'error': f'不支持的文件格式: {ext}',
            'supported': list(SUPPORTED_EXTENSIONS)
        }), 400

    # 获取文件类型分类
    file_type = FILE_TYPE_MAP.get(ext, 'file')

    try:
        # 将上传文件保存到临时目录
        with tempfile.NamedTemporaryFile(delete=False, suffix=ext) as tmp:
            file.save(tmp.name)
            tmp_path = tmp.name

        # 计算文件大小
        file_size = os.path.getsize(tmp_path)
        payload = convert_source(
            tmp_path,
            filename=file.filename,
            file_type=file_type,
            file_size=file_size,
            extension=ext
        )

        # 清理临时文件
        os.unlink(tmp_path)

        return jsonify(payload)

    except Exception as e:
        # 确保清理临时文件
        if 'tmp_path' in locals() and os.path.exists(tmp_path):
            os.unlink(tmp_path)
        return jsonify({
            'success': False,
            'error': f'文件转换失败: {str(e)}'
        }), 500


@app.route('/convert-url', methods=['POST'])
def convert_url():
    """Convert an http(s) URL directly through MarkItDown."""
    payload = request.get_json(silent=True) or {}
    url = (payload.get('url') or '').strip()
    parsed = urlparse(url)

    if not url:
        return jsonify({'success': False, 'error': '未提供链接'}), 400
    if parsed.scheme not in {'http', 'https'} or not parsed.netloc:
        return jsonify({'success': False, 'error': '仅支持 http/https 链接'}), 400

    filename = os.path.basename(parsed.path.rstrip('/')) or parsed.netloc

    try:
        tmp_path = ''
        final_url = url
        content_type = ''
        downloaded_size = 0
        try:
            tmp_path, final_url, content_type, downloaded_size = _download_remote_pdf(url)
        except Exception:
            tmp_path = ''

        if tmp_path:
            try:
                result = convert_source(
                    tmp_path,
                    filename=os.path.basename(urlparse(final_url).path.rstrip('/')) or filename,
                    file_type='pdf',
                    file_size=downloaded_size,
                    extension='.pdf'
                )
            finally:
                if os.path.exists(tmp_path):
                    os.unlink(tmp_path)
        else:
            result = convert_source(
                url,
                filename=filename,
                file_type='pdf' if _looks_like_pdf_url(url) else 'link',
                file_size=0,
                extension='.pdf' if _looks_like_pdf_url(url) else ''
            )

        result['metaLabel'] = parsed.netloc
        result['finalUrl'] = final_url
        result['contentType'] = content_type
        return jsonify(result)
    except Exception as e:
        return jsonify({
            'success': False,
            'error': f'链接解析失败: {str(e)}'
        }), 500


@app.route('/group/list', methods=['POST'])
def group_list():
    payload = request.get_json(silent=True) or {}
    user = _normalize_group_user(payload)
    auth_error = _reject_anonymous_group_user(user)
    if auth_error:
        return auth_error
    with GROUP_DATA_LOCK:
        data = _read_group_data()
        groups = [
            _public_group(group)
            for group in data.get("groups", {}).values()
            if _require_group_member(group, user)
        ]
    groups.sort(key=lambda item: item.get("updatedAt") or 0, reverse=True)
    return jsonify({"success": True, "groups": groups})


@app.route('/group/create', methods=['POST'])
def group_create():
    payload = request.get_json(silent=True) or {}
    user = _normalize_group_user(payload)
    auth_error = _reject_anonymous_group_user(user)
    if auth_error:
        return auth_error
    title = str(payload.get("title") or "").strip()[:80]
    desc = str(payload.get("desc") or "").strip()[:500]
    invite_code = str(payload.get("invite_code") or payload.get("inviteCode") or "").strip()[:80]

    if not invite_code:
        return jsonify({"success": False, "error": "请填写邀请码"}), 400

    now = _now_ms()
    with GROUP_DATA_LOCK:
        data = _read_group_data()
        invite_index = data.setdefault("invite_index", {})
        groups = data.setdefault("groups", {})
        existing_id = invite_index.get(invite_code)

        if existing_id and existing_id in groups:
            group = groups[existing_id]
            is_new_member = _add_group_member(group, user)
            group["updated_at"] = now
            if is_new_member:
                _append_group_system_message(
                    group,
                    f"欢迎 {user.get('name') or '新成员'} 加入「{group.get('title') or '群聊'}」。在群里 @LongCat，我会参考上下文一起回复。",
                    now,
                )
            _write_group_data(data)
            return jsonify({
                "success": True,
                "joinedExisting": True,
                "group": _public_group(group),
            })

        if not title or not desc:
            return jsonify({"success": False, "error": "创建新群聊需要填写名称和用途"}), 400

        group_id = f"grp_{uuid.uuid4().hex[:18]}"
        group = {
            "id": group_id,
            "title": title,
            "desc": desc,
            "invite_code": invite_code,
            "created_at": now,
            "updated_at": now,
            "owner_id": user["id"],
            "members": {},
            "messages": [],
        }
        _add_group_member(group, user)
        groups[group_id] = group
        invite_index[invite_code] = group_id
        _write_group_data(data)

    return jsonify({"success": True, "joinedExisting": False, "group": _public_group(group)})


