@app.route('/group/messages', methods=['POST'])
def group_messages():
    payload = request.get_json(silent=True) or {}
    user = _normalize_group_user(payload)
    auth_error = _reject_anonymous_group_user(user)
    if auth_error:
        return auth_error
    group_id = str(payload.get("group_id") or payload.get("groupId") or "").strip()
    if not group_id:
        return jsonify({"success": False, "error": "缺少群聊 ID"}), 400

    with GROUP_DATA_LOCK:
        data = _read_group_data()
        group = (data.get("groups") or {}).get(group_id)
        if not group:
            return jsonify({"success": False, "error": "群聊不存在"}), 404
        if not _require_group_member(group, user):
            return jsonify({"success": False, "error": "尚未加入该群聊"}), 403
