@app.route('/browser/action', methods=['POST'])
def browser_action():
    """Execute a browser action (navigate, click, type, etc.)"""
    data = request.get_json(silent=True) or {}
    action_type = data.get('action')
    params = data.get('params', {})
    
    if not action_type:
        return jsonify({'success': False, 'error': '未提供操作类型'}), 400
        
    try:
        observation = run_async(harness.execute_action(action_type, params))
        observation = enrich_browser_observation(observation)
        if observation.get('screenshot'):
            preview_stream.publish_frame(_preview_stream_source(), observation)
        elif isinstance(observation.get('state'), dict) and observation['state'].get('screenshot'):
            preview_stream.publish_frame(_preview_stream_source(), observation['state'])
        has_error = bool(observation.get('error'))
        has_state = isinstance(observation.get('state'), dict)
        has_screenshot = bool(
            observation.get('screenshot') or
            (has_state and observation['state'].get('screenshot'))
        )

        if has_error and not has_screenshot:
            return jsonify({
                'success': False,
                'error': observation['error'],
                'observation': observation
            }), 207

        return jsonify({
            'success': not has_error,
            'observation': observation
        }), 200 if not has_error else 207
    except Exception as e:
        return jsonify({
            'success': False,
            'error': f'浏览器操作失败: {str(e)}'
        }), 500


@app.route('/browser/preview', methods=['GET'])
def browser_preview():
    """Return a lightweight screenshot preview for the live browser viewport.
    支持并行搜索模式：自动轮流显示多个搜索页面"""
    try:
        # 检查是否有并行搜索在进行
        parallel_preview = parallel_search_manager.get_current_preview()
        
        if parallel_preview and parallel_preview.get('screenshot'):
            # 并行搜索模式：返回当前轮转的页面
            return jsonify({
                'success': True,
                'observation': {
                    'screenshot': parallel_preview['screenshot'],
                    'url': parallel_preview['url'],
                    'title': f"[{parallel_preview['rotation_index']+1}/{parallel_preview['total_pages']}] {parallel_preview['query']}",
                    'parallel_mode': True,
                    'page_id': parallel_preview['page_id'],
                    'status': parallel_preview['status']
                },
                'parallel_info': {
                    'query': parallel_preview['query'],
                    'rotation_index': parallel_preview['rotation_index'],
                    'total_pages': parallel_preview['total_pages'],
                    'findings_count': parallel_preview['findings_count']
                }
            }), 200
        
        # 普通模式
        observation = run_async(harness.get_preview())

        if observation.get('error'):
            return jsonify({
                'success': False,
                'error': observation['error'],
                'observation': observation,
            }), 500

        if observation.get('screenshot'):
            preview_stream.publish_frame(_preview_stream_source(), observation)

        return jsonify({
            'success': True,
            'observation': observation,
        }), 200
    except Exception as e:
        return jsonify({
            'success': False,
            'error': f'浏览器预览失败: {str(e)}'
        }), 500


@app.route('/browser/preview/stream', methods=['GET'])
def browser_preview_stream():
    """Push live preview frames over SSE; fall back gracefully when unsupported."""
    if _parallel_preview_active():
        def fallback_stream():
            yield _sse_message('fallback', {
                'reason': 'parallel-preview-active',
                'message': '并行搜索预览仍使用旧轮询通道',
            })

        return Response(
            stream_with_context(fallback_stream()),
            mimetype='text/event-stream',
            headers={
                'Cache-Control': 'no-cache',
                'X-Accel-Buffering': 'no',
            },
        )

    source = _preview_stream_source()
    subscriber_id, event_queue, latest_event = preview_stream.subscribe(source=source)
    latest_frame_event = preview_stream.get_latest_frame(source)

    def generate():
        stream_started = False
        stream_started_at = None
        try:
            yield 'retry: 1000\n\n'
            yield _sse_message('status', {'source': source, 'mode': 'sse'})

            if latest_frame_event:
                yield _sse_message('frame', _serialize_preview_stream_event(latest_frame_event))
            if latest_event and latest_event != latest_frame_event:
                yield _sse_message(latest_event.get('event', 'status'), _serialize_preview_stream_event(latest_event))

            stream_started, result = _start_preview_stream_source(source)
            if not stream_started:
                yield _sse_message('fallback', {
                    'reason': result.get('reason') or 'preview-stream-unsupported',
                    'source': result.get('source') or harness.browser_source,
                    'message': result.get('error') or '当前浏览器通道不支持 CDP 推流，已回退到轮询',
                })
                return

            first_frame_received = latest_frame_event is not None
            stream_started_at = time.time()

            while True:
                try:
                    event = event_queue.get(timeout=5)
                    if event.get('event') == 'frame':
                        first_frame_received = True
                    yield _sse_message(event.get('event', 'status'), _serialize_preview_stream_event(event))
                except queue.Empty:
                    if not first_frame_received and stream_started_at and (time.time() - stream_started_at) >= 2.5:
                        if not preview_stream.get_latest_frame(source):
                            yield _sse_message('fallback', {
                                'reason': 'preview-stream-timeout',
                                'message': 'CDP 推流未及时返回首帧，已回退到轮询',
                            })
                            return
                    yield ': keepalive\n\n'
        finally:
            preview_stream.unsubscribe(subscriber_id)
            if preview_stream.subscriber_count(source) == 0:
                try:
                    _stop_preview_stream_source(source)
                except Exception:
                    pass

    return Response(
        stream_with_context(generate()),
        mimetype='text/event-stream',
        headers={
            'Cache-Control': 'no-cache',
            'X-Accel-Buffering': 'no',
        },
    )

