@app.route('/browser/parallel-search', methods=['POST'])
def browser_parallel_search():
    """
    启动并行搜索，同时搜索多个query
    请求体: {"queries": ["query1", "query2", "query3"]}
    """
    try:
        data = request.get_json() or {}
        queries = data.get('queries', [])
        
        if not queries or len(queries) == 0:
            return jsonify({
                'success': False,
                'error': '请提供至少一个搜索查询'
            }), 400
        
        # 限制并行数量
        if len(queries) > 3:
            queries = queries[:3]
        
        # 启动并行搜索
        page_ids = run_async(parallel_search_manager.start_parallel_search(queries))
        
        return jsonify({
            'success': True,
            'page_ids': page_ids,
            'queries': queries,
            'message': f'已启动 {len(queries)} 个并行搜索任务'
        }), 200
    except Exception as e:
        return jsonify({
            'success': False,
            'error': f'并行搜索启动失败: {str(e)}'
        }), 500


