@app.route('/aps/search', methods=['POST'])
def aps_search():
    """Search academic papers for the LongCat /APS command."""
    data = request.get_json(silent=True) or {}
    raw_query = (data.get("query") or "").strip()
    try:
        query, sources, max_results, year = _normalize_paper_search_args(data)
    except ValueError as e:
        return jsonify({'success': False, 'error': str(e)}), 400

    try:
        payload = _search_papers_direct(query, sources, max_results, year, original_query=raw_query)
    except Exception as e:
        return jsonify({
            'success': False,
            'error': f'APS 搜索失败: {str(e)}',
            'query': query,
            'original_query': raw_query,
            'sources': sources,
        }), 500

    return jsonify({
        'success': True,
        'error': '',
        'query': payload.get('query') or query,
        'original_query': raw_query or query,
        'sources': sources,
        'max_results': max_results,
        'year': payload.get('year') or year,
        'data': payload,
        'warnings': '',
    }), 200


