@app.route('/aps/reader/asset', methods=['GET'])
def aps_reader_asset():
    """Proxy paper images so arXiv figures render reliably inside the local reader."""
    url = (request.args.get("url") or "").strip()
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return jsonify({'success': False, 'error': '图片链接格式不正确'}), 400
    try:
        data, content_type = _download_reader_asset(url)
    except Exception as e:
        return jsonify({'success': False, 'error': f'图片读取失败: {str(e)}'}), 502
    response = Response(data, mimetype=content_type)
    response.headers["Cache-Control"] = "public, max-age=86400"
    return response


@app.route('/aps/mineru/asset/<cache_id>/<path:asset_path>', methods=['GET'])
def aps_mineru_asset(cache_id, asset_path):
    """Serve image assets extracted from MinerU result ZIPs."""
    if not re.match(r"^[a-f0-9]{16,64}$", cache_id or ""):
        return jsonify({'success': False, 'error': '资源缓存 ID 不正确'}), 400
    safe_path = _safe_zip_path(unquote(asset_path or ""), require_image=True)
    if not safe_path:
        return jsonify({'success': False, 'error': '资源路径不正确'}), 400
    root = os.path.abspath(os.path.join(MINERU_ASSET_CACHE_DIR, cache_id))
    target = os.path.abspath(os.path.join(root, *safe_path.split("/")))
    if target != root and not target.startswith(root + os.sep):
        return jsonify({'success': False, 'error': '资源路径越界'}), 400
    if not os.path.isfile(target):
        return jsonify({'success': False, 'error': '资源不存在'}), 404
    with open(target, "rb") as handle:
        data = handle.read()
    content_type = mimetypes.guess_type(target)[0] or "application/octet-stream"
    response = Response(data, mimetype=content_type)
    response.headers["Cache-Control"] = "public, max-age=604800, immutable"
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response


@app.route('/aps/reader/pdf-proxy', methods=['GET'])
@app.route('/aps/reader/pdf-proxy/<path:filename>', methods=['GET'])
def aps_reader_pdf_proxy(filename=""):
    """Public PDF proxy used when MinerU cannot reliably fetch arXiv directly."""
    url = (request.args.get("url") or "").strip()
    parsed = urlparse(url)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return jsonify({'success': False, 'error': 'PDF 链接格式不正确'}), 400
    if not _is_known_reader_pdf_url(parsed):
        return jsonify({'success': False, 'error': '仅允许代理官方论文 PDF'}), 403
    try:
        cache_path = _ensure_pdf_proxy_cache(url, timeout=75)
        with open(cache_path, "rb") as handle:
            data = handle.read()
    except Exception as e:
        return jsonify({'success': False, 'error': f'PDF 代理读取失败: {str(e)}'}), 502
    response = Response(data, mimetype="application/pdf")
    response.headers["Cache-Control"] = "public, max-age=86400"
    response.headers["Content-Disposition"] = f'inline; filename="{filename or "paper.pdf"}"'
    response.headers["X-Content-Type-Options"] = "nosniff"
    return response


