@app.route('/aps/mineru/start', methods=['POST'])
def aps_mineru_start():
    """Create a MinerU parse task for a paper PDF/HTML."""
    data = request.get_json(silent=True) or {}
    url = (data.get("url") or "").strip()
    model_version = (data.get("model_version") or data.get("modelVersion") or MINERU_DEFAULT_MODEL).strip()
    if model_version not in {MINERU_DEFAULT_MODEL, "pipeline", MINERU_HTML_MODEL}:
        model_version = MINERU_DEFAULT_MODEL
    if not url:
        return jsonify({'success': False, 'error': '未提供解析链接'}), 400
    try:
        payload = _create_mineru_task(url, model_version)
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500
    return jsonify({'success': True, **payload}), 200


