# ---------- Travel Agent APIs ----------
_travel_coordinator = TravelCoordinator()


@app.route('/travel/intake', methods=['POST'])
def travel_intake():
    """Create a travel session and generate the intake questionnaire."""
    data = request.get_json(silent=True) or {}
    goal = (data.get('goal') or '').strip()
    if not goal:
        return jsonify({'success': False, 'error': 'Goal is required'}), 400
    try:
        session = travel_harness.create(goal)
        questionnaire, decisions = _travel_coordinator.run_intake(goal)
        session.questionnaire = questionnaire
        session.status = 'intake'
        for d in decisions:
            session.log(d.agent_name, d.action, d.data)
        travel_harness.update(session.id, questionnaire=questionnaire, status='intake')
        duration = _extract_duration(goal)
        return jsonify({
            'success': True,
            'session_id': session.id,
            'questionnaire': questionnaire,
            'prefilled': {
                'duration': duration,
            } if duration else {},
        }), 200
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/travel/session/<session_id>', methods=['GET'])
def travel_session(session_id: str):
    """Get current travel session state."""
    session = travel_harness.get(session_id)
    if not session:
        return jsonify({'success': False, 'error': 'Session not found'}), 404
    return jsonify({'success': True, 'session': session.to_dict()}), 200


@app.route('/travel/answer', methods=['POST'])
def travel_answer():
    """Submit one or more answers; if complete, trigger planning."""
    data = request.get_json(silent=True) or {}
    session_id = (data.get('session_id') or '').strip()
    answers = data.get('answers')
    if not session_id:
        return jsonify({'success': False, 'error': 'session_id is required'}), 400
    session = travel_harness.get(session_id)
    if not session:
        return jsonify({'success': False, 'error': 'Session not found'}), 404
    if not isinstance(answers, list):
        return jsonify({'success': False, 'error': 'answers must be a list'}), 400

    # Merge new answers
    merged = list(session.answers or [])
    merged.extend(answers)
    travel_harness.update(session_id, answers=merged)

    questionnaire = session.questionnaire or {}
    qs = questionnaire.get('questions') or []
    # If we have answers for all questions, run the full multi-agent pipeline in background
    if len(merged) >= len(qs) and qs:
        def _plan_in_background(sid: str, g: str, ans: list):
            s = travel_harness.get(sid)
            if not s:
                return
            try:
                def _log_decision(d):
                    s.log(d.agent_name, d.action, d.data)

                plan, _ = _travel_coordinator.run_full_pipeline(g, ans, on_decision=_log_decision)
                travel_harness.update(sid, plan=plan, status='done')
            except Exception as e:
                travel_harness.update(sid, status='failed', error=str(e))

        travel_harness.update(session_id, status='planning')
        session.log('PlannerAgent', 'plan_start', {'step': 1})
        threading.Thread(
            target=_plan_in_background,
            args=(session_id, session.goal, merged),
            daemon=True,
        ).start()
        return jsonify({
            'success': True,
            'session_id': session_id,
            'status': 'planning',
            'latest_agent': 'PlannerAgent',
            'latest_event': 'plan_start',
        }), 200

    return jsonify({
        'success': True,
        'session_id': session_id,
        'status': 'intake',
        'answers_received': len(merged),
        'total_questions': len(qs),
    }), 200



