@app.route('/travel/status/<session_id>', methods=['GET'])
def travel_status(session_id: str):
    """Poll planning status for the travel session."""
    session = travel_harness.get(session_id)
    if not session:
        return jsonify({'success': False, 'error': 'Session not found'}), 404

    latest = session.agent_log[-1] if session.agent_log else None
    return jsonify({
        'success': True,
        'session_id': session_id,
        'status': session.status,
        'latest_agent': latest['agent'] if latest else None,
        'latest_event': latest['event'] if latest else None,
        'plan': session.plan if session.status == 'done' else None,
        'error': session.error,
    }), 200


